def _pond_cells(pond):
    cc, cr, rc, rr = pond
    return {(c, r) for c in range(COLS) for r in range(ROWS)
            if ((c + 0.5 - cc) / rc) ** 2 + ((r + 0.5 - cr) / rr) ** 2 <= 1.0}


def _land_cells(blobs):
    """The islands on a sea map, as (centre col, centre row, half width,
    half height) blobs - the same shape a pond is, used the other way up."""
    out = set()
    for cc, cr, rc, rr in blobs:
        out |= {(c, r) for c in range(COLS) for r in range(ROWS)
                if ((c + 0.5 - cc) / rc) ** 2
                + ((r + 0.5 - cr) / rr) ** 2 <= 1.0}
    return out


def _road_cells(wps):
    cells = set()
    for i in range(len(wps) - 1):
        c0, r0 = wps[i]
        c1, r1 = wps[i + 1]
        if c0 == c1:
            step = 1 if r1 > r0 else -1
            for r in range(int(r0), int(r1) + step, step):
                cells.add((int(c0), r))
        else:
            step = 1 if c1 > c0 else -1
            for c in range(int(c0), int(c1) + step, step):
                cells.add((c, int(r0)))
    return {(c, r) for (c, r) in cells if 0 <= c < COLS and 0 <= r < ROWS}


class WorldMap:
    """One sector: its routes, its water, and what can be built on."""

    def __init__(self, d):
        self.key = d["key"]
        self.ground = Route(d["ground"])
        self.air = Route(d["air"])
        self.beast = Route(d["beast"])
        # a lane of its own for anything that swims. Sectors without one
        # put their hulls on the road, the way they always did.
        self.sealane = Route(d["sealane"]) if d.get("sealane") else None
        self.hq = d["hq"]
        self.fortress = d["fortress"]
        self.obstacles = set(d["obstacles"])
        # cut stone: a curtain wall and its towers. Blocked like an
        # obstacle, drawn like a castle.
        self.walls = set(d.get("walls", ()))
        self.towers = set(d.get("towers", ()))
        self.city = set(d.get("city", ()))
        # RINGS OF BUILDABLE GROUND OUTSIDE THE GRID. Nought everywhere
        # but the capital, whose land reaches far enough past the board
        # that leaving it unbuildable made it look like water you were
        # being refused. Cells here are ordinary ground: no road, no
        # obstacle, nothing blocked, just further out.
        self.pad = int(d.get("pad", 0))
        self.pal = PALETTES[d.get("palette", "island")]
        self.pond_def = d["pond"]
        self.road = _road_cells(d["ground"])
        self.sea = bool(d.get("sea"))
        if d.get("sea"):
            # Mostly water: the whole grid is sea except the lane itself and
            # the islands the fighting happens on. `pond_def` is still an
            # ellipse because the water art is drawn from one - it just
            # names the deepest part now rather than the only part.
            self.land = _land_cells(d.get("land", ()))
            self.pond = {(c, r) for c in range(COLS) for r in range(ROWS)
                         } - self.land
        else:
            self.land = None
            self.pond = _pond_cells(d["pond"])
        # the gate is a hole in the city, not a building the road goes under
        self.city -= self.road
        self.bridge = self.pond & self.road
        self.water = self.pond - self.road
        # THE HOSTILE CITY IS GROUND YOU MAY HOLD. It is three columns
        # down the left edge of the castle map - forty-two cells of it -
        # and it used to be as solid as the water. It is a place now: the
        # houses are scenery you build among rather than a wall you build
        # behind, and taking a gun that far forward is a real decision
        # because it is standing where they come out.
        #
        # Everything that is actually IN the way still is - the road, the
        # curtain walls, the map's own towers, the water and the post -
        # and two of the city's cells are wall, so those stay shut.
        self.blocked = (self.road | self.obstacles | self.walls
                        | self.towers | self.water | {self.hq})
        self.terrain = None


