# ----------------------------------------------------------------------------
# AUDIO  (procedurally synthesised - no asset files required)
# ----------------------------------------------------------------------------

class SoundBank:
    RATE = 22050

    def __init__(self):
        self.ok = False
        self.sounds = {}
        try:
            # pygame.init() has already claimed the mixer at its own defaults
            # by the time we get here, and pre_init on a live mixer does
            # nothing - which left every effect authored at 22050 mono being
            # read as 44100 stereo, i.e. played FOUR TIMES TOO FAST. Drop the
            # mixer first so the settings below are the ones that take.
            init = pygame.mixer.get_init()
            if init and (init[0] != self.RATE or init[2] != 1):
                # only tear it down if it is actually the wrong format;
                # quitting a mixer that is already right is a good way to
                # upset a live audio device for no reason
                try:
                    pygame.mixer.quit()
                except Exception:
                    pass
                init = None
            if not init:
                pygame.mixer.pre_init(self.RATE, -16, 1, 512)
                pygame.mixer.init(self.RATE, -16, 1, 512)
            pygame.mixer.set_num_channels(24)
            self._build()
            self.ok = True
        except Exception:
            self.ok = False

    def _snd(self, samples, vol):
        buf = array('h', (clamp(int(s * 20000), -32000, 32000) for s in samples))
        s = pygame.mixer.Sound(buffer=buf.tobytes())
        s.set_volume(vol)
        return s

    def _build(self):
        r = self.RATE
        rnd = random.Random(7)

        def noise(dur, decay, lp=0.0, tone=0.0, tone_f=200.0):
            n = int(r * dur)
            out = []
            prev = 0.0
            for i in range(n):
                t = i / r
                env = math.exp(-t * decay)
                v = rnd.uniform(-1, 1)
                if lp > 0:
                    v = prev + (v - prev) * lp
                    prev = v
                if tone > 0:
                    v = v * (1 - tone) + math.sin(2 * math.pi * tone_f * t) * tone
                out.append(v * env)
            return out

        self.sounds['mg'] = self._snd(noise(0.07, 60, 0.5, 0.15, 900), 0.16)
        self.sounds['auto'] = self._snd(noise(0.09, 45, 0.35, 0.2, 420), 0.18)
        self.sounds['sniper'] = self._snd(noise(0.22, 22, 0.25, 0.1, 260), 0.28)
        self.sounds['mortar'] = self._snd(noise(0.30, 14, 0.12, 0.25, 120), 0.30)
        self.sounds['missile'] = self._snd(noise(0.35, 11, 0.30, 0.3, 700), 0.22)
        self.sounds['boom'] = self._snd(noise(0.55, 8, 0.08, 0.12, 70), 0.34)
        self.sounds['zap'] = self._snd(noise(0.14, 30, 0.9, 0.5, 1400), 0.14)

        def beep(f1, f2, dur, vol):
            n = int(r * dur)
            out = []
            for i in range(n):
                t = i / r
                f = lerp(f1, f2, t / dur)
                env = min(1.0, t * 40) * math.exp(-t * 6)
                out.append(math.sin(2 * math.pi * f * t) * env * 0.6)
            return self._snd(out, vol)

        self.sounds['build'] = beep(420, 760, 0.16, 0.35)
        self.sounds['upgrade'] = beep(520, 980, 0.22, 0.35)
        self.sounds['sell'] = beep(700, 300, 0.18, 0.30)
        self.sounds['deny'] = beep(240, 160, 0.16, 0.30)
        self.sounds['wave'] = beep(300, 540, 0.45, 0.40)
        self.sounds['leak'] = beep(360, 120, 0.5, 0.45)
    def play(self, name, chance=1.0):
        if not self.ok:
            return
        if chance < 1.0 and random.random() > chance:
            return
        s = self.sounds.get(name)
        if s:
            try:
                s.play()
            except Exception:
                pass


# ----------------------------------------------------------------------------
# MUSIC  (also synthesised - the score is code, not a file)
#
# THE MOTIF. Five notes, stored as intervals and rhythm with no key, tempo or
# instrument attached, so the same idea can be a warning in one place and a
# dirge in another. The signature is the second interval: the fifth slipping
# DOWN a semitone. That fall is what the ear remembers.
# ----------------------------------------------------------------------------
MOTIF = [(0, 1.0), (7, 0.5), (6, 0.5), (3, 1.0), (0, 1.0)]


def m_inverted(m=MOTIF):
    return [(-p, d) for p, d in m]


def m_augmented(m=MOTIF, f=2.0):
    return [(p, d * f) for p, d in m]


def m_diminished(m=MOTIF, f=0.5):
    return [(p, d * f) for p, d in m]


def m_hardened(m=MOTIF):
    """Flatten the third: the same shape with the last softness taken out."""
    return [(p - 1 if p == 3 else p, d) for p, d in m]


def semi(name):
    """'A2' -> semitones from A4."""
    steps = {"C": -9, "D": -7, "E": -5, "F": -4, "G": -2, "A": 0, "B": 2}
    n = steps[name[0].upper()]
    i = 1
    while i < len(name) and name[i] in "#b":
        n += 1 if name[i] == "#" else -1
        i += 1
    return n + (int(name[i:]) - 4) * 12


def mhz(st):
    return 440.0 * (2.0 ** (st / 12.0))


class Score:
    """A mono buffer things are mixed into, at the mixer's own rate."""

    def __init__(self, seconds, rate):
        self.rate = rate
        self.buf = [0.0] * int(rate * seconds)

    def add(self, at, samples, gain=1.0):
        i0 = int(at * self.rate)
        buf = self.buf
        n = len(buf)
        for j, v in enumerate(samples):
            k = i0 + j
            if 0 <= k < n:
                buf[k] += v * gain

    def to_bytes(self, chans=1, peak=0.72):
        """The finished score as raw PCM.

        Deliberately NOT a pygame Sound: this runs on a worker thread, and
        creating an SDL object off the main thread takes the process down
        with it. The main thread turns these bytes into a Sound when it
        picks them up.

        `chans` must be the MIXER's channel count - a buffer is interpreted
        using the mixer's format, not the one it was written at, and getting
        that wrong plays the piece at a quarter of its length.

        The dead air at the end is trimmed off here. Everything in this
        score loops for ever, so whatever is at the end butts onto the
        front once a loop - and every piece was allocating a second or
        two more tail than its last note needed."""
        buf = self.buf
        top = max(1e-9, max(abs(v) for v in buf))
        # ---- trim the dead air off the end -----------------------------
        # Scan back in 10ms blocks to the last one that has anything in
        # it, keep a moment past that for the decay, and fade the last
        # 25ms to nothing so the join onto the front is silent-to-silent
        # instead of a step.
        blk = max(1, int(self.rate * 0.010))
        floor = top * 0.004
        cut = len(buf)
        least = int(self.rate * 5.0)         # never trim it to nothing
        while cut - blk > least and max(
                abs(v) for v in buf[cut - blk:cut]) < floor:
            cut -= blk
        cut = min(len(buf), cut + int(self.rate * 0.10))
        buf = buf[:cut]
        fade = min(cut, int(self.rate * 0.025))
        for i in range(cut - fade, cut):
            buf[i] *= (cut - i) / float(fade)
        sc = peak / top
        if chans <= 1:
            data = array('h', (clamp(int(v * sc * 32000), -32000, 32000)
                               for v in buf))
        else:
            data = array('h')
            for v in buf:
                q = clamp(int(v * sc * 32000), -32000, 32000)
                for _ in range(chans):
                    data.append(q)
        return data.tobytes()


class Band:
    """Every instrument in the score. The electric guitar is a Karplus-Strong
    delay line - noise in a buffer one wavelength long, read round and round
    with each sample averaged against its neighbour, which low-passes the
    bright pick attack into a warm tone exactly as a real string does. The
    amplifier is soft clipping, which is what makes it a guitar and not a
    harp."""

    def __init__(self, rate):
        self.rate = rate
        self._cache = {}

    def _env(self, n, a, d, sus, r):
        out = []
        for i in range(n):
            if i < a:
                out.append(i / max(1, a))
            elif i < a + d:
                out.append(1.0 - (1.0 - sus) * (i - a) / max(1, d))
            elif i < n - r:
                out.append(sus)
            else:
                out.append(sus * max(0.0, (n - i) / max(1, r)))
        return out

    def guitar(self, f, dur, drive=6.0, damp=0.996, tone=0.42, seed=1):
        key = (round(f, 1), round(dur, 3), drive, damp, tone, seed)
        got = self._cache.get(key)
        if got is not None:
            return got
        r = self.rate
        n = max(2, int(r / max(20.0, f)))
        rnd = random.Random(seed)
        buf = [rnd.uniform(-1.0, 1.0) for _ in range(n)]
        total = int(r * dur)
        out = [0.0] * total
        j = 0
        prev = 0.0
        for i in range(total):
            v = buf[j]
            buf[j] = (v + buf[(j + 1) % n]) * 0.5 * damp
            j = (j + 1) % n
            v = math.tanh(v * drive)          # the amp
            prev = prev + (v - prev) * tone   # the cabinet
            out[i] = prev
        atk = int(r * 0.004)
        for i in range(min(atk, total)):
            out[i] *= i / max(1, atk)
        rel = int(r * 0.03)
        for i in range(max(0, total - rel), total):
            out[i] *= (total - i) / max(1, rel)
        self._cache[key] = out
        return out

    def chord(self, root, dur, ivs=(0, 7, 12), drive=7.0, damp=0.996,
              tone=0.42):
        mix = None
        for k, iv in enumerate(ivs):
            v = self.guitar(mhz(root + iv), dur, drive, damp, tone, 1 + k)
            if mix is None:
                mix = list(v)
            else:
                for i in range(min(len(mix), len(v))):
                    mix[i] += v[i]
        return [x / len(ivs) for x in mix]

    def chug(self, root, dur, drive=10.5):
        return self.chord(root, dur, (0, 7, 12), drive, 0.955)

    def bass(self, f, dur):
        r = self.rate
        n = int(r * dur)
        e = self._env(n, int(r * 0.006), int(r * 0.10), 0.72, int(r * 0.05))
        out = []
        for i in range(n):
            t = i / r
            ph = (t * f) % 1.0
            out.append(((1.0 if ph < 0.5 else -1.0) * 0.55
                        + math.sin(2 * math.pi * f * 0.5 * t) * 0.45)
                       * e[i] * 0.5)
        return out

    def pad(self, freqs, dur):
        r = self.rate
        n = int(r * dur)
        e = self._env(n, int(r * 0.45), int(r * 0.2), 0.85, int(r * 0.7))
        out = [0.0] * n
        rnd = random.Random(4)
        for f in freqs:
            for h, amp in ((1, 1.0), (2, 0.30), (3, 0.12)):
                ph = rnd.random() * 6.283
                for i in range(n):
                    out[i] += math.sin(2 * math.pi * f * h * i / r + ph) * amp
        k = len(freqs) * 3.0
        return [v / k * e[i] for i, v in enumerate(out)]

    def kick(self, dur=0.34):
        r = self.rate
        return [math.sin(2 * math.pi * (132 * math.exp(-(i / r) * 25) + 43)
                         * (i / r)) * math.exp(-(i / r) * 8.5)
                for i in range(int(r * dur))]

    def snare(self, dur=0.24, seed=3):
        r = self.rate
        rnd = random.Random(seed)
        out, prev = [], 0.0
        for i in range(int(r * dur)):
            t = i / r
            v = rnd.uniform(-1, 1)
            v = prev + (v - prev) * 0.55
            prev = v
            body = (math.sin(2 * math.pi * 185 * t)
                    + math.sin(2 * math.pi * 278 * t) * 0.5) * 0.3
            out.append((v * 0.85 + body) * math.exp(-t * 17))
        return out

    def hat(self, seed=5, open_=False):
        r = self.rate
        rnd = random.Random(seed)
        n = int(r * (0.22 if open_ else 0.05))
        out, prev = [], 0.0
        for i in range(n):
            v = rnd.uniform(-1, 1)
            out.append((v - prev) * math.exp(-(i / r) * (14 if open_ else 68)))
            prev = v
        return out

    def crash(self, dur=1.1, seed=8, reverse=False):
        r = self.rate
        rnd = random.Random(seed)
        n = int(r * dur)
        out, prev = [], 0.0
        for i in range(n):
            v = rnd.uniform(-1, 1)
            out.append((v - prev * 0.6) * math.exp(-(i / r) * 3.2))
            prev = v
        if reverse:
            return [out[n - 1 - i] * ((i / n) ** 1.3) for i in range(n)]
        return out

    def tom(self, f, dur=0.26):
        r = self.rate
        return [math.sin(2 * math.pi * f * (1.0 + 0.55
                                            * math.exp(-(i / r) * 22)) * (i / r))
                * math.exp(-(i / r) * 7.0) for i in range(int(r * dur))]

    def riser(self, dur=1.2, seed=21):
        r = self.rate
        rnd = random.Random(seed)
        n = int(r * dur)
        out, prev = [], 0.0
        for i in range(n):
            f = i / n
            v = rnd.uniform(-1, 1)
            prev = prev + (v - prev) * (0.02 + 0.55 * f * f)
            out.append(prev * (f ** 2.2))
        return out

    def squeal(self, f, dur=0.42):
        r = self.rate
        base = self.guitar(f * 3.0, dur, 16.0, 0.9985, 0.62, 9)
        return [v * (1.0 + 0.012 * math.sin(2 * math.pi * 6.5 * i / r))
                for i, v in enumerate(base)]

    def horn(self, f, dur, bite=0.35):
        """Brass. A stack of harmonics pushed into soft clip, with a bloom
        on the front instead of an attack - the one voice here that is
        neither plucked nor struck, which is what lets a march be carried
        on it rather than hammered out."""
        key = ("horn", round(f, 1), round(dur, 3), round(bite, 2))
        got = self._cache.get(key)
        if got is not None:
            return got
        r = self.rate
        n = int(r * dur)
        e = self._env(n, int(r * 0.085), int(r * 0.13), 0.80, int(r * 0.30))
        out = [0.0] * n
        for h, amp in ((1, 1.0), (2, 0.44), (3, 0.31), (4, 0.17),
                       (5, 0.11), (6, 0.06)):
            w = 2 * math.pi * f * h / r
            for i in range(n):
                out[i] += math.sin(w * i) * amp
        out = [math.tanh(v * (0.46 + bite)) * e[i] * 0.62
               for i, v in enumerate(out)]
        self._cache[key] = out
        return out

    def bell(self, f, dur, seed=2):
        """Struck metal. INHARMONIC - the partials are not whole multiples
        of anything, each one decays at its own rate, and the loudest of
        them is not the note. That is the whole difference between a bell
        and a guitar, and it is why one of them sounds like a band and the
        other like a ceremony."""
        key = ("bell", round(f, 1), round(dur, 3), seed)
        got = self._cache.get(key)
        if got is not None:
            return got
        r = self.rate
        n = int(r * dur)
        out = [0.0] * n
        rnd = random.Random(seed)
        # hum, prime, TIERCE, quint, nominal, and two above that. The
        # tierce is the loudest - a real bell is a minor third that only
        # sounds like the note it is named after.
        for mult, amp, dk in ((0.50, 0.52, 1.3), (1.00, 0.50, 2.0),
                              (1.19, 1.00, 2.7), (1.51, 0.66, 3.5),
                              (2.01, 0.80, 4.3), (2.66, 0.30, 6.0),
                              (3.42, 0.16, 7.8)):
            w = 2 * math.pi * f * mult / r
            ph = rnd.random() * 6.283
            g = amp
            step = math.exp(-dk / r)
            for i in range(n):
                out[i] += math.sin(w * i + ph) * g
                g *= step
        atk = int(r * 0.0022)
        for i in range(min(atk, n)):
            out[i] *= i / max(1, atk)
        out = [v * 0.30 for v in out]
        self._cache[key] = out
        return out

    def lead(self, sc, at, mot, root, bpm, gain, drive=7.0, ivs=(0, 7)):
        """The motif as twin lead - two or three guitars in harmony, which is
        the difference between a riff and an anthem."""
        beat = 60.0 / bpm
        t = at
        for p, d in mot:
            sc.add(t, self.chord(root + p, d * beat * 0.95, ivs, drive,
                                 0.998, 0.52), gain)
            t += d * beat
        return t


def build_siege_theme(rate, chans=1):
    """BLOOD RED SIEGE, and chapter three. Gallops from the first bar."""
    b = Band(rate)
    BPM, BARS = 118, 16
    beat = 60.0 / BPM
    bar = beat * 4
    sc = Score(BARS * bar + 1.2, rate)
    A2, A3, A4 = semi("A2"), semi("A3"), semi("A4")
    ROOTS = [A2, A2, semi("F2"), semi("G2")]
    CH = {A2: ["A3", "C4", "E4"], semi("F2"): ["F3", "A3", "C4"],
          semi("G2"): ["G3", "B3", "D4"]}
    sc.add(0.0, b.crash(bar * 0.9, reverse=True), 0.30)
    for i in range(BARS):
        t0 = i * bar
        root = ROOTS[(i // 2) % 4] if i >= 4 else A2
        stage = min(3, i // 4)
        for e in range(8):
            if e == 7 and i % 4 == 3:
                continue
            g = 0.62 + 0.10 * stage
            sc.add(t0 + e * beat * 0.5, b.chug(root, beat * 0.30), g)
            sc.add(t0 + (e * 0.5 + 0.34) * beat, b.chug(root, beat * 0.13),
                   g * 0.55)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], bar * 0.98),
               0.26 + 0.05 * stage)
        for e in range(4):
            sc.add(t0 + e * beat, b.bass(mhz(root - 12), beat * 0.88), 0.46)
        if i >= 1:
            for e in range(4):
                sc.add(t0 + e * beat, b.kick(), 0.86)
                if i >= 8:
                    sc.add(t0 + (e + 0.5) * beat, b.kick(), 0.52)
                if e in (1, 3):
                    sc.add(t0 + e * beat, b.snare(), 0.46)
                sc.add(t0 + e * beat, b.hat(), 0.17)
                sc.add(t0 + (e + 0.5) * beat,
                       b.hat(6, open_=(e == 3 and i % 2 == 1)), 0.14)
        if i % 4 == 0:
            sc.add(t0, b.crash(), 0.38)
        if i == 2:
            b.lead(sc, t0, MOTIF, A3, BPM, 0.88, 6.0)
        if i == 6:
            b.lead(sc, t0, MOTIF, A3, BPM, 0.92, 7.5, (0, 3, 12))
            sc.add(t0 + 3.4 * beat, b.squeal(mhz(A3), 0.5), 0.40)
        if i in (10, 11):
            b.lead(sc, t0, m_hardened(m_diminished(MOTIF)), A4, BPM, 0.80,
                   8.5)
        if i == 14:
            b.lead(sc, t0, MOTIF, A3, BPM, 1.0, 9.0, (0, 3, 12))
        if i % 4 == 3:
            sc.add(t0 + 2.0 * beat, b.riser(bar * 0.5), 0.30)
            for j, f in enumerate((175, 148, 124, 104, 88, 74)):
                sc.add(t0 + (2.5 + j * 0.25) * beat, b.tom(f), 0.48)
    return sc.to_bytes(chans)


def build_grey_hour(rate, chans=1):
    """THE GREY HOUR. What plays under the menu and under every sector
    that does not own a piece of its own - which, before it existed, was
    eleven of the thirteen and the whole of the menu, in silence.

    Slow, heavy and mechanical. The other two pieces are guitar riffs at
    118 and 176; this is 76, the guitar is one chug on the downbeat, and
    the tune is the MOTIF inverted and augmented - the same five notes,
    upside down and at twice the length."""
    b = Band(rate)
    BPM, BARS = 76, 15
    beat = 60.0 / BPM
    bar = beat * 4
    sc = Score(BARS * bar + 1.6, rate)
    A2, A3 = semi("A2"), semi("A3")
    # A minor, and it never resolves upward: i - VI - VII - i
    ROOTS = [A2, A2, semi("F2"), semi("G2")]
    CH = {A2: ["A3", "C4", "E4"], semi("F2"): ["F3", "A3", "C4"],
          semi("G2"): ["G3", "B3", "D4"]}
    FIG = m_augmented(m_inverted(MOTIF))
    sc.add(0.0, b.crash(bar * 1.1, reverse=True), 0.22)
    for i in range(BARS):
        t0 = i * bar
        root = ROOTS[i % 4]
        stage = min(3, i // 4)
        last = (i == BARS - 1)
        # the drone under all of it - the one thing that never stops
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], bar * 0.99),
               0.30 + 0.05 * stage)
        sc.add(t0, b.bass(mhz(root - 12), bar * 0.52), 0.52)
        if not last:
            sc.add(t0 + 2 * beat, b.bass(mhz(root - 12), bar * 0.44), 0.44)
        # ...and the weight on the downbeat. ONE chug a bar: any more and
        # it stops being heavy and starts being a riff.
        if i >= 1 and not last:
            sc.add(t0, b.chug(root, beat * 0.62), 0.58 + 0.08 * stage)
            if i >= 6:
                sc.add(t0 + 2 * beat, b.chug(root, beat * 0.40),
                       0.40 + 0.06 * stage)
        # the machine: two on the floor, and a tick where the fourth
        # beat would be if anything were in a hurry
        if i >= 1:
            for e in (0, 2):
                sc.add(t0 + e * beat, b.kick(0.40), 0.90 if not last else 0.70)
            if i >= 3 and not last:
                sc.add(t0 + 2 * beat, b.snare(0.30), 0.34 + 0.06 * stage)
                sc.add(t0 + 3.5 * beat, b.tom(96, 0.22), 0.40)
            if i >= 5 and not last:
                for e in range(4):
                    sc.add(t0 + (e + 0.5) * beat, b.hat(9), 0.11 + 0.02 * stage)
        # the figure, inverted and stretched, low and unhurried
        if i in (2, 6):
            b.lead(sc, t0, FIG, A2 + 12, BPM, 0.62, 4.5, (0, 7))
        if i == 10:
            b.lead(sc, t0, m_hardened(FIG), A3, BPM, 0.74, 6.0, (0, 3, 12))
        if i == 13:
            b.lead(sc, t0, FIG, A3, BPM, 0.80, 6.5, (0, 7, 12))
            sc.add(t0 + 3.2 * beat, b.squeal(mhz(A3), 0.62), 0.26)
        if i in (0, 5, 10):
            sc.add(t0, b.crash(1.4), 0.30)
        if i == 9:                      # the one lift in it
            sc.add(t0 + 2.0 * beat, b.riser(bar * 0.9), 0.30)
            for j, f in enumerate((150, 128, 108, 92)):
                sc.add(t0 + (2.6 + j * 0.30) * beat, b.tom(f, 0.30), 0.42)
    return sc.to_bytes(chans)


def build_vengeance(rate, chans=1):
    """THE VENGEANCE. The VERMILION VENGEANCE's own theme - the one piece
    in this game that belongs to a single machine rather than to a sector.

    It used to be a RECORDING, and the only file this game shipped.
    Everything else in here is generated, so now this is too: the build
    has no assets in it at all, and nothing in it anybody has to hold a
    licence for.

    Its shape is the thing worth keeping, and no other piece here has it.
    It does not open as a fight. Twenty-two seconds of ceremony at 66 -
    bells, a horn, the motif stretched to twice its length - which is the
    sound of something ARRIVING rather than something attacking. Then it
    stops dead: three quarters of a second of true silence, the only real
    silence anywhere in this score, and long enough to be a mistake.

    Then 184, which is faster than anything else written here including
    the finale's own fight at 176, and it does not let up again. On the
    loop the fight drops back into the ceremony, which is the right way
    round for a machine that keeps coming back."""
    b = Band(rate)
    I_BPM, I_BARS = 66, 6
    D_BPM, D_BARS = 184, 26
    GAP = 0.75
    ib = 60.0 / I_BPM
    ibar = ib * 4
    db = 60.0 / D_BPM
    dbar = db * 4
    DROP = I_BARS * ibar + GAP
    sc = Score(DROP + D_BARS * dbar + 1.6, rate)
    A2, A3, A4 = semi("A2"), semi("A3"), semi("A4")
    # the fight themes' own roots - this is the Blood Red coming back, and
    # it should be built out of the Blood Red
    ROOTS = [A2, semi("A#2"), A2, semi("G2")]
    CH = {A2: ["A3", "C4", "E4"], semi("A#2"): ["A#3", "D4", "F4"],
          semi("G2"): ["G3", "B3", "D4"]}
    FIG = m_augmented(MOTIF)

    # ---- I. IT ARRIVES -------------------------------------------------
    sc.add(0.0, b.crash(ibar * 1.2, reverse=True), 0.22)
    for i in range(I_BARS):
        t0 = i * ibar
        root = ROOTS[i % 4]
        stage = min(3, i // 2)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], ibar * 0.99),
               0.32 + 0.04 * stage)
        sc.add(t0, b.horn(mhz(root + 12), ibar * 0.90, 0.22 + 0.06 * stage),
               0.30 + 0.05 * stage)
        sc.add(t0, b.bass(mhz(root - 12), ibar * 0.55), 0.48)
        for e in (0, 2):
            sc.add(t0 + e * ib, b.bell(mhz(root + 24), 2.6,
                                       2 if e == 0 else 4),
                   0.28 if e == 0 else 0.20)
        if i >= 2:
            sc.add(t0, b.kick(0.48), 0.72)
        if i >= 3:
            sc.add(t0 + 2 * ib, b.tom(92, 0.30), 0.34)
        if i in (1, 4):
            t = t0
            for p, d in FIG:
                sc.add(t, b.bell(mhz(A4 + p), min(3.0, d * ib * 1.3)),
                       0.26 + 0.04 * stage)
                t += d * ib
        # ...and the last bar winds up and hands over to nothing
        if i == I_BARS - 1:
            sc.add(t0, b.riser(ibar * 0.94), 0.40)
            for j, f in enumerate((150, 126, 104, 86, 72)):
                sc.add(t0 + (1.6 + j * 0.42) * ib, b.tom(f, 0.26),
                       0.40 + j * 0.03)

    # ---- II. AND THEN IT DOES NOT STOP ---------------------------------
    # Nothing at all is written between the last tom and here. That gap
    # is the whole piece: a boss theme that pauses long enough for you to
    # think it is over.
    for i in range(D_BARS):
        t0 = DROP + i * dbar
        root = ROOTS[i % 4]
        stage = min(3, i // 7)
        last = (i == D_BARS - 1)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], dbar * 0.98),
               0.22 + 0.03 * stage)
        if not last:
            for j in range(16):
                if j % 8 == 7 and i % 2:
                    continue
                sc.add(t0 + j * db * 0.25, b.chug(root, db * 0.21, 11.5),
                       0.62 + 0.06 * stage)
        for e in range(4):
            sc.add(t0 + e * db, b.bass(mhz(root - 12), db * 0.90), 0.54)
        if not last:
            for e in range(8):
                sc.add(t0 + e * db * 0.5, b.kick(0.26),
                       0.88 if e % 2 == 0 else 0.58)
                if i >= 14:
                    sc.add(t0 + (e * 0.5 + 0.25) * db, b.kick(0.22), 0.44)
                if e in (2, 6):
                    sc.add(t0 + e * db * 0.5, b.snare(0.22), 0.54)
                sc.add(t0 + e * db * 0.5, b.hat(29, open_=(e == 7)), 0.16)
        else:
            sc.add(t0, b.kick(0.42), 0.70)
        if i % 4 == 0:
            sc.add(t0, b.crash(1.1), 0.40 if i == 0 else 0.32)
        if i == 0:              # the first bar of it lands hardest
            sc.add(t0, b.chord(root, db * 1.9, (0, 7, 12), 10.0), 0.72)
            sc.add(t0 + 2.2 * db, b.squeal(mhz(A4), 0.7), 0.44)
        if i in (3, 7, 17, 21):
            b.lead(sc, t0, m_hardened(m_diminished(MOTIF)), A4, D_BPM,
                   0.88, 8.5, (0, 3, 12))
        if i in (11, 12):
            b.lead(sc, t0, m_hardened(MOTIF), A4, D_BPM, 0.92, 9.5,
                   (0, 3, 12))
        if i == 24:
            sc.add(t0 + 2.0 * db, b.riser(dbar * 0.7), 0.34)
            for j, f in enumerate((190, 158, 130, 106, 88)):
                sc.add(t0 + (2.3 + j * 0.24) * db, b.tom(f, 0.20), 0.50)
    return sc.to_bytes(chans)


def build_three_flags(rate, chans=1):
    """THREE FLAGS. Chapter two, where the war stops being one country's.

    A march rather than a riff: 88, kick on one and three, snare on two
    and four, and a DOUBLE STROKE off the last beat of every bar, which
    is the thing that makes a drum a parade instead of a backbeat. The
    chords fall instead of circling - i, VII, VI, V, and the V is MAJOR,
    which is the oldest way of writing something that will not stop.

    What makes it chapter two is that the tune refuses to stay in one
    key. The MOTIF is stated three times - once in A, once in C, once in
    D - one flag each, climbing. And at the end two of them play it at
    once, a minor third apart, because Crimson and Azure and Amber
    arriving together is three armies playing the same anthem out of
    tune with each other."""
    b = Band(rate)
    BPM, BARS = 88, 16
    beat = 60.0 / BPM
    bar = beat * 4
    sc = Score(BARS * bar + 1.5, rate)
    A2, A3, C4, D4 = semi("A2"), semi("A3"), semi("C4"), semi("D4")
    ROOTS = [A2, semi("G2"), semi("F2"), semi("E2")]
    CH = {A2: ["A3", "C4", "E4"], semi("G2"): ["G3", "B3", "D4"],
          semi("F2"): ["F3", "A3", "C4"], semi("E2"): ["E3", "G#3", "B3"]}
    FIG = m_hardened(MOTIF)

    def horns(t, mot, root, gain):
        """The motif on brass, in fifths - a bugle call takes no thirds."""
        for p, d in mot:
            sc.add(t, b.horn(mhz(root + p), d * beat * 0.94, 0.48), gain)
            sc.add(t, b.horn(mhz(root + p + 7), d * beat * 0.94, 0.42),
                   gain * 0.60)
            t += d * beat
        return t

    sc.add(0.0, b.crash(bar * 0.8, reverse=True), 0.24)
    for i in range(BARS):
        t0 = i * bar
        root = ROOTS[i % 4]
        stage = min(3, i // 4)
        last = (i == BARS - 1)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], bar * 0.99),
               0.26 + 0.04 * stage)
        sc.add(t0, b.horn(mhz(root + 12), bar * 0.84, 0.28 + 0.06 * stage),
               0.30 + 0.05 * stage)
        for e in (0, 2, 3):
            sc.add(t0 + e * beat, b.bass(mhz(root - 12), beat * 0.78), 0.46)
        if not last:
            for e in (0, 2):
                sc.add(t0 + e * beat, b.chug(root, beat * 0.46),
                       0.42 + 0.07 * stage)
        if i >= 1:
            for e in (0, 2):
                sc.add(t0 + e * beat, b.kick(0.36), 0.84)
            for e in (1, 3):
                sc.add(t0 + e * beat, b.snare(0.22), 0.42 + 0.05 * stage)
            if not last:
                for j in range(2):
                    sc.add(t0 + (3.5 + j * 0.25) * beat,
                           b.snare(0.13, 7 + j * 2), 0.28 + j * 0.07)
            if i >= 8:
                for e in range(4):
                    sc.add(t0 + e * beat, b.hat(11), 0.12 + 0.02 * stage)
        if i % 4 == 0:
            sc.add(t0, b.crash(1.2), 0.28)
        # ---- the flags, one key at a time, then two at once ------------
        if i == 3:
            b.lead(sc, t0, FIG, A3, BPM, 0.56, 5.0, (0, 7))
        if i == 7:
            horns(t0, FIG, C4, 0.42)
        if i == 11:
            b.lead(sc, t0, FIG, D4, BPM, 0.66, 6.5, (0, 7, 12))
        if i == 13:
            sc.add(t0 + 2.2 * beat, b.riser(bar * 0.62), 0.28)
            for j, f in enumerate((158, 132, 110, 92)):
                sc.add(t0 + (2.6 + j * 0.26) * beat, b.tom(f, 0.26), 0.42)
        if i == 14:
            b.lead(sc, t0, FIG, A3, BPM, 0.70, 7.0, (0, 7, 12))
            horns(t0, FIG, C4, 0.44)
    return sc.to_bytes(chans)


def build_last_light(rate, chans=1):
    """LAST LIGHT. Chapter four - she made the call, and they answered.

    The slowest thing in this score at 64, and the ONLY one that resolves
    upward. Everything else here is written to sit on you: i - VI - VII
    and round again, never arriving. This goes i - VI - III - VII and
    finishes on A MAJOR, because the chapter it plays under is the one
    where help turns up.

    The MOTIF augmented and NOT inverted, so the fifth still climbs
    before it slips - at this tempo that stops being a warning and turns
    into something being remembered. It is carried on bells, and the
    guitar never once chugs: it holds a clean chord and lets it ring."""
    b = Band(rate)
    BPM, BARS = 64, 14
    beat = 60.0 / BPM
    bar = beat * 4
    sc = Score(BARS * bar + 2.2, rate)
    A2, A3, A4 = semi("A2"), semi("A3"), semi("A4")
    ROOTS = [A2, semi("F2"), semi("C3"), semi("G2")]
    CH = {A2: ["A3", "C4", "E4"], semi("F2"): ["F3", "A3", "C4"],
          semi("C3"): ["C4", "E4", "G4"], semi("G2"): ["G3", "B3", "D4"]}
    LIFT = ["A3", "C#4", "E4"]              # A major: the answer
    FIG = m_augmented(MOTIF)

    def bells(t, mot, root, gain):
        for p, d in mot:
            sc.add(t, b.bell(mhz(root + p), min(2.8, d * beat * 1.25)), gain)
            t += d * beat
        return t

    sc.add(0.0, b.crash(bar * 0.7, reverse=True), 0.18)
    for i in range(BARS):
        t0 = i * bar
        last = (i == BARS - 1)
        stage = min(3, i // 4)
        names = LIFT if last else CH[ROOTS[i % 4]]
        root = A2 if last else ROOTS[i % 4]
        sc.add(t0, b.pad([mhz(semi(x)) for x in names], bar * 0.99),
               0.34 + 0.04 * stage)
        sc.add(t0, b.bass(mhz(root - 12), bar * 0.60), 0.42)
        # clean, not driven - it rings rather than bites
        sc.add(t0, b.chord(root + 12, beat * 3.1, (0, 7, 12), 3.0, 0.9985,
                           0.62), 0.30 + 0.04 * stage)
        if last:
            sc.add(t0, b.bell(mhz(A3), 3.4), 0.34)
            sc.add(t0, b.kick(0.44), 0.58)
            continue
        if i >= 2:
            sc.add(t0, b.kick(0.44), 0.72)
        if i >= 4:
            sc.add(t0 + 2 * beat, b.tom(88, 0.30), 0.30)
        if i >= 6:
            for e in range(4):
                sc.add(t0 + (e + 0.5) * beat, b.hat(13), 0.08)
        if i % 4 == 0:
            sc.add(t0, b.bell(mhz(root + 24), 2.4), 0.24)
        # ---- the figure. Bells, then the guitar, and the last statement
        # is a MAJOR triad - the one place in this whole score where the
        # third is not flattened.
        if i in (2, 6):
            bells(t0, FIG, A4, 0.30)
        if i == 9:
            b.lead(sc, t0, FIG, A3, BPM, 0.44, 3.6, (0, 7))
        if i == 11:
            b.lead(sc, t0, FIG, A3, BPM, 0.52, 4.0, (0, 4, 7))
            bells(t0, FIG, A4, 0.26)
    return sc.to_bytes(chans)


def build_thin_air(rate, chans=1):
    """THIN AIR. Chapter five, going up to find out why the sun is blue.

    The only piece in this score that is not in four. THREE beats to a
    bar at 96 - a waltz turning slowly, not a machine running - and the
    kick is gone for the first two thirds of it, because the ground
    drops away and only comes back when you look down. When it does
    return it lands on beats one and three of a bar that only has three,
    so it never falls in the same place twice.

    A minor with a SHARP FOURTH sitting high in the pad. That one note
    is the difference between a sky that is open and a sky that is
    wrong, and it is the whole reason this chapter is a mystery instead
    of a holiday."""
    b = Band(rate)
    BPM, BARS = 96, 24
    beat = 60.0 / BPM
    bar = beat * 3
    sc = Score(BARS * bar + 2.0, rate)
    A2, A5 = semi("A2"), semi("A5")
    ROOTS = [A2, semi("C3"), semi("E3"), semi("D3")]
    # the tritone sits at the TOP of the chord, where it glitters instead
    # of muddying the root
    CH = {A2: ["A3", "C4", "E4", "D#5"],
          semi("C3"): ["C4", "E4", "G4"],
          semi("E3"): ["E4", "G4", "B4"],
          semi("D3"): ["D4", "F4", "A4"]}
    FIG = m_diminished(m_inverted(MOTIF))

    def bells(t, mot, root, gain):
        for p, d in mot:
            sc.add(t, b.bell(mhz(root + p), min(2.2, d * beat * 2.4)), gain)
            t += d * beat
        return t

    sc.add(0.0, b.crash(bar * 1.4, reverse=True), 0.20)
    for i in range(BARS):
        t0 = i * bar
        root = ROOTS[(i // 2) % 4]
        stage = min(3, i // 6)
        last = (i == BARS - 1)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], bar * 0.99),
               0.36 + 0.03 * stage)
        sc.add(t0, b.bass(mhz(root - 12), bar * 0.70), 0.30)
        # harmonics, not a chord: almost no drive and it rings for ever
        sc.add(t0, b.chord(root + 24, bar * 0.88, (0, 7), 2.4, 0.9990,
                           0.72), 0.24 + 0.03 * stage)
        if last:
            sc.add(t0, b.bell(mhz(A5 - 12), 2.6), 0.26)
            continue
        if i >= 3:
            for e in range(3):
                sc.add(t0 + e * beat, b.hat(15), 0.09 + 0.02 * stage)
        if i % 4 == 0:
            sc.add(t0, b.tom(120, 0.32), 0.26)
        if i in (8, 16):
            sc.add(t0, b.crash(1.8, reverse=True), 0.22)
        # ---- and the ground comes back ---------------------------------
        if i == 13:
            sc.add(t0, b.riser(bar * 1.9), 0.30)
        if i >= 15:
            sc.add(t0, b.kick(0.38), 0.72)
        if i >= 19:
            sc.add(t0 + 2 * beat, b.kick(0.34), 0.52)
            sc.add(t0 + 1 * beat, b.snare(0.20), 0.22)
        # ---- the figure: high, quick, and gone -------------------------
        if i in (5, 11):
            bells(t0, FIG, A5, 0.30)
        if i == 20:
            bells(t0, FIG, A5, 0.34)
            b.lead(sc, t0, FIG, A5 - 24, BPM, 0.34, 3.2, (0, 7))
    return sc.to_bytes(chans)


def build_undertow(rate, chans=1):
    """THE UNDERTOW. Chapter six, and all of it under water.

    58, and in TWELVE - four beats of three, so nothing lands square.
    Everything arrives slightly late and leaves slowly, which is what
    swell does and what a straight backbeat cannot do at any tempo.

    PHRYGIAN: the second degree is flat, so the chord above the root is
    a semitone up from it. That interval is the oldest way there is of
    writing something large coming up from underneath, and it is why
    this is the only piece here that does not use the same VI and VII as
    the rest of the score.

    Nothing in it is struck if it can be swelled instead. Reversed
    cymbals land ON the bar line rather than after it, the horn holds
    the whole bar, and the guitar never chugs once - it takes a chord
    and lets the water close over it."""
    b = Band(rate)
    BPM, BARS = 58, 12
    beat = 60.0 / BPM
    bar = beat * 4
    trip = beat / 3.0
    sc = Score(BARS * bar + 2.4, rate)
    A2 = semi("A2")
    ROOTS = [A2, semi("A#2"), A2, semi("G2")]
    CH = {A2: ["A3", "C4", "E4"],
          semi("A#2"): ["A#3", "D4", "F4"],
          semi("G2"): ["G3", "A#3", "D4"]}
    FIG = m_augmented(m_hardened(MOTIF))

    def horns(t, mot, root, gain):
        for p, d in mot:
            sc.add(t, b.horn(mhz(root + p), d * beat * 0.96, 0.22), gain)
            t += d * beat
        return t

    for i in range(BARS):
        t0 = i * bar
        root = ROOTS[i % 4]
        stage = min(3, i // 3)
        last = (i == BARS - 1)
        # the swell lands ON the bar line, so it has to start before it
        sc.add(max(0.0, t0 - 1.55), b.crash(1.6, 8, reverse=True),
               0.20 + 0.03 * stage)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], bar * 0.99),
               0.38 + 0.03 * stage)
        sc.add(t0, b.horn(mhz(root - 12), bar * 0.90, 0.18), 0.40)
        sc.add(t0, b.chord(root, bar * 0.80, (0, 7, 12), 6.0, 0.9985,
                           0.38), 0.34 + 0.05 * stage)
        for e in (0.0, 2.5):
            sc.add(t0 + e * beat, b.bass(mhz(root - 24), beat * 1.20), 0.50)
        if last:
            sc.add(t0, b.kick(0.52), 0.56)
            continue
        if i >= 1:
            for e in (0, 2):
                sc.add(t0 + e * beat, b.kick(0.52), 0.74)
        # the roll is in THREES against a bar of four - the hull working
        if i >= 3:
            for e in (1, 3):
                for j in range(3):
                    sc.add(t0 + e * beat + j * trip,
                           b.tom(104 - j * 12, 0.24), 0.30 - j * 0.06)
        if i == 8:
            sc.add(t0, b.riser(bar * 1.5), 0.30)
        # ---- the figure, doubled in length and with the third flattened
        # out of it: the darkest shape the motif has.
        if i == 2:
            horns(t0, FIG, A2 + 12, 0.34)
        if i == 6:
            b.lead(sc, t0, FIG, A2 + 12, BPM, 0.46, 4.2, (0, 7))
        if i == 9:
            b.lead(sc, t0, FIG, A2 + 12, BPM, 0.54, 5.0, (0, 7, 12))
            horns(t0, FIG, A2 + 24, 0.30)
    return sc.to_bytes(chans)


def build_no_ground(rate, chans=1):
    """NO MORE GROUND. Chapter seven: three lanes at once, and none of it
    coming for the HQ - all of it coming for the guns.

    The heaviest of the beds, and the closest to THE GREY HOUR on
    purpose. Same chords, same shape, 92 instead of 76 - this is where
    that first grey morning ends up. What is different is the SEVENTH.
    It is raised: harmonic minor, so the chord under the third bar of
    every phrase is diminished and leans on the root instead of resting
    beside it. Nothing in this piece is allowed to sit still.

    Under all of it is a HORN holding the root for the whole bar, which
    is the one voice THE GREY HOUR has not got, and from the eighth bar
    the guitar stops leaving gaps between chugs. Heavier, not faster.

    And the tune is a CANON. The MOTIF starts; two beats later the same
    MOTIF starts again upside down underneath it, and the two of them
    collide in the middle of the bar. That is what three lanes arriving
    at once sounds like."""
    b = Band(rate)
    BPM, BARS = 92, 16
    beat = 60.0 / BPM
    bar = beat * 4
    sc = Score(BARS * bar + 1.4, rate)
    A2, A3 = semi("A2"), semi("A3")
    ROOTS = [A2, semi("F2"), semi("G#2"), A2]
    CH = {A2: ["A3", "C4", "E4"], semi("F2"): ["F3", "A3", "C4"],
          semi("G#2"): ["G#3", "B3", "D4"]}

    def canon(t, mot, root, gain, drive, ivs):
        """The shape, and the same shape upside down half a bar later."""
        b.lead(sc, t, mot, root, BPM, gain, drive, ivs)
        b.lead(sc, t + 2 * beat, m_inverted(mot), root, BPM, gain * 0.74,
               drive * 0.85, (0, 7))

    sc.add(0.0, b.crash(bar * 0.9, reverse=True), 0.26)
    for i in range(BARS):
        t0 = i * bar
        root = ROOTS[i % 4]
        stage = min(3, i // 4)
        last = (i == BARS - 1)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], bar * 0.99),
               0.28 + 0.04 * stage)
        for e in (0, 2):
            sc.add(t0 + e * beat, b.bass(mhz(root - 12), beat * 1.70), 0.50)
        # the horn under all of it: a siren rather than a voice, and the
        # one thing in here that THE GREY HOUR has not got
        if i >= 2 and not last:
            sc.add(t0, b.horn(mhz(root - 12), bar * 0.94, 0.14),
                   0.26 + 0.05 * stage)
        if not last:
            # and from bar eight it stops leaving gaps
            for e in ((0, 1, 2, 3) if i >= 8 else (0, 2)):
                sc.add(t0 + e * beat, b.chug(root, beat * 0.52),
                       0.54 + 0.07 * stage)
            for e in (1.75, 3.75):          # the pickup that will not rest
                sc.add(t0 + e * beat, b.chug(root, beat * 0.20),
                       0.34 + 0.05 * stage)
        if i >= 2 and not last:
            for e in range(4):
                sc.add(t0 + e * beat, b.kick(0.34), 0.88)
                if i >= 9:
                    sc.add(t0 + (e + 0.5) * beat, b.kick(0.28), 0.48)
            if i >= 4:
                for e in (1, 3):
                    sc.add(t0 + e * beat, b.snare(0.26), 0.46 + 0.05 * stage)
            if i >= 10:                     # the flam into three
                sc.add(t0 + 1.75 * beat, b.snare(0.14, 9), 0.30)
            if i >= 6:
                for e in range(4):
                    sc.add(t0 + (e + 0.5) * beat, b.hat(17), 0.13)
        elif last:
            sc.add(t0, b.kick(0.44), 0.66)
        if i % 4 == 0:
            sc.add(t0, b.crash(1.3), 0.30)
        if i == 4:
            canon(t0, MOTIF, A3, 0.62, 5.5, (0, 7))
        if i == 10:
            canon(t0, m_hardened(MOTIF), A3, 0.74, 7.0, (0, 3, 12))
        if i == 13:
            sc.add(t0 + 2.4 * beat, b.riser(bar * 0.7), 0.30)
            for j, f in enumerate((170, 142, 118, 98, 82)):
                sc.add(t0 + (2.6 + j * 0.22) * beat, b.tom(f, 0.24), 0.46)
        if i == 14:
            canon(t0, m_hardened(MOTIF), A3, 0.82, 8.0, (0, 3, 12))
            sc.add(t0 + 3.3 * beat, b.squeal(mhz(A3), 0.55), 0.24)
    return sc.to_bytes(chans)


def build_the_court(rate, chans=1):
    """THE COURT. What plays in the Red Capital.

    That tour is two hundred waves long, so the loop is the longest one
    here by half again - a short piece under a run that length wears
    through and starts being the sound of waiting.

    Ceremonial rather than military. 80, SIX beats to a bar, and the
    tune moves in PARALLEL FIFTHS - organum, the oldest harmony there
    is, and the only one that sounds like a procession instead of a
    band. Bells on the bar line, a horn under all of it, and for twelve
    bars the guitar does nothing but hold a chord.

    The figure is augmented, which makes it eight beats long against a
    bar of six, so it never starts in the same place twice - it walks
    round the bar the way the Court walks round the city. It is stated
    at each level in turn: low on the horn, in the middle on the bells,
    then both at once. Nothing about it hurries, because the thing it is
    written for does not."""
    b = Band(rate)
    BPM, BARS = 80, 15
    beat = 60.0 / BPM
    bar = beat * 6
    sc = Score(BARS * bar + 2.6, rate)
    A2, A3 = semi("A2"), semi("A3")
    ROOTS = [A2, semi("F2"), semi("G2"), semi("E2"), A2]
    CH = {A2: ["A3", "C4", "E4"], semi("F2"): ["F3", "A3", "C4"],
          semi("G2"): ["G3", "B3", "D4"], semi("E2"): ["E3", "G#3", "B3"]}
    FIG = m_augmented(MOTIF)

    def horns(t, mot, root, gain):
        for p, d in mot:
            sc.add(t, b.horn(mhz(root + p), d * beat * 0.95, 0.26), gain)
            sc.add(t, b.horn(mhz(root + p + 7), d * beat * 0.95, 0.22),
                   gain * 0.58)
            t += d * beat
        return t

    def bells(t, mot, root, gain):
        for p, d in mot:
            sc.add(t, b.bell(mhz(root + p), min(3.2, d * beat * 1.4)), gain)
            sc.add(t, b.bell(mhz(root + p + 7), min(3.2, d * beat * 1.4), 4),
                   gain * 0.55)
            t += d * beat
        return t

    for i in range(BARS):
        t0 = i * bar
        root = ROOTS[i % 5]
        stage = min(3, i // 5)
        last = (i == BARS - 1)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], bar * 0.99),
               0.34 + 0.03 * stage)
        sc.add(t0, b.horn(mhz(root + 12), bar * 0.88, 0.24 + 0.05 * stage),
               0.32 + 0.04 * stage)
        sc.add(t0, b.chord(root + 12, bar * 0.70, (0, 7, 12), 4.6, 0.9988,
                           0.46), 0.28 + 0.04 * stage)
        for e in (0, 3):
            sc.add(t0 + e * beat, b.bass(mhz(root - 12), beat * 2.4), 0.48)
            sc.add(t0 + e * beat,
                   b.bell(mhz(root + 24), 2.6, 2 if e == 0 else 4),
                   0.26 if e == 0 else 0.18)
        if i % 5 == 0:                      # the gong, on the cycle
            sc.add(t0, b.crash(2.8), 0.26)
        if last:
            sc.add(t0, b.kick(0.50), 0.62)
            continue
        if i >= 1:
            for e in (0, 3):
                sc.add(t0 + e * beat, b.kick(0.46), 0.80)
        if i % 5 == 4:
            for j, f in enumerate((128, 108, 90)):
                sc.add(t0 + (4.0 + j * 0.5) * beat, b.tom(f, 0.30), 0.34)
        if i >= 12:                         # and only here does it harden
            for e in (0, 3):
                sc.add(t0 + e * beat, b.chug(root, beat * 0.50), 0.44)
        if i == 2:
            horns(t0, FIG, A2 + 12, 0.34)
        if i == 6:
            bells(t0, FIG, A3, 0.30)
        if i == 9:
            b.lead(sc, t0, FIG, A3, BPM, 0.50, 4.4, (0, 7))
        if i == 12:
            horns(t0, FIG, A3, 0.36)
            bells(t0, FIG, A3 + 12, 0.24)
    return sc.to_bytes(chans)


def build_bloodred_fight(rate, chans=1):
    """What plays while a finale is on the field. Same motif, off the leash."""
    b = Band(rate)
    BPM, BARS, LIFT = 176, 20, 2
    beat = 60.0 / BPM
    bar = beat * 4
    sc = Score(BARS * bar + 1.2, rate)
    A2, A3, A4 = semi("A2"), semi("A3"), semi("A4")
    ROOTS = [A2, semi("A#2"), A2, semi("G2")]
    sc.add(0.0, b.crash(bar * 0.85, reverse=True), 0.34)
    for i in range(BARS):
        t0 = i * bar
        lift = LIFT if i >= 16 else 0
        root = ROOTS[i % 4] + lift
        brk = i in (8, 9)
        if not brk:
            for e in range(16):
                if e % 8 == 7 and i % 2 == 1:
                    continue
                sc.add(t0 + e * beat * 0.25, b.chug(root, beat * 0.22, 11.0),
                       0.62)
            sc.add(t0, b.chord(root, beat * 0.95, drive=9.5), 0.58)
            sc.add(t0 + 2.5 * beat, b.chord(root, beat * 0.6, drive=9.5), 0.44)
            for e in range(4):
                sc.add(t0 + e * beat, b.bass(mhz(root - 12), beat * 0.92), 0.52)
            for e in range(8):
                sc.add(t0 + e * beat * 0.5, b.kick(), 0.74 if e % 2 else 0.84)
                if i >= 12:
                    sc.add(t0 + (e * 0.5 + 0.25) * beat, b.kick(), 0.42)
                if e in (2, 6):
                    sc.add(t0 + e * beat * 0.5, b.snare(), 0.52)
                sc.add(t0 + e * beat * 0.5, b.hat(5 + e % 3, open_=(e == 7)),
                       0.15)
            if i % 4 == 0:
                sc.add(t0, b.crash(), 0.44)
        else:
            sc.add(t0, b.chord(root, bar * 0.95, drive=8.0, damp=0.9985), 0.42)
            if i == 8:
                sc.add(t0 + 1.0 * beat, b.squeal(mhz(A4), 0.8), 0.50)
            if i == 9:
                sc.add(t0 + 1.5 * beat, b.riser(bar * 0.6), 0.42)
                for j in range(4):
                    sc.add(t0 + (3.0 + j * 0.25) * beat,
                           b.snare(0.16 - j * 0.015, 7 + j * 2), 0.40 + j * 0.03)
        if i in (2, 3, 6, 7):
            b.lead(sc, t0, m_hardened(MOTIF), A4, BPM, 0.84, 8.0)
        if i == 9:
            b.lead(sc, t0, MOTIF, A4, BPM, 0.95, 5.0, (0, 3, 12))
        if i in (10, 11, 14, 15):
            b.lead(sc, t0, m_hardened(MOTIF), A4, BPM, 0.90, 9.0, (0, 3, 12))
        if i == 13:
            b.lead(sc, t0, m_inverted(m_hardened(MOTIF)), A4, BPM, 0.82, 9.5)
        if i >= 16:
            if i % 2 == 0:
                b.lead(sc, t0, m_hardened(MOTIF), A4 + LIFT, BPM, 0.98, 9.5,
                       (0, 3, 12))
            sc.add(t0, b.crash(), 0.34)
        if i == 15:
            sc.add(t0 + 2.0 * beat, b.riser(bar * 0.55), 0.40)
            for j, f in enumerate((190, 160, 132, 108, 90, 76)):
                sc.add(t0 + (2.5 + j * 0.25) * beat, b.tom(f, 0.22), 0.52)
    return sc.to_bytes(chans)


# What plays under each chapter. Seven chapters, seven beds - THE GREY
# HOUR was under all of them, which was better than the silence it
# replaced and still meant the sky, the sea and the last siege all
# sounded like the first morning of the war.
#
# Chapter three is the exception that was already here: it plays the
# Blood Red's own piece, because chapter three is about the Blood Red
# coming back, and that is also what hands the fight themes their tours
# (see `combat_music`).
CHAPTER_MUSIC = {
    "arising": "grey",              # where it started, and the menu
    "ww3": "threeflags",            # three nations, three keys
    "revenge": "siege",             # the Blood Red's own
    "amber": "lastlight",           # the one that resolves upward
    "sky": "thinair",               # the one that is not in four
    "tide": "undertow",             # the one that is under water
    "lastsiege": "nomoreground",    # where the grey morning ends up
}


def build_corridor(rate, chans=1):
    """THE CORRIDOR. What plays when chapter one's finale walks on.

    The one piece in this score that CHANGES TEMPO. It opens at 124 and
    finishes at 144, a little faster every bar, and nothing announces it -
    you notice at the end that you have been leaning forward for a while.
    Chapter one is the corridor, and holding a corridor is exactly that.

    DORIAN, so it is not the siege. Same key, same guitar, but the sixth
    is raised, which puts a D MAJOR where the siege has an F - and that
    one chord is the whole difference between a gallop that is grim and a
    gallop that is game."""
    b = Band(rate)
    BARS = 20
    sc = Score(40.0, rate)
    A2, A3, A4 = semi("A2"), semi("A3"), semi("A4")
    ROOTS = [A2, A2, semi("G2"), semi("D2")]
    CH = {A2: ["A3", "C4", "E4"], semi("G2"): ["G3", "B3", "D4"],
          semi("D2"): ["D3", "F#3", "A3"]}
    FIG = m_diminished(MOTIF)
    t0 = 0.0
    for i in range(BARS):
        bpm = 124.0 + 20.0 * (i / float(BARS - 1))
        beat = 60.0 / bpm
        bar = beat * 4
        root = ROOTS[i % 4]
        stage = min(3, i // 5)
        last = (i == BARS - 1)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], bar * 0.98),
               0.24 + 0.03 * stage)
        for e in range(4):
            sc.add(t0 + e * beat, b.bass(mhz(root - 12), beat * 0.86), 0.48)
        # DOTTED EIGHTHS: six chugs evenly across four beats, which is
        # three against four and will not sit still
        if not last:
            for j in range(6):
                sc.add(t0 + j * beat * 0.75, b.chug(root, beat * 0.34),
                       0.58 + 0.07 * stage)
        if i >= 1 and not last:
            for e in range(4):
                sc.add(t0 + e * beat, b.kick(0.32), 0.84)
                if e in (1, 3):
                    sc.add(t0 + e * beat, b.snare(0.22), 0.48)
                sc.add(t0 + e * beat, b.hat(19), 0.15)
                sc.add(t0 + (e + 0.5) * beat,
                       b.hat(6, open_=(e == 3 and i % 2 == 1)), 0.13)
        elif last:
            sc.add(t0, b.kick(0.44), 0.70)
        if i % 4 == 0:
            sc.add(t0, b.crash(1.1), 0.34)
        if i in (4, 8):
            _t = b.lead(sc, t0, FIG, A3, bpm, 0.74, 6.0, (0, 7))
            b.lead(sc, _t, FIG, A3, bpm, 0.68, 6.0, (0, 7))
        if i in (12, 16):
            _t = b.lead(sc, t0, m_hardened(FIG), A4, bpm, 0.82, 7.5,
                        (0, 3, 12))
            b.lead(sc, _t, FIG, A4, bpm, 0.76, 7.5, (0, 3, 12))
        if i == 17:
            sc.add(t0 + 2.0 * beat, b.riser(bar * 0.6), 0.32)
            for j, f in enumerate((168, 142, 118, 98)):
                sc.add(t0 + (2.4 + j * 0.24) * beat, b.tom(f, 0.22), 0.46)
        if i == 18:
            sc.add(t0 + 3.2 * beat, b.squeal(mhz(A4), 0.50), 0.28)
        t0 += bar
    return sc.to_bytes(chans)


def build_all_three(rate, chans=1):
    """ALL THREE. Chapter two's finales - the Sovereign, the Bastion, and
    the machine the three of them built together.

    THREE FLAGS states the motif in three keys, one per section. This does
    the same thing EVERY BAR: A, then C, then D, then A again, and the
    whole band moves with it. Nothing gets four bars to settle into,
    because nothing in that chapter does.

    150, sixteenths, and horn stabs on the backbeat - the horn is what
    makes it three armies rather than one band playing quickly."""
    b = Band(rate)
    BPM, BARS = 150, 21
    beat = 60.0 / BPM
    bar = beat * 4
    sc = Score(BARS * bar + 1.4, rate)
    A3, C4, D4 = semi("A3"), semi("C4"), semi("D4")
    # one bar each, round and round: three flags, no seniority
    ROOTS = [semi("A2"), semi("C3"), semi("D3")]
    CH = {semi("A2"): ["A3", "C4", "E4"], semi("C3"): ["C4", "E4", "G4"],
          semi("D3"): ["D4", "F4", "A4"]}
    FIG = m_hardened(MOTIF)
    sc.add(0.0, b.crash(bar * 0.8, reverse=True), 0.28)
    for i in range(BARS):
        t0 = i * bar
        root = ROOTS[i % 3]
        stage = min(3, i // 6)
        last = (i == BARS - 1)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], bar * 0.98),
               0.24 + 0.03 * stage)
        if not last:
            for j in range(16):
                if j % 8 == 7 and i % 2:
                    continue
                sc.add(t0 + j * beat * 0.25, b.chug(root, beat * 0.22, 11.0),
                       0.58 + 0.06 * stage)
        for e in range(4):
            sc.add(t0 + e * beat, b.bass(mhz(root - 12), beat * 0.92), 0.52)
        # the stabs: brass on two and four, and they move with the key
        if i >= 2 and not last:
            for e in (1, 3):
                sc.add(t0 + e * beat, b.horn(mhz(root + 12), beat * 0.55,
                                             0.55), 0.34 + 0.05 * stage)
        if i >= 1 and not last:
            for e in range(8):
                sc.add(t0 + e * beat * 0.5, b.kick(0.30),
                       0.84 if e % 2 == 0 else 0.60)
                if e in (2, 6):
                    sc.add(t0 + e * beat * 0.5, b.snare(0.24), 0.52)
                sc.add(t0 + e * beat * 0.5, b.hat(5 + e % 3, open_=(e == 7)),
                       0.16)
        elif last:
            sc.add(t0, b.kick(0.42), 0.68)
        if i % 6 == 0:
            sc.add(t0, b.crash(1.2), 0.36)
        # three statements, three keys, back to back - then all at once
        if i == 6:
            b.lead(sc, t0, FIG, A3, BPM, 0.80, 7.0, (0, 7))
        if i == 7:
            b.lead(sc, t0, FIG, C4, BPM, 0.80, 7.0, (0, 7))
        if i == 8:
            b.lead(sc, t0, FIG, D4, BPM, 0.80, 7.0, (0, 7))
        if i == 14:
            sc.add(t0 + 2.4 * beat, b.riser(bar * 0.7), 0.32)
            for j, f in enumerate((176, 148, 122, 100, 84)):
                sc.add(t0 + (2.6 + j * 0.22) * beat, b.tom(f, 0.22), 0.48)
        if i in (16, 18):
            b.lead(sc, t0, FIG, A3, BPM, 0.86, 8.5, (0, 3, 12))
            b.lead(sc, t0, FIG, C4, BPM, 0.62, 7.0, (0, 7))
            b.lead(sc, t0, FIG, D4, BPM, 0.46, 6.0, (0, 7))
    return sc.to_bytes(chans)


def build_answered(rate, chans=1):
    """THEY ANSWERED. Chapter four's finales.

    Built as CALL AND RESPONSE, which nothing else here is: the guitar
    plays the motif, and one bar later the horns play it back a fifth
    higher. Call, answer, call, answer - and at the end the two of them
    stop taking turns and play together.

    LAST LIGHT is the only bed that resolves upward and this is the only
    fight that does. The lead harmonises in MAJOR thirds, which in a score
    written almost entirely in minor is the loudest thing in it."""
    b = Band(rate)
    BPM, BARS = 144, 20
    beat = 60.0 / BPM
    bar = beat * 4
    sc = Score(BARS * bar + 1.8, rate)
    A2, A3 = semi("A2"), semi("A3")
    ROOTS = [A2, semi("F2"), semi("C3"), semi("G2")]
    CH = {A2: ["A3", "C4", "E4"], semi("F2"): ["F3", "A3", "C4"],
          semi("C3"): ["C4", "E4", "G4"], semi("G2"): ["G3", "B3", "D4"]}

    def answer(t, mot, root, gain):
        """The horns, a fifth up, playing back what was just said."""
        for p, d in mot:
            sc.add(t, b.horn(mhz(root + p + 7), d * beat * 0.92, 0.50), gain)
            sc.add(t, b.horn(mhz(root + p + 12), d * beat * 0.92, 0.44),
                   gain * 0.55)
            t += d * beat
        return t

    sc.add(0.0, b.crash(bar * 0.9, reverse=True), 0.26)
    for i in range(BARS):
        t0 = i * bar
        root = ROOTS[i % 4]
        stage = min(3, i // 5)
        last = (i == BARS - 1)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], bar * 0.98),
               0.28 + 0.04 * stage)
        for e in range(4):
            sc.add(t0 + e * beat, b.bass(mhz(root - 12), beat * 0.90), 0.50)
        # THE BAND GETS OUT OF THE WAY FOR THE ANSWER. On the bars the
        # horns reply, the guitar plays ONE chug and the kit drops to
        # half time - otherwise the reply is buried under the rhythm
        # part and the whole idea of the piece is inaudible. The two
        # bars at the end where they play together keep the full band,
        # because by then they have stopped taking turns.
        reply = i in (5, 9, 13)
        if not last:
            for e in ((0,) if reply else range(4)):
                sc.add(t0 + e * beat, b.chug(root, beat * 0.44),
                       0.56 + 0.06 * stage)
                if not reply:
                    sc.add(t0 + (e + 0.5) * beat, b.chug(root, beat * 0.22),
                           0.32 + 0.05 * stage)
        if i >= 1 and not last:
            if reply:
                for e in (0, 2):
                    sc.add(t0 + e * beat, b.kick(0.34), 0.68)
                sc.add(t0 + 2 * beat, b.snare(0.26), 0.38)
            else:
                for e in range(4):
                    sc.add(t0 + e * beat, b.kick(0.34), 0.86)
                    if e in (1, 3):
                        sc.add(t0 + e * beat, b.snare(0.26), 0.50)
                    sc.add(t0 + (e + 0.5) * beat,
                           b.hat(21, open_=(e == 3)), 0.15)
        elif last:
            sc.add(t0, b.kick(0.46), 0.70)
            sc.add(t0, b.bell(mhz(A3), 3.0), 0.30)
        if i % 4 == 0:
            sc.add(t0, b.crash(1.2), 0.32)
            sc.add(t0, b.bell(mhz(root + 24), 2.0), 0.20)
        # ---- call... and answer ----------------------------------------
        if i in (4, 8, 12):
            b.lead(sc, t0, MOTIF, A3, BPM, 0.78, 6.5, (0, 4, 7))
        if reply:
            answer(t0, MOTIF, A3, 0.58)
        if i == 16:
            sc.add(t0 + 2.2 * beat, b.riser(bar * 0.66), 0.30)
            for j, f in enumerate((164, 138, 114, 94)):
                sc.add(t0 + (2.5 + j * 0.24) * beat, b.tom(f, 0.24), 0.46)
        # ...and at the end they stop taking turns
        if i in (17, 18):
            b.lead(sc, t0, MOTIF, A3, BPM, 0.86, 8.0, (0, 4, 7))
            answer(t0, MOTIF, A3, 0.50)
    return sc.to_bytes(chans)


def build_blue_sun(rate, chans=1):
    """BLUE SUN. Chapter five's finales, up where the sun is the wrong
    colour.

    The fastest thing in this score at 172, and for the first third of it
    there is NO BASS AT ALL - guitar, kit and bells, and nothing holding
    the bottom. It is the fight equivalent of what the bed does by taking
    the kick away: you are a long way up and there is nothing underneath.
    The low end arrives at bar eight and doubles at bar sixteen, and that
    arrival is the whole shape of the piece.

    The sharp fourth is kept, high in the pad, and the figure is THIN
    AIR's - the motif inverted and halved - played at nearly twice the
    tempo it floats at up there."""
    b = Band(rate)
    BPM, BARS = 172, 24
    beat = 60.0 / BPM
    bar = beat * 4
    sc = Score(BARS * bar + 1.6, rate)
    A2, A4, A5 = semi("A2"), semi("A4"), semi("A5")
    ROOTS = [A2, semi("C3"), semi("E3"), semi("D3")]
    CH = {A2: ["A3", "C4", "E4", "D#5"], semi("C3"): ["C4", "E4", "G4"],
          semi("E3"): ["E4", "G4", "B4"], semi("D3"): ["D4", "F4", "A4"]}
    FIG = m_diminished(m_inverted(MOTIF))
    sc.add(0.0, b.crash(bar * 1.2, reverse=True), 0.24)
    for i in range(BARS):
        t0 = i * bar
        root = ROOTS[(i // 2) % 4]
        stage = min(3, i // 6)
        last = (i == BARS - 1)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], bar * 0.98),
               0.26 + 0.03 * stage)
        # the guitar sits an octave up, where there is no weight in it
        if not last:
            for j in range(8):
                sc.add(t0 + j * beat * 0.5, b.chug(root + 12, beat * 0.26,
                                                   9.0), 0.50 + 0.06 * stage)
        # ---- THE GROUND. Nothing under it until here. ------------------
        if i >= 8:
            for e in range(4):
                sc.add(t0 + e * beat, b.bass(mhz(root - 12), beat * 0.88),
                       0.46)
        if i >= 16:
            for e in range(4):
                sc.add(t0 + (e + 0.5) * beat, b.bass(mhz(root - 24),
                                                     beat * 0.44), 0.38)
        if i >= 1 and not last:
            for e in range(8):
                sc.add(t0 + e * beat * 0.5, b.kick(0.26),
                       0.80 if e % 2 == 0 else 0.52)
                if e in (2, 6):
                    sc.add(t0 + e * beat * 0.5, b.snare(0.20), 0.48)
            # bells ON THE OFFBEAT, used as a cymbal - the one place in
            # this score where the bell is percussion
            for e in range(4):
                sc.add(t0 + (e + 0.5) * beat, b.bell(mhz(A5 + 12), 0.45, 6),
                       0.14 + 0.02 * stage)
        elif last:
            sc.add(t0, b.kick(0.40), 0.64)
            sc.add(t0, b.bell(mhz(A5), 2.2), 0.26)
        if i % 8 == 0:
            sc.add(t0, b.crash(1.0), 0.30)
        if i in (4, 10):
            _t = b.lead(sc, t0, FIG, A5 - 12, BPM, 0.62, 4.6, (0, 7))
            b.lead(sc, _t, FIG, A5 - 12, BPM, 0.58, 4.6, (0, 7))
        if i == 7:
            sc.add(t0 + 2.0 * beat, b.riser(bar * 1.9), 0.32)
        if i in (16, 20):
            _t = b.lead(sc, t0, FIG, A5, BPM, 0.70, 5.5, (0, 3, 12))
            b.lead(sc, _t, m_hardened(FIG), A5, BPM, 0.66, 5.5, (0, 3, 12))
        if i == 21:
            sc.add(t0 + 3.0 * beat, b.squeal(mhz(A4), 0.44), 0.26)
    return sc.to_bytes(chans)


def build_all_hands(rate, chans=1):
    """ALL HANDS. Chapter six's finales, and there is a lot of them and
    they are all enormous.

    IN SIX. 138, six beats to a bar, and it rolls rather than marches -
    the swell that THE UNDERTOW is built on, kept, and put behind a full
    kit. Phrygian kept as well, so the chord above the root is still a
    semitone up from it.

    It has the deepest bottom end in the score: the bass plays two
    octaves under the root and the horn holds the same note under that.
    Everything in this chapter comes up from underneath."""
    b = Band(rate)
    BPM, BARS = 138, 13
    beat = 60.0 / BPM
    bar = beat * 6
    trip = beat / 3.0
    sc = Score(BARS * bar + 2.0, rate)
    A2 = semi("A2")
    ROOTS = [A2, semi("A#2"), A2, semi("G2")]
    CH = {A2: ["A3", "C4", "E4"], semi("A#2"): ["A#3", "D4", "F4"],
          semi("G2"): ["G3", "A#3", "D4"]}
    FIG = m_augmented(m_hardened(MOTIF))
    sc.add(0.0, b.crash(bar * 0.7, reverse=True), 0.26)
    for i in range(BARS):
        t0 = i * bar
        root = ROOTS[i % 4]
        stage = min(3, i // 4)
        last = (i == BARS - 1)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], bar * 0.98),
               0.30 + 0.03 * stage)
        sc.add(t0, b.horn(mhz(root - 12), bar * 0.92, 0.20), 0.36)
        # ...and the bottom never lets go: two octaves under the root on
        # the odd beats, one octave on the others, so there is no beat of
        # the six with nothing underneath it
        for e in (0, 2, 4):
            sc.add(t0 + e * beat, b.bass(mhz(root - 24), beat * 1.70), 0.56)
        for e in (1, 3, 5):
            sc.add(t0 + e * beat, b.bass(mhz(root - 12), beat * 0.84), 0.34)
        # QUARTERS, NOT EIGHTHS. Twelve chugs across a bar of six at 138
        # is a gallop, and this is the sea - it should be the heaviest
        # thing in the score, not the busiest. Six, and each one twice
        # the weight.
        if not last:
            for j in range(6):
                sc.add(t0 + j * beat, b.chug(root, beat * 0.52, 11.5),
                       0.68 + 0.06 * stage)
        if i >= 1 and not last:
            for e in (0, 2, 4):
                sc.add(t0 + e * beat, b.kick(0.36), 0.88)
            sc.add(t0 + 3 * beat, b.snare(0.28), 0.52)
            if i >= 4:
                sc.add(t0 + 1 * beat, b.snare(0.24), 0.34)
                for e in (1, 5):        # the roll, still in threes
                    for j in range(3):
                        sc.add(t0 + e * beat + j * trip,
                               b.tom(112 - j * 14, 0.20), 0.30 - j * 0.05)
            if i >= 9:                  # and the hats arrive late
                for e in range(6):
                    sc.add(t0 + (e + 0.5) * beat, b.hat(23), 0.10)
        elif last:
            sc.add(t0, b.kick(0.50), 0.66)
        if i % 4 == 0:
            sc.add(t0, b.crash(1.6), 0.32)
        if i in (2, 6):
            b.lead(sc, t0, FIG, A2 + 24, BPM, 0.72, 6.0, (0, 7))
        if i == 9:
            b.lead(sc, t0, FIG, A2 + 24, BPM, 0.82, 7.5, (0, 3, 12))
            sc.add(t0 + 5.0 * beat, b.squeal(mhz(semi("A4")), 0.60), 0.26)
        if i == 8:
            sc.add(t0 + 3.0 * beat, b.riser(bar * 0.6), 0.30)
    return sc.to_bytes(chans)


def build_three_lanes(rate, chans=1):
    """THREE LANES. Chapter seven's finales - and chapter seven fields the
    whole campaign's back catalogue, so this one had to be able to walk on
    behind anything.

    NO MORE GROUND is a canon in two voices half a bar apart. This is the
    same canon at 160 in THREE voices, ONE BEAT apart: the motif, the
    motif upside down, and the motif with its third flattened, all three
    stacked and colliding through the middle of every bar. Three lanes.

    Harmonic minor kept, so the seventh leans; the horn drone kept, so
    there is a siren under it."""
    b = Band(rate)
    BPM, BARS = 160, 22
    beat = 60.0 / BPM
    bar = beat * 4
    sc = Score(BARS * bar + 1.5, rate)
    A2, A3 = semi("A2"), semi("A3")
    ROOTS = [A2, semi("F2"), semi("G#2"), A2]
    CH = {A2: ["A3", "C4", "E4"], semi("F2"): ["F3", "A3", "C4"],
          semi("G#2"): ["G#3", "B3", "D4"]}

    def canon(t, root, gain, drive):
        """Three entries, one beat apart. They are on top of each other
        for two of the four beats, which is the point."""
        b.lead(sc, t, MOTIF, root, BPM, gain, drive, (0, 7))
        b.lead(sc, t + beat, m_inverted(MOTIF), root, BPM, gain * 0.76,
               drive * 0.88, (0, 7))
        b.lead(sc, t + 2 * beat, m_hardened(MOTIF), root, BPM, gain * 0.58,
               drive * 0.80, (0, 7))

    sc.add(0.0, b.crash(bar * 0.9, reverse=True), 0.28)
    for i in range(BARS):
        t0 = i * bar
        root = ROOTS[i % 4]
        stage = min(3, i // 6)
        last = (i == BARS - 1)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], bar * 0.98),
               0.26 + 0.03 * stage)
        sc.add(t0, b.horn(mhz(root - 12), bar * 0.94, 0.16), 0.28)
        for e in range(4):
            sc.add(t0 + e * beat, b.bass(mhz(root - 12), beat * 0.92), 0.52)
        if not last:
            for j in range(16):
                if j % 8 == 7 and i % 2:
                    continue
                sc.add(t0 + j * beat * 0.25, b.chug(root, beat * 0.20, 11.5),
                       0.60 + 0.06 * stage)
        if i >= 2 and not last:
            for e in range(8):
                sc.add(t0 + e * beat * 0.5, b.kick(0.28),
                       0.86 if e % 2 == 0 else 0.56)
                if e in (2, 6):
                    sc.add(t0 + e * beat * 0.5, b.snare(0.24), 0.52)
                sc.add(t0 + e * beat * 0.5, b.hat(25, open_=(e == 7)), 0.16)
        elif last:
            sc.add(t0, b.kick(0.44), 0.68)
        if i % 6 == 0:
            sc.add(t0, b.crash(1.2), 0.34)
        if i in (5, 11):
            canon(t0, A3, 0.76, 7.0)
        if i == 15:
            sc.add(t0 + 2.4 * beat, b.riser(bar * 0.7), 0.32)
            for j, f in enumerate((180, 152, 126, 104, 86)):
                sc.add(t0 + (2.6 + j * 0.20) * beat, b.tom(f, 0.20), 0.48)
        if i in (17, 19):
            canon(t0, A3, 0.88, 8.5)
        if i == 20:
            sc.add(t0 + 3.2 * beat, b.squeal(mhz(A3), 0.52), 0.26)
    return sc.to_bytes(chans)


def build_emperor(rate, chans=1):
    """THE EMPEROR. What plays when anything in the Court walks on - the
    Emperor Amaranth at the end of it, and the thirteen that come first.

    THE COURT at war speed. Same five-bar cycle, same six beats to a bar,
    same parallel fifths - 120 instead of 80, with a kit under it and the
    guitar chugging every beat. A procession does not stop being a
    procession because it has started killing people.

    Its own idea: the fifths and the INVERSION play at the same time.
    Organum going up and the same line going down, over each other, for
    the whole of every statement - which is a sound nothing else in this
    score makes and about as close to a hundred and eighty million hit
    points as five notes can get.

    The bells are artillery here rather than ceremony: same instrument,
    twice the gain, on the beats the kick is not."""
    b = Band(rate)
    BPM, BARS = 120, 15
    beat = 60.0 / BPM
    bar = beat * 6
    sc = Score(BARS * bar + 2.2, rate)
    A2, A3 = semi("A2"), semi("A3")
    ROOTS = [A2, semi("F2"), semi("G2"), semi("E2"), A2]
    CH = {A2: ["A3", "C4", "E4"], semi("F2"): ["F3", "A3", "C4"],
          semi("G2"): ["G3", "B3", "D4"], semi("E2"): ["E3", "G#3", "B3"]}
    FIG = m_augmented(MOTIF)

    def court(t, root, gain):
        """Fifths going up and the inversion going down, together."""
        b.lead(sc, t, FIG, root, BPM, gain, 6.5, (0, 7, 12))
        tt = t
        for p, d in m_inverted(FIG):
            sc.add(tt, b.horn(mhz(root + p), d * beat * 0.94, 0.52),
                   gain * 0.52)
            tt += d * beat
        return tt

    for i in range(BARS):
        t0 = i * bar
        root = ROOTS[i % 5]
        stage = min(3, i // 5)
        last = (i == BARS - 1)
        sc.add(t0, b.pad([mhz(semi(x)) for x in CH[root]], bar * 0.98),
               0.30 + 0.03 * stage)
        sc.add(t0, b.horn(mhz(root + 12), bar * 0.90, 0.34), 0.30)
        for e in (0, 3):
            sc.add(t0 + e * beat, b.bass(mhz(root - 12), beat * 2.5), 0.54)
        if not last:
            for e in range(6):
                sc.add(t0 + e * beat, b.chug(root, beat * 0.46),
                       0.56 + 0.06 * stage)
        if i >= 1 and not last:
            for e in (0, 3):
                sc.add(t0 + e * beat, b.kick(0.42), 0.90)
            for e in (1, 4):
                sc.add(t0 + e * beat, b.kick(0.30), 0.54)
            sc.add(t0 + 2 * beat, b.snare(0.28), 0.50)
            sc.add(t0 + 5 * beat, b.snare(0.28), 0.50)
            # artillery: the bell on the beats the kick is not
            for e in (2, 5):
                sc.add(t0 + e * beat, b.bell(mhz(root + 24), 1.9),
                       0.30 + 0.04 * stage)
            if i >= 5:
                for e in range(6):
                    sc.add(t0 + (e + 0.5) * beat, b.hat(27), 0.14)
        elif last:
            sc.add(t0, b.kick(0.50), 0.70)
            sc.add(t0, b.bell(mhz(A3), 3.0), 0.32)
        if i % 5 == 0:
            sc.add(t0, b.crash(2.2), 0.32)
        if i in (2, 7):
            court(t0, A3, 0.66)
        if i == 11:
            sc.add(t0 + 4.0 * beat, b.riser(bar * 0.5), 0.30)
            for j, f in enumerate((150, 126, 104, 86)):
                sc.add(t0 + (4.2 + j * 0.28) * beat, b.tom(f, 0.26), 0.46)
        if i == 12:
            court(t0, A3, 0.80)
            sc.add(t0 + 5.2 * beat, b.squeal(mhz(A3), 0.58), 0.26)
    return sc.to_bytes(chans)


def tour_music(d):
    """Which piece a tour plays.

    A datasheet may name its own with `music=`, which is how a tour off
    the chapter ladder gets one - VERMILION BLOOD has `chapter=None` and
    would otherwise fall through to the menu piece for two hundred
    waves. Failing that it is the chapter's bed, and failing THAT the
    menu piece, so a chapter added later is never silent."""
    if d is None:
        return MENU_TRACK
    own = d.get("music")
    if own:
        return own
    if d.get("key") == "siege":
        return "siege"
    return CHAPTER_MUSIC.get(d.get("chapter"), MENU_TRACK)


# What plays while a finale is on the field, chapter by chapter. Each
# one is built out of that chapter's own bed - same key, same chords,
# same transform of the MOTIF - and then taken off the leash, so a
# finale arrives sounding like the sector it is the end of rather than
# like a different band walking on.
CHAPTER_FIGHT = {
    "arising": "corridor",          # accelerates, 124 to 144
    "ww3": "allthree",              # changes key every bar
    "revenge": "bloodred",          # the Blood Red's, and only theirs
    "amber": "answered",            # call, and the answer a fifth up
    "sky": "bluesun",               # no bass for the first third
    "tide": "allhands",             # in six, and rolling
    "lastsiege": "threelanes",      # the canon, in three voices
}

# ...and the bosses who are somebody in particular. A named enemy brings
# its own music wherever it turns up, which is the entire point of
# having been given a piece of its own - the VERMILION VENGEANCE is a
# milestone in chapter seven as well as a finale in chapter three, and
# it should not sound like the sector it is visiting.
BOSS_FIGHT = {"vermilion": "vermilion"}


def tour_fight(d):
    """What plays while a finale is on this tour's field, before any
    individual boss claims it.

    Mirrors `tour_music`: a datasheet may name its own with `fight=`,
    the BLOOD RED SIEGE keeps the piece it is named for, and anything
    else takes its chapter's. None if the chapter has no fight written
    for it, in which case the bed simply plays on - which is what the
    whole game did until there were eight of these."""
    if d is None:
        return None
    own = d.get("fight")
    if own:
        return own
    if d.get("key") == "siege":
        return "bloodred"
    return CHAPTER_FIGHT.get(d.get("chapter"))


def combat_music(game):
    """What should be playing right now.

    A finale on the field takes the music over, and hands it back when
    it dies. That used to happen in six tours out of forty; the other
    thirty-four played their bed straight through whatever walked on.

    A boss with its own name beats the chapter's fight, and if several
    of them are standing there at once the BIGGEST one wins - which is
    only decidable if it is written down, and `any(...)` over an
    unordered list was not."""
    base = tour_music(game.diff)
    live = [e for e in game.enemies
            if not e.dead and not e.leaked and e.d.get("boss")]
    if not live:
        return base
    named = [(e.d.get("hp", 0), BOSS_FIGHT[e.kind]) for e in live
             if e.kind in BOSS_FIGHT]
    if named:
        return max(named)[1]
    return tour_fight(game.diff) or base


TRACKS = {"siege": build_siege_theme, "bloodred": build_bloodred_fight,
          # ---- the beds, one per chapter ----
          "grey": build_grey_hour, "threeflags": build_three_flags,
          "lastlight": build_last_light, "thinair": build_thin_air,
          "undertow": build_undertow, "nomoreground": build_no_ground,
          "court": build_the_court,
          # ---- and what each of them lifts into when a finale lands ----
          "corridor": build_corridor, "allthree": build_all_three,
          "answered": build_answered, "bluesun": build_blue_sun,
          "allhands": build_all_hands, "threelanes": build_three_lanes,
          "emperor": build_emperor,
          # ---- ...and the one that belongs to a machine, not a sector ----
          "vermilion": build_vengeance}

# The piece under the menu and under every tour that does not own one.
# WRITTEN, not loaded: it needs no file beside the script and no credit
# to anybody, because the game generated it.
MENU_TRACK = "grey"


class Music:
    """Plays the score. Rendering a piece takes a few seconds of pure Python,
    so it happens on a worker thread and the music starts when it is ready -
    the game never waits for it."""

    def __init__(self, sounds):
        self.ok = bool(sounds and getattr(sounds, "ok", False))
        # the mixer's own rate, not the one the effects happen to use
        self.rate = getattr(sounds, "RATE", 22050)
        try:
            init = pygame.mixer.get_init()
            if init:
                self.rate = init[0]
        except Exception:
            pass
        self.built = {}          # name -> Sound, made on the main thread
        self.raw = {}            # name -> PCM bytes, made on a worker
        self.chans = 1
        try:
            init = pygame.mixer.get_init()
            if init:
                self.chans = init[2]
        except Exception:
            pass
        self.pending = set()
        self.want = None
        self.playing = None
        self.muted = False
        self.volume = 0.55
        self.channel = None
        if self.ok:
            try:
                self.channel = pygame.mixer.Channel(
                    pygame.mixer.get_num_channels() - 1)
            except Exception:
                self.ok = False

    def _render(self, name):
        """Worker thread. Pure arithmetic - it must not touch pygame."""
        try:
            self.raw[name] = TRACKS[name](self.rate, self.chans)
        except Exception:
            self.raw[name] = b""
        finally:
            self.pending.discard(name)

    def request(self, name):
        """Ask for a track. Starts it if it is ready, builds it if not."""
        if not self.ok or name == self.want:
            return
        self.want = name
        if name is None:
            self.stop()
            return
        if name in self.built:
            self._start(name)
        elif name not in self.pending:
            self.pending.add(name)
            threading.Thread(target=self._render, args=(name,),
                             daemon=True).start()

    def update(self):
        """Called every frame ON THE MAIN THREAD. Any PCM a worker has
        finished is turned into a Sound here, where that is safe to do."""
        if not self.ok:
            return
        for name in list(self.raw):
            data = self.raw.pop(name)
            try:
                self.built[name] = (pygame.mixer.Sound(buffer=data)
                                    if data else None)
            except Exception:
                self.built[name] = None
        if self.want is None:
            return
        if self.playing != self.want and self.want in self.built:
            self._start(self.want)

    def _start(self, name):
        snd = self.built.get(name)
        if snd is None or self.channel is None:
            return
        try:
            self.channel.stop()
            self.channel.play(snd, loops=-1)
            self.channel.set_volume(0.0 if self.muted else self.volume)
            self.playing = name
        except Exception:
            pass

    def stop(self):
        self.playing = None
        if self.channel is not None:
            try:
                self.channel.stop()
            except Exception:
                pass

    def toggle_mute(self):
        self.muted = not self.muted
        if self.channel is not None:
            try:
                self.channel.set_volume(0.0 if self.muted else self.volume)
            except Exception:
                pass
        return self.muted

