BASE_LOADOUT = ["mg", "sniper", "mortar", "sam", "auto", "jammer"]
LOADOUT_SLOTS = 6

# Special emplacements sit in their own two slots and are earned by clearing
# tours rather than bought. A later one supersedes the earlier it grew from.
# ...but not the ones a TOUR lends. A lent berth is standing in the sector
# because somebody left it there; it is not earned, it does not go in the
# armoury, it does not take a loadout slot and it does not follow you out
# of the chapter. Without this the four THE GENOCIDE lends turned up free
# and permanent in every other tour in the game.
SPECIAL_ORDER = [k for k in TOWER_TYPES
                 if TOWER_TYPES[k].get("special")
                 and not TOWER_TYPES[k].get("lent")]
SPECIAL_SLOTS = 2
# A titan does not compete with the ordinary specials for a berth in the
# loadout - it is carried in a slot of its own, so taking one costs you
# nothing else.
TITAN_SLOTS = 1

# The specials fall into four tiers, and the armoury shows them that way: what
# a tour hands you outright, what a line grows into, what sits at the end of
# one, and the titans, which are a class apart. Derived from the specs rather
# than listed, so a new emplacement lands in the right section by virtue of
# how it is defined.
SPECIAL_SECTIONS = [
    ("FIELD ISSUE", "Earned outright by finishing a tour."),
    ("EVOLUTIONS", "The same weapon, rebuilt. Both forms stay available."),
    ("MASTERIES", "The end of a line. Nothing grows out of these."),
    ("TITANS", "One machine, carried in a slot of its own."),
]


def is_titan(kind):
    return bool(TOWER_TYPES[kind].get("titan"))


def special_tier(kind):
    """0 = issued outright, 1 = an evolution, 2 = a mastery, 3 = a titan."""
    d = TOWER_TYPES[kind]
    if d.get("titan"):
        return 3
    if d.get("mastery"):
        return 2
    return 1 if d.get("evolves") else 0


def slot_cap(kind):
    """How many of this kind of special may be carried at once."""
    return TITAN_SLOTS if is_titan(kind) else SPECIAL_SLOTS


def carried(special, kind):
    """How many things of the same class as `kind` are already carried."""
    want = is_titan(kind)
    return sum(1 for k in special if is_titan(k) == want)


def trim_special(special):
    """Cut a loadout down to what the two caps allow, keeping order."""
    out, n_sp, n_ti = [], 0, 0
    for k in special:
        if is_titan(k):
            if n_ti >= TITAN_SLOTS:
                continue
            n_ti += 1
        else:
            if n_sp >= SPECIAL_SLOTS:
                continue
            n_sp += 1
        out.append(k)
    return out


def specials_by_section():
    """The special roster split into its three tiers, in armoury order."""
    return [[k for k in SPECIAL_ORDER if special_tier(k) == t]
            for t in range(len(SPECIAL_SECTIONS))]



