def feat_earned(key, carried):
    """Does this loadout satisfy the feat's carry requirement?

    Only meaningful for the feats that are tours. A tally feat is
    credited a kill at a time and never by finishing anything."""
    f = FEATS[key]
    if "carry" not in f:
        return False
    held = set(carried or ())
    return all(set(group) & held for group in f["carry"])


def feat_reqs(kind):
    """The feats that stand between the player and this emplacement."""
    return list(TOWER_TYPES[kind].get("feats", []))


def feat_have(key, feats, clears=None):
    """How far along this feat is.

    A tally feat is counted into `feats` a kill at a time. A CHAPTER feat
    is not counted at all - it is however many times the least-cleared tour
    of that chapter has been cleared, which is the honest reading of
    "the whole chapter, twice"."""
    f = FEATS[key]
    ch = f.get("chapter")
    if ch:
        tours = [d["key"] for d in DIFFICULTIES
                 if d.get("chapter") == ch and not d.get("box")
                 and not d.get("cat") and not d.get("crown")
                 and not d.get("capital") and not d.get("endless")]
        if not tours:
            return 0
        return min((clears or {}).get(k, 0) for k in tours)
    return (feats or {}).get(key, 0)


def feats_met(kind, feats, clears=None):
    return all(feat_have(k, feats, clears) >= FEATS[k]["need"]
               for k in feat_reqs(kind))


def feat_label(key, have=0):
    f = FEATS[key]
    return f"{f['label']} x{f['need']}" + (f" ({have}/{f['need']})"
                                           if have else "")


def special_req(kind):
    """The mission that earns this emplacement: a list of (tour, clears)."""
    return list(TOWER_TYPES[kind].get("req", []))


def special_met(kind, clears, feats=None, owned=None):
    # A code emplacement is not earned, it is TOLD to you. No number of
    # clears and no feat opens it; only the word does, and the word puts it
    # straight into `unlocked`.
    if TOWER_TYPES[kind].get("code") and kind not in (owned or ()):
        return False
    if not all(clears.get(k, 0) >= n for k, n in special_req(kind)):
        return False
    return feats_met(kind, feats or {}, clears)


def special_progress(kind, clears, feats=None):
    """Every outstanding task, as (label, have, need). A plain tour is
    named by the tour; a feat is named by what it asks you to carry."""
    out = [(DIFF_BY_KEY[k]["name"], min(clears.get(k, 0), n), n)
           for k, n in special_req(kind)]
    for k in feat_reqs(kind):
        f = FEATS[k]
        # read through feat_have, so a CHAPTER feat shows its real progress
        # rather than a zero it never counts into
        have = min(feat_have(k, feats, clears), f["need"])
        label = f["label"]
        ch = f.get("chapter")
        if ch and have < f["need"]:
            # NAME the tour that is holding it up. "every tour of THE ORANGE
            # TIDE cleared, twice - 1/2" is perfectly true and no use at all
            # when three of the four are on three clears and the fourth is
            # on one: it tells you that you are short without telling you
            # what of, and the whole chapter looks done from where you sit.
            worst = sorted(
                ((clears or {}).get(d["key"], 0), d["name"])
                for d in DIFFICULTIES
                if d.get("chapter") == ch and not d.get("box")
                and not d.get("cat") and not d.get("crown")
                and not d.get("capital") and not d.get("endless"))
            if worst:
                low, name = worst[0]
                chn = next((c["name"] for c in CHAPTERS if c["key"] == ch),
                           ch.upper())
                label = f"{chn} x{f['need']} - {name} on {low}"
        out.append((label, have, f["need"]))
    return out


def max_level(kind):
    """How many ranks this emplacement has. Almost everything stops at four;
    the Cat Base does not, because every rank of it adds another animal."""
    return TOWER_TYPES[kind].get("levels", MAX_LEVEL)


def unlock_cost(kind):
    return TOWER_TYPES[kind].get("unlock", 0)


def unlock_requires(kind):
    """Emplacements that must already be owned before this one can be bought.
    The silo is the missile launcher's end of the line, not a first purchase,
    and the base is built on top of the whole support roster."""
    req = TOWER_TYPES[kind].get("requires")
    if req is None:
        return []
    return list(req) if isinstance(req, (list, tuple)) else [req]


def unlock_tours(kind):
    """Tours that must have been cleared before this one can be bought, as a
    list of (tour key, clears). Bought emplacements are normally open from the
    start; the biggest ones also want a campaign behind them."""
    return list(TOWER_TYPES[kind].get("req_tour", []))


