FACTION_ORDER = ["crimson", "azure", "amber", "cobalt", "tide",
                 "kitten", "longcat", "kingdom", "forest", "cosmos",
                 "genocide", "vermilion"]


def faction_col(key):
    return FACTIONS[key]["col"] if key in FACTIONS else None


def _rage_form(d):
    """What stands back up out of the wreck.

    Lighter, faster, angrier, and worth less: killing something twice
    should not pay twice. `walks_again` is what starts it at the gate
    rather than where its own corpse fell - without it a rage form
    inherits the dead one's distance and there is no road left to fight
    it on."""
    r = dict(d)
    r["name"] = "ENRAGED " + d["name"]
    r["full"] = "AN ENRAGED " + d["name"]
    r["hp"] = max(1, int(d["hp"] * 0.55))
    r["spd"] = round(d["spd"] * 1.45, 1)
    r["atk"] = int(d["atk"] * 1.60)
    r["armor"] = int(d["armor"] * 0.80)
    r["bounty"] = int(d.get("bounty", 0) * 0.5)
    r["col"] = (255, 78, 58)
    r["walks_again"] = True
    r["rage"] = True
    # A rage form does not rage again, does not bring friends, and does
    # not split: it is the last thing this hostile does.
    for _k in ("drops", "escorts", "splits", "quarters"):
        r.pop(_k, None)
    return r


VERMILION_RAGE = {}
for _vk, _vd in list(ENEMY_TYPES.items()):
    # Structures do not stand back up - a portal that came back would
    # never let the wave end.
    if _vd.get("only") != ("vermilion",) or _vd.get("gate"):
        continue
    _rk = "rage_" + _vk
    VERMILION_RAGE[_vk] = _rk
    ENEMY_TYPES[_rk] = _rage_form(_vd)
    ENEMY_TYPES[_vk] = dict(_vd,
                            drops=tuple(_vd.get("drops", ())) + ((_rk, 1),))
del _vk, _vd, _rk


def national(kind, faction):
    """What `faction` fields where the plan asks for `kind`.

    Some equipment belongs to one nation - the Syndicate's heavy armour is
    theirs and nobody else's - so anyone else sends the nearest thing they
    have instead, walking down the fallback chain until they reach something
    they are allowed to field."""
    for _ in range(6):
        only = ENEMY_TYPES.get(kind, {}).get("only")
        if not only or faction in only:
            return kind
        nxt = ENEMY_TYPES[kind].get("fallback")
        if not nxt or nxt == kind:
            return kind
        kind = nxt
    return kind


def ground_only(plan, diff):
    """Strip the aircraft out of a wave, for a tour that has none.

    Applied AFTER doctrine rather than before it: a nation's swap table can
    turn a ground slot into an air one, so filtering the plan first would let
    aircraft back in through the side door."""
    if not diff or not diff.get("no_air"):
        return plan
    return [row for row in plan if not ENEMY_TYPES[row[0]].get("air")]


def apply_doctrine(plan, faction):
    """Rewrite a wave plan into one nation's way of fighting."""
    if not faction or faction not in FACTIONS:
        return plan
    swap = FACTIONS[faction]["swap"]
    return [(national(swap.get(k, k), faction), n, gap, delay)
            for (k, n, gap, delay) in plan]


def tour_factions(d):
    """Every nation taking part in a tour, in the order they show up."""
    if d.get("factions"):
        return list(d["factions"])
    return [d.get("faction", "crimson")]


CHAPTERS = [
    dict(key="arising", n=1, name="WAR ARISING",
         sub="Hold the corridor. Where it all began.",
         opens=None),
    dict(key="ww3", n=2, name="WORLD WAR III",
         sub="The line breaks and the war goes global.",
         opens="siege"),
    dict(key="revenge", n=3, name="BLOOD RED REVENGE",
         sub="It was never destroyed. It was only waiting.",
         opens="totalwar"),
    dict(key="amber", n=4, name="AMBER HORIZON",
         sub="She made the call. They answered.",
         opens="revenge"),
    dict(key="sky", n=5, name="THE SKY VOYAGE",
         sub="The sun is blue. Go up and find out why.",
         opens="amberhorizon"),
    dict(key="tide", n=6, name="THE ORANGE TIDE",
         sub="Two flags, one fleet, and all of it under water.",
         opens="skyvoyage"),
    dict(key="lastsiege", n=7, name="THE FINAL SIEGE",
         sub="Three lanes at once, and they are coming for the guns.",
         opens="seaking"),
]
CHAPTER_BY_KEY = {c["key"]: c for c in CHAPTERS}
_ROMAN = ((10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"))


def roman(n):
    """Chapter numeral. This used to be a three-item list, which meant
    adding a fourth chapter crashed the chapter screen rather than numbering
    it."""
    out = ""
    for v, sym in _ROMAN:
        while n >= v:
            out += sym
            n -= v
    return out


def chapter_tours(key):
    """Every tour in one chapter, in ladder order.

    Endless runs are NOT in it. They belong to a chapter for the sake of
    which army turns up, but they are not rungs on its ladder - counting
    them made chapter one read as eight tours when it has seven, and there
    is nothing to clear in them anyway."""
    return [d for d in DIFFICULTIES
            if d.get("chapter", "arising") == key and not d.get("endless")]


def _endless_for(ch):
    """The endless run for one chapter, built off its hardest real tour."""
    pool = [d for d in DIFFICULTIES
            if d.get("chapter", "arising") == ch["key"]
            and not d.get("endless") and not d.get("cat")
            and not d.get("box") and not d.get("crown")
            and not d.get("capital") and not d.get("secret")]
    if not pool:
        return None
    base = max(pool, key=lambda d: (d["tier"], d.get("waves", 0)))
    return dict(
        key="endless_" + ch["key"], tier=base["tier"], chapter=ch["key"],
        name="ENDLESS: " + ch["name"], sub="Hold Until Overrun",
        # a shade under the tour it is drawn from, because it never stops
        hp=base["hp"] * 0.86, spd=base["spd"] * 0.97,
        armor=base["armor"] * 0.90, atk=base["atk"] * 0.90,
        bounty=base.get("bounty", 1.0) * 1.14,
        cash=base.get("cash", 400) + 120,
        integrity=max(12, base.get("integrity", 16) + 6),
        gap=base.get("gap", 10.0) + 1.4,
        rp=round(base.get("rp", 2.0) * 0.55, 2),
        waves=ENDLESS_RAMP, boss=base["boss"], endless=True,
        # Only carried when the base tour actually has them. Setting
        # map=None is NOT the same as leaving it out: `get("map",
        # "corridor")` hands back the None rather than the default, and
        # chapter one - whose tours name no map at all - crashed on it.
        **{k: base[k] for k in ("milestones", "map", "faction", "armoury",
                                "breakers", "hackers")
           if base.get(k) is not None},
        note=f"{ch['name']}, with no finish line. The sector, the army and "
             f"the flags of that chapter - and a boss every tenth wave "
             f"until you are overrun.")


for _ch in CHAPTERS:
    _e = _endless_for(_ch)
    if _e:
        DIFFICULTIES.append(_e)
ENDLESS_TOURS = [d for d in DIFFICULTIES if d.get("endless")]

