class Particle:
    __slots__ = ("x", "y", "vx", "vy", "life", "max_life", "col", "size",
                 "kind", "grav", "spin")

    def __init__(self, x, y, vx, vy, life, col, size, kind="spark", grav=0.0):
        self.x, self.y = x, y
        self.vx, self.vy = vx, vy
        self.life = self.max_life = life
        self.col = col
        self.size = size
        self.kind = kind
        self.grav = grav
        self.spin = random.uniform(-9, 9)

    def update(self, dt):
        self.x += self.vx * dt
        self.y += self.vy * dt
        self.vy += self.grav * dt
        if self.kind == "smoke":
            self.vx *= 0.96
            self.vy *= 0.96
            self.size += 26 * dt
        self.life -= dt
        return self.life > 0

    def draw(self, surf):
        t = clamp(self.life / self.max_life, 0, 1)
        if self.kind == "smoke":
            a = int(120 * t)
            s = int(self.size)
            if s < 1:
                return
            tmp = pygame.Surface((s * 2, s * 2), pygame.SRCALPHA)
            pygame.draw.circle(tmp, (*self.col, a), (s, s), s)
            surf.blit(tmp, (self.x - s, self.y - s))
        elif self.kind == "debris":
            r = max(1, self.size * t)
            pygame.draw.rect(surf, self.col,
                             (self.x - r, self.y - r, r * 2, r * 2))
        else:  # spark
            r = max(1.0, self.size * t)
            pygame.draw.circle(surf, self.col, (self.x, self.y), r)


