BASE_BY_KEY = {b["key"]: b for b in BASE_UPGRADES}
# Field repairs are a rate rather than a number, so the level maps to a wave
# interval instead of multiplying a step. Fewer waves is better.
REPAIR_EVERY = (0, 20, 14, 9, 6)


def base_cost(key, level):
    """What the NEXT level costs, or None once it is maxed."""
    b = BASE_BY_KEY[key]
    if level >= b["levels"]:
        return None
    return int(round(b["cost"] * b["growth"] ** level / 10.0) * 10)


def base_total(key, level):
    """Everything one upgrade is worth at `level`."""
    if key == "repair":
        return REPAIR_EVERY[clamp(level, 0, len(REPAIR_EVERY) - 1)]
    return BASE_BY_KEY[key]["step"] * level


def clip_words(text, size, width, bold=True):
    """Trim to whole words that fit `width`, with an ellipsis if anything was
    dropped. Cutting on a character count instead left every blurb on the
    COMMAND screen ending in the middle of a word."""
    if FONTS.font(size, bold).size(text)[0] <= width:
        return text
    out = []
    for w in text.split():
        trial = " ".join(out + [w]) + "..."
        if FONTS.font(size, bold).size(trial)[0] > width:
            break
        out.append(w)
    return (" ".join(out) + "...") if out else ""


def base_effect_text(key, level):
    b = BASE_BY_KEY[key]
    if key == "repair":
        if not level:
            return "none"
        return f"+1 integrity every {REPAIR_EVERY[level]} waves"
    v = base_total(key, level)
    if key == "supply":
        return f"+${v:.0f}/sec while a wave is on the road"
    if key == "hq":
        return f"+{v:.0f} HQ integrity"
    if key == "reserve":
        return f"+${v:.0f} at the start of every sector"
    if key == "salvage":
        return f"+{v:.0f}% bounty on every kill"
    if key == "requisition":
        return f"+{v:.0f}% requisition from every tour"
    if key == "tempo":
        return f"+{v:.0f}% on the deploy-early bonus"
    if key == "refit":
        return f"-{v:.0f}% on every refit"
    if key in ("veterans", "garrison"):
        return f"+{v:.0f}% HP on everything you field"
    if key == "quarter":
        return f"-{v:.0f}% to lay every emplacement"
    if key == "flak":
        return f"+{v:.0f}% damage to anything airborne"
    if key == "signals":
        return f"stuns end {v:.0f}% sooner"
    if key == "kinetic":
        return f"+{v:.0f}% fire rate on every emplacement"
    if key == "demo":
        return f"+{v:.0f}% splash radius"
    if key == "fabricate":
        return f"spawners replace losses {v:.0f}% sooner"
    if key == "arsenal":
        return f"+{v:.0f}% damage from every emplacement"
    if key == "overwatch":
        return f"+{v:.0f}% range on every emplacement"
    if key == CITADEL_KEY:
        return "the post rebuilt, and three programmes opened" if level \
            else "not built"
    return f"+{v:.0f}%"


GFX_DETAIL = ("FULL", "AUTO", "PLAIN")
