def read_code(text):
    """What the player typed, in the form the table is keyed by.

    Case and spacing are not the puzzle - somebody reading a code off a
    screen should not lose it to a stray space or the caps lock."""
    return "".join(c for c in str(text).upper() if c.isalnum())


class Profile:
    """Requisition, unlocked emplacements and the chosen loadout, persisted
    beside the script. A broken or missing file just means a fresh recruit."""

    def __init__(self):
        self.rp = 0
        self.chapter = "arising"
        # The first six cost nothing and are issued outright. A CODE
        # emplacement also costs nothing, and handing those to everybody at
        # profile creation would give away the whole point of the word.
        # A CODE emplacement is listed and locked - the point of a code
        # is that you know the thing exists. A DROP is not listed at all.
        self.unlocked = [k for k in TOWER_ORDER if unlock_cost(k) == 0
                         and not TOWER_TYPES[k].get("code")
                         and not TOWER_TYPES[k].get("drop")]
        self.loadout = list(BASE_LOADOUT)
        self.diff_index = 1
        self.auto_wave = False
        self.best = {}                 # difficulty key -> best wave cleared
        self.skip = {}                 # difficulty key -> chosen start wave
        # THE THIRD PLACE THESE LIVE. `load` sets them from the file
        # and the reset branch sets them again; this is the one that
        # runs first and always. Miss it and `save` raises on the
        # attribute - inside a bare `try`, so the profile silently
        # stops persisting ANYTHING rather than failing loudly.
        self.seen_intro = False        # the opening has played
        self.seen_ending = False       # the siege cutscene has played
        self.seen_forge = False        # chapter three's opening has played
        self.seen_vengeance = False    # and the end of the campaign
        self.seen_command = False      # chapter four's opening
        self.seen_second = False       # and what they did after it
        self.seen_blue = False         # and what was watching all of it
        self.seen_quiet = False        # and the five years after it
        self.seen_lastsiege = False    # and the three that are left
        self.seen_final = False        # wave three hundred, and the hand
        self.seen_peace = False        # and what everybody got afterwards
        self.seen_lighthouse = False   # ...and what a fih turns into
        self.seen_launch = False       # where the Cat Prince came from
        self.seen_escape = False       # ...and how anybody got off it
        self.base_on = True            # is COMMAND applied to a run at all
        # what the game is allowed to spend on looking good. See `Gfx`.
        self.gfx_detail = "AUTO"
        self.gfx_spawns = "AUTO"
        self.gfx_hostiles = "AUTO"
        self.gfx_crowd = "AUTO"
        self.gfx_shots = "FULL"
        self.gfx_particles = "FULL"
        self.gfx_effects = True
        self.gfx_shake = True
        self.codes = []                # codes already redeemed, once each
        self.cleared = []              # difficulty keys whose tour was won
        self.clears = {}               # key -> how many times it was won
        self.special = []              # equipped special emplacements
        self.evolved = []              # evolutions already rolled forward
        self.base = {}                 # command upgrade key -> level
        self.feats = {}                # feat key -> times performed
        self.siege_seen = False        # has the hidden mode been uncovered
        self.kitten_seen = False       # and has the cat been found
        self.kitten_won = False        # and did anyone finish what it started
        self.box_seen = False          # and has the box been opened
        self.crown_seen = False        # and has the crown been picked up
        self.fast = False              # ...and has FASTER been typed in
        self.sun = False               # ...and has SUNCLICKER
        self.rpx = False               # ...and has CLAUDE
        self.keep_on = True            # is the Cat Kingdom the post fielded
        self.box_won = False           # and did anybody hold the line
        self.load()

    def load(self):
        try:
            with open(PROFILE_PATH, "r", encoding="utf-8") as fh:
                d = json.load(fh)
        except Exception:
            return
        try:
            self.rp = max(0, int(d.get("rp", 0)))
            # prefer the key: inserting a tier shifts every stored index. Look
            # the position up rather than trusting "tier" to equal it, so a
            # tour can be slotted in anywhere without breaking saves.
            key = d.get("diff_key")
            if key in DIFF_BY_KEY:
                self.diff_index = next(i for i, dd in enumerate(DIFFICULTIES)
                                       if dd["key"] == key)
            else:
                self.diff_index = clamp(int(d.get("diff_index", 1)),
                                        0, len(DIFFICULTIES) - 1)
            ch = d.get("chapter", "arising")
            self.chapter = ch if ch in CHAPTER_BY_KEY else "arising"
            gd = d.get("gfx_detail", "AUTO")
            self.gfx_detail = gd if gd in GFX_DETAIL else "AUTO"
            gs = d.get("gfx_spawns", "AUTO")
            self.gfx_spawns = gs if gs in GFX_DETAIL else "AUTO"
            gh = d.get("gfx_hostiles", "AUTO")
            self.gfx_hostiles = gh if gh in GFX_DETAIL else "AUTO"
            gc = d.get("gfx_crowd", "AUTO")
            self.gfx_crowd = gc if gc in GFX_CROWD else "AUTO"
            gt = d.get("gfx_shots", "FULL")
            self.gfx_shots = gt if gt in GFX_SHOTS else "FULL"
            gp = d.get("gfx_particles", "FULL")
            self.gfx_particles = gp if gp in GFX_PARTICLES else "FULL"
            self.gfx_effects = bool(d.get("gfx_effects", True))
            self.gfx_shake = bool(d.get("gfx_shake", True))
            self.codes = [c for c in (d.get("codes") or []) if c in CODES]
            self.apply_gfx()
            self.auto_wave = bool(d.get("auto_wave", False))
            self.cleared = [k for k in d.get("cleared", []) if k in DIFF_BY_KEY]
            ft = d.get("feats", {})
            if isinstance(ft, dict):
                self.feats = {k: max(0, int(v)) for k, v in ft.items()
                              if k in FEATS}
            self.siege_seen = bool(d.get("siege_seen", False))
            self.kitten_seen = bool(d.get("kitten_seen", False))
            self.kitten_won = bool(d.get("kitten_won", False))
            self.box_seen = bool(d.get("box_seen", False))
            self.crown_seen = bool(d.get("crown_seen", False))
            self.fast = bool(d.get("fast", False))
            self.sun = bool(d.get("sun", False))
            self.rpx = bool(d.get("rpx", False))
            self.keep_on = bool(d.get("keep_on", True))
            self.box_won = bool(d.get("box_won", False))
            cl = d.get("clears", {})
            if isinstance(cl, dict):
                self.clears = {k: max(0, int(v)) for k, v in cl.items()
                               if k in DIFF_BY_KEY}
            # an older save only recorded *that* a tour was cleared
            for k in self.cleared:
                self.clears.setdefault(k, 1)
            self.special = trim_special([k for k in d.get("special", [])
                                         if k in SPECIAL_ORDER])
            self.evolved = [k for k in d.get("evolved", [])
                            if k in SPECIAL_ORDER]
            bs = d.get("base", {})
            if isinstance(bs, dict):
                self.base = {k: clamp(int(v), 0, BASE_BY_KEY[k]["levels"])
                             for k, v in bs.items() if k in BASE_BY_KEY}
            best = d.get("best", {})
            if isinstance(best, dict):
                self.seen_intro = bool(d.get("seen_intro"))
                self.seen_ending = bool(d.get("seen_ending"))
                self.seen_forge = bool(d.get("seen_forge"))
                self.seen_vengeance = bool(d.get("seen_vengeance"))
                self.seen_command = bool(d.get("seen_command"))
                self.seen_second = bool(d.get("seen_second"))
                self.seen_blue = bool(d.get("seen_blue"))
                self.seen_quiet = bool(d.get("seen_quiet"))
                self.seen_lastsiege = bool(d.get("seen_lastsiege"))
                self.seen_final = bool(d.get("seen_final"))
                self.seen_peace = bool(d.get("seen_peace"))
                self.seen_lighthouse = bool(d.get("seen_lighthouse"))
                self.seen_launch = bool(d.get("seen_launch"))
                self.seen_escape = bool(d.get("seen_escape"))
                self.base_on = bool(d.get("base_on", True))
                sk = d.get("skip", {})
                if isinstance(sk, dict):
                    self.skip = {k: max(1, int(v)) for k, v in sk.items()
                                 if k in DIFF_BY_KEY}
                self.best = {k: int(v) for k, v in best.items()
                             if k in DIFF_BY_KEY}
            base = [k for k in TOWER_ORDER if unlock_cost(k) == 0
                    and not TOWER_TYPES[k].get("code")
                    and not TOWER_TYPES[k].get("drop")]
            got = [k for k in d.get("unlocked", []) if k in TOWER_TYPES]
            self.unlocked = list(dict.fromkeys(base + got))
            load = [k for k in d.get("loadout", []) if k in self.unlocked]
            self.loadout = list(dict.fromkeys(load))[:LOADOUT_SLOTS]
            if not self.loadout:
                self.loadout = list(BASE_LOADOUT)
        except Exception:
            self.rp = 0
            self.chapter = "arising"
            self.unlocked = [k for k in TOWER_ORDER if unlock_cost(k) == 0
                             and not TOWER_TYPES[k].get("code")]
            self.loadout = list(BASE_LOADOUT)
            self.diff_index = 1
            self.auto_wave = False
            self.best = {}
            self.skip = {}
            self.seen_intro = False
            self.seen_ending = False
            self.seen_forge = False
            self.seen_vengeance = False
            self.seen_command = False
            self.seen_second = False
            self.seen_blue = False
            self.seen_quiet = False
            self.seen_lastsiege = False
            self.seen_final = False
            self.seen_peace = False
            self.seen_lighthouse = False
            self.seen_launch = False
            self.seen_escape = False
            self.base_on = True
            self.cleared = []
            self.clears = {}
            self.special = []
            self.evolved = []
            self.base = {}
            self.siege_seen = False
            self.kitten_seen = False
            self.kitten_won = False
            self.box_seen = False
            self.box_won = False

    def redeem(self, text):
        """Take a code. Returns (did it work, what to tell them).

        Never raises and never half-applies: either the code is good and
        unspent and everything it gives is given, or nothing happens."""
        key = read_code(text)
        if not key:
            return False, ""
        got = CODES.get(key)
        if got is None:
            return False, "! THAT IS NOT A CODE"
        if key in self.codes:
            return False, "! ALREADY REDEEMED"
        self.codes.append(key)
        rp = int(got.get("rp", 0))
        if rp:
            self.rp += rp
        gives = got.get("gives")
        if gives and gives not in self.unlocked:
            self.unlocked.append(gives)
        if got.get("speed"):
            self.fast = True
        if got.get("money"):
            self.sun = True
        if got.get("rpmul"):
            self.rpx = True
        self.save()
        note = got.get("note", "")
        bits = [note] if note else []
        if rp:
            bits.append(f"+{rp:,} RP")
        if gives:
            bits.append(TOWER_TYPES[gives]["name"])
        if got.get("speed"):
            bits.append(f"{got['speed']}x SPEED")
        if got.get("money"):
            bits.append(f"{got['money']}x MONEY")
        if got.get("rpmul"):
            bits.append(f"{got['rpmul']:g}x REQUISITION")
        return True, "  -  ".join(bits)

    def apply_gfx(self):
        """Push the stored settings into the one object the drawing code
        reads. Called on load and whenever a setting is changed."""
        GFX.detail = self.gfx_detail
        GFX.spawns = self.gfx_spawns
        GFX.hostiles = self.gfx_hostiles
        GFX.crowd = self.gfx_crowd
        GFX.shots = self.gfx_shots
        GFX.particles = self.gfx_particles
        GFX.effects = self.gfx_effects
        GFX.shake = self.gfx_shake
        if GFX.detail != "AUTO" and GFX.spawns != "AUTO":
            GFX.busy = False

    def cycle_gfx(self, field, step=1):
        """Step one setting on, and make it take effect at once."""
        if field == "detail":
            i = GFX_DETAIL.index(self.gfx_detail)
            self.gfx_detail = GFX_DETAIL[(i + step) % len(GFX_DETAIL)]
        elif field == "spawns":
            i = GFX_DETAIL.index(self.gfx_spawns)
            self.gfx_spawns = GFX_DETAIL[(i + step) % len(GFX_DETAIL)]
        elif field == "hostiles":
            i = GFX_DETAIL.index(self.gfx_hostiles)
            self.gfx_hostiles = GFX_DETAIL[(i + step) % len(GFX_DETAIL)]
        elif field == "crowd":
            i = GFX_CROWD.index(self.gfx_crowd)
            self.gfx_crowd = GFX_CROWD[(i + step) % len(GFX_CROWD)]
        elif field == "shots":
            i = GFX_SHOTS.index(self.gfx_shots)
            self.gfx_shots = GFX_SHOTS[(i + step) % len(GFX_SHOTS)]
        elif field == "particles":
            i = GFX_PARTICLES.index(self.gfx_particles)
            self.gfx_particles = GFX_PARTICLES[(i + step)
                                               % len(GFX_PARTICLES)]
        elif field == "effects":
            self.gfx_effects = not self.gfx_effects
        elif field == "shake":
            self.gfx_shake = not self.gfx_shake
        self.apply_gfx()
        self.save()

    def save(self):
        try:
            with open(PROFILE_PATH, "w", encoding="utf-8") as fh:
                json.dump({"rp": self.rp, "chapter": self.chapter,
                           "unlocked": self.unlocked,
                           "loadout": self.loadout,
                           "diff_index": self.diff_index,
                           "diff_key": self.difficulty()["key"],
                           "auto_wave": self.auto_wave,
                           "cleared": self.cleared,
                           "siege_seen": self.siege_seen,
                           "kitten_seen": self.kitten_seen,
                           "kitten_won": self.kitten_won,
                           "box_seen": self.box_seen,
                           "crown_seen": self.crown_seen,
                           "fast": self.fast,
                           "sun": self.sun,
                           "rpx": self.rpx,
                           "keep_on": self.keep_on,
                           "box_won": self.box_won,
                           "clears": self.clears,
                           "feats": self.feats,
                           "special": self.special,
                           "evolved": self.evolved,
                           "base": self.base,
                           "best": self.best,
                           "skip": self.skip,
                           "seen_intro": self.seen_intro,
                           "seen_ending": self.seen_ending,
                           "seen_forge": self.seen_forge,
                           "seen_vengeance": self.seen_vengeance,
                           "seen_command": self.seen_command,
                           "seen_second": self.seen_second,
                           "seen_blue": self.seen_blue,
                           "seen_quiet": self.seen_quiet,
                           "seen_lastsiege": self.seen_lastsiege,
                           "seen_final": self.seen_final,
                           "seen_peace": self.seen_peace,
                           "seen_lighthouse": self.seen_lighthouse,
                           "seen_launch": self.seen_launch,
                           "seen_escape": self.seen_escape,
                           "base_on": self.base_on,
                           "gfx_detail": self.gfx_detail,
                           "gfx_spawns": self.gfx_spawns,
                           "gfx_hostiles": self.gfx_hostiles,
                           "gfx_crowd": self.gfx_crowd,
                           "gfx_shots": self.gfx_shots,
                           "gfx_particles": self.gfx_particles,
                           "gfx_effects": self.gfx_effects,
                           "gfx_shake": self.gfx_shake,
                           "codes": self.codes},
                          fh, indent=1)
        except Exception:
            pass                      # a read-only folder must not break play

    def is_unlocked(self, kind):
        return kind in self.unlocked

    def missing_for(self, kind):
        """Everything still standing between the player and this emplacement:
        a list of short human-readable strings, empty when it can be bought."""
        gaps = []
        for fk in feat_reqs(kind):
            have = feat_have(fk, self.feats, self.clears)
            need = FEATS[fk]["need"]
            if have < need:
                gaps.append(f"{FEATS[fk]['label']} {have}/{need}")
        if TOWER_TYPES[kind].get("code") and not self.is_unlocked(kind):
            gaps.append("a code")
        for req in unlock_requires(kind):
            if not self.is_unlocked(req):
                gaps.append(TOWER_TYPES[req]["name"].lower())
        for tour, n in unlock_tours(kind):
            have = self.clears.get(tour, 0)
            if have < n:
                name = DIFF_BY_KEY[tour]["name"]
                gaps.append(f"{name} x{n - have}" if n > 1 else f"clear {name}")
        return gaps

    def can_unlock(self, kind):
        """Affordable, and every prerequisite and tour behind it."""
        return (not self.is_unlocked(kind)
                and self.rp >= unlock_cost(kind)
                and not self.missing_for(kind))

    def unlock(self, kind):
        cost = unlock_cost(kind)
        if TOWER_TYPES[kind].get("code"):
            return False          # this one is told to you, not sold to you
        if self.is_unlocked(kind) or self.rp < cost:
            return False
        # `missing_for` now covers feats as well as owned kit and cleared
        # tours, so a quest gates an ordinary emplacement the same way.
        if self.missing_for(kind):
            return False
        self.rp -= cost
        self.unlocked.append(kind)
        # An evolution supersedes what it grew out of: if the earlier form is
        # being carried, this takes its place rather than asking for a slot
        # of its own. Both stay unlocked, so it can be swapped back by hand.
        base = TOWER_TYPES[kind].get("evolves")
        if base in self.loadout and kind not in self.loadout:
            self.loadout[self.loadout.index(base)] = kind
        elif len(self.loadout) < LOADOUT_SLOTS:
            self.loadout.append(kind)
        self.save()
        return True

    def toggle_loadout(self, kind):
        if not self.is_unlocked(kind):
            return False
        if kind in self.loadout:
            if len(self.loadout) <= 1:
                return False
            self.loadout.remove(kind)
        elif len(self.loadout) >= LOADOUT_SLOTS:
            return False
        else:
            self.loadout.append(kind)
        self.save()
        return True

    def difficulty(self):
        return DIFFICULTIES[self.diff_index]

    def chapter_unlocked(self, key):
        """A chapter opens once the tour that closes the one before it has
        been cleared. The first is always open."""
        need = CHAPTER_BY_KEY[key]["opens"]
        return need is None or need in self.cleared

    def chapters_open(self):
        return [c for c in CHAPTERS if self.chapter_unlocked(c["key"])]

    def tours(self):
        """The tours selectable right now: those in the chosen chapter."""
        return chapter_tours(self.chapter)

    def set_chapter(self, key):
        if not self.chapter_unlocked(key):
            return False
        self.chapter = key
        # land on the first tour of the chapter we just moved to
        self.diff_index = DIFFICULTIES.index(self.tours()[0])
        self.save()
        return True

    def cycle_chapter(self, step=1):
        open_ch = self.chapters_open()
        keys = [c["key"] for c in open_ch]
        i = keys.index(self.chapter) if self.chapter in keys else 0
        self.set_chapter(keys[(i + step) % len(keys)])
        return CHAPTER_BY_KEY[self.chapter]

    def start_wave(self, d=None):
        """The checkpoint the next run on this tour will drop into.

        Always re-clamped against the record: a saved choice must never
        outlive the progress that earned it, or editing the file - or a tour
        being made shorter - would hand out ground that was never taken."""
        d = d or self.difficulty()
        pts = self.skip_points_for(d)
        want = self.skip.get(d["key"], 1)
        return max(p for p in pts if p <= want) if want >= 1 else 1

    def skip_points_for(self, d=None):
        """This tour's checkpoints, including the finale where it is open."""
        d = d or self.difficulty()
        return skip_points(d, self.best.get(d["key"], 0),
                           d["key"] in self.cleared)

    def cycle_skip(self, step=1, d=None):
        d = d or self.difficulty()
        pts = self.skip_points_for(d)
        cur = self.start_wave(d)
        i = pts.index(cur) if cur in pts else 0
        self.skip[d["key"]] = pts[(i + step) % len(pts)]
        self.save()
        return self.skip[d["key"]]

    def can_skip(self, d=None):
        d = d or self.difficulty()
        return len(self.skip_points_for(d)) > 1

    def cycle_difficulty(self, step=1):
        # Cycle within the chosen chapter, not across the whole ladder.
        # A tour nobody has uncovered is not in the pool AT ALL - the
        # siege included. It used to sit in here as a "? ? ?" and name
        # itself the moment the row landed on it, which meant the one
        # secret in chapter one was the one you could not help finding.
        pool = [d for d in self.tours()
                if ((not d.get("cat") or self.kitten_seen)
                    and (not d.get("box") or self.box_seen)
                    and (not d.get("crown") or self.crown_seen)
                    and (not d.get("capital") or self.capital_open())
                    and (not d.get("secret") or self.siege_seen))]
        cur = self.difficulty()
        i = pool.index(cur) if cur in pool else 0
        self.diff_index = DIFFICULTIES.index(pool[(i + step) % len(pool)])
        self.save()
        return self.difficulty()

    # WAR ARISING, WORLD WAR III, BLOOD RED REVENGE and THE ORANGE TIDE,
    # five times each - measured on the tour that ENDS each of those
    # chapters rather than on every tour in them, so a chapter counts as
    # taken when its hardest ladder sector has been.
    CAPITAL_KEYS = ("nightmare", "totalwar", "revenge", "seaking")
    CAPITAL_NEED = 5

    def capital_have(self):
        """How many of the four required tours are at five clears."""
        return sum(1 for k in self.CAPITAL_KEYS
                   if self.clears.get(k, 0) >= self.CAPITAL_NEED)

    def capital_open(self):
        return self.capital_have() >= len(self.CAPITAL_KEYS)

    def capital_progress(self):
        """One row per required tour, for the page that shows the seal:
        (key, tour name, its chapter, clears so far, clears wanted)."""
        out = []
        for k in self.CAPITAL_KEYS:
            d = DIFF_BY_KEY[k]
            out.append((k, d["name"], CHAPTER_BY_KEY.get(d.get("chapter")),
                        self.clears.get(k, 0), self.CAPITAL_NEED))
        return out

    def capital_left(self):
        """How many more clears in total - the number the one-line
        readout on EXTRAS cannot say."""
        return sum(max(0, self.CAPITAL_NEED - self.clears.get(k, 0))
                   for k in self.CAPITAL_KEYS)

    def revealed(self, d=None):
        d = d or self.difficulty()
        if d.get("capital"):
            return self.capital_open()
        if d.get("cat"):
            return self.kitten_seen
        if d.get("box"):
            return self.box_seen
        if d.get("crown"):
            return self.crown_seen
        return (not d.get("secret")) or self.siege_seen

    def label(self, d=None):
        d = d or self.difficulty()
        return d["name"] if self.revealed(d) else "? ? ?"

    def blood(self):
        """Is the blood-red theme active?"""
        d = self.difficulty()
        return bool(d.get("secret")) and self.siege_seen

    def credit_feats(self, tally):
        """Bank a run's counted feats. Called with whatever has been
        tallied since the last time, so it adds rather than sets."""
        if not tally:
            return
        for k, n in tally.items():
            if k in FEATS:
                self.feats[k] = self.feats.get(k, 0) + int(n)
        self.refresh_special()
        self.save()

    def mark_cleared(self, diff_key, carried=None):
        # An endless run has no objective to secure. It cannot be won, so it
        # cannot be cleared, and it must never open a chapter or a special.
        if DIFF_BY_KEY.get(diff_key, EMPTY).get("endless"):
            return
        if diff_key not in self.cleared:
            self.cleared.append(diff_key)
        self.clears[diff_key] = self.clears.get(diff_key, 0) + 1
        # and credit any feat this run also satisfied - the tour is only
        # half of it, the other half is what was on the board
        for key, f in FEATS.items():
            # `any_tour` is for "win five carrying this", where the point is
            # what you brought rather than where you took it.
            named = f.get("tour")
            if ((named == diff_key or (named is None and f.get("any_tour")))
                    and feat_earned(key, carried)):
                self.feats[key] = self.feats.get(key, 0) + 1
        self.refresh_special()
        self.save()

    # -- special emplacements ---------------------------------------------
    def special_unlocked(self, kind):
        """Earned, and paid for if it asks to be. Only the top of the titan
        line carries a price; everything else is earned outright."""
        if not special_met(kind, self.clears, self.feats,
                           self.unlocked):
            return False
        return unlock_cost(kind) <= 0 or kind in self.unlocked

    def special_earned(self, kind):
        """The tours are done - whether or not the bill has been settled."""
        return special_met(kind, self.clears, self.feats, self.unlocked)

    def buy_special(self, kind):
        cost = unlock_cost(kind)
        if cost <= 0 or kind in self.unlocked:
            return False
        if (not special_met(kind, self.clears, self.feats, self.unlocked)
                or self.rp < cost):
            return False
        self.rp -= cost
        self.unlocked.append(kind)
        self.save()
        return True

    def special_available(self):
        """Every earned special. An evolution does NOT retire the form it grew
        from - both stay available so either can be carried."""
        return [k for k in SPECIAL_ORDER if self.special_unlocked(k)]

    def refresh_special(self):
        """On the first unlock of an evolution, roll an equipped ancestor
        forward once so the evolution is felt. Afterwards the player is free
        to switch back: both forms remain equippable."""
        avail = self.special_available()
        for k in avail:
            base = TOWER_TYPES[k].get("evolves")
            if not base or k in self.evolved:
                continue
            self.evolved.append(k)
            if base in self.special and k not in self.special:
                self.special[self.special.index(base)] = k
        self.special = trim_special([k for k in self.special if k in avail])

    def toggle_special(self, kind):
        if kind not in self.special_available():
            return False
        if kind in self.special:
            self.special.remove(kind)
        elif carried(self.special, kind) >= slot_cap(kind):
            # a titan fills its own slot; it never displaces a special
            return False
        else:
            self.special.append(kind)
        self.save()
        return True

    def full_loadout(self):
        return list(self.loadout) + list(self.special)

    def armoury_loadout(self):
        """Every emplacement this player actually owns, in armoury order.

        The last tour carries "the whole armoury" - which means the whole
        of YOURS. Reading it as every emplacement in the game handed out
        locked specials, the Perfected Triarch included, for a chapter that
        had not been finished yet."""
        have = [k for k in TOWER_ORDER if self.is_unlocked(k)]
        avail = self.special_available()
        have += [k for k in SPECIAL_ORDER
                 if k not in TOWER_ORDER and k in avail]
        return have

    # -- command upgrades ------------------------------------------------
    def base_level(self, key):
        return clamp(int(self.base.get(key, 0)), 0, BASE_BY_KEY[key]["levels"])

    def base_gain(self, key):
        """What one upgrade is currently worth to a run."""
        return base_total(key, self.base_level(key))

    def citadel(self):
        """Has the post been rebuilt? Everything tier two hangs off this."""
        return self.base_level(CITADEL_KEY) >= 1

    def catkeep(self):
        """Has the post become the court's seat? Tier three hangs off it.

        Owning it and FIELDING it are different questions: the tier is
        yours once it is bought, but which post goes into a sector is a
        choice you make between tours."""
        return self.base_level(CATKEEP_KEY) >= 1

    def keep_fielded(self):
        """Is the Cat Kingdom the post going into the next sector?"""
        return self.catkeep() and self.keep_on

    def base_open(self, b):
        """Is this row on the screen at all?

        A row with `needs` is not merely unaffordable until that tour has
        been cleared - it is not offered, because it is a trophy and the
        screen should not spoil what it is a trophy for."""
        need = b.get("needs")
        if need and need not in self.cleared:
            # never beaten it: the row is a trophy and stays out of sight
            return False
        # A programme OF something does not exist until the thing it is a
        # programme of has been bought. Not greyed out - not there: five
        # rows about flufas on a screen with no flufas on it is five rows
        # of nonsense.
        parent = b.get("needs_row")
        if parent and self.base_level(parent) < 1:
            return False
        tier = b.get("tier", 1)
        if tier == 2:
            return self.citadel()
        if tier == 3:
            return self.catkeep()
        return True

    def base_locked(self, b):
        """Everything still standing between this row and being bought,
        or None if it is buyable.

        Separate from `base_open` on purpose. `base_open` answers "should
        this be on the screen at all" and hides a trophy; this answers
        "what is it waiting for" and is printed on the card's face. A
        requirement nobody can see is a requirement nobody will ever
        meet, so anything countable is counted out loud."""
        out = []
        need = b.get("needs")
        want = b.get("needs_clears", 1)
        if need and want > 1:
            have = self.clears.get(need, 0)
            if have < want:
                nm = DIFF_BY_KEY[need]["name"] if need in DIFF_BY_KEY else need
                out.append(f"{min(have, want)}/{want} {nm}")
        fk = b.get("needs_feat")
        if fk and self.feats.get(fk, 0) < FEATS[fk]["need"]:
            out.append(f"{self.feats.get(fk, 0)}/{FEATS[fk]['need']} "
                       f"{FEATS[fk]['label']}")
        return "   ".join(out) if out else None

    def base_rows(self):
        """Every COMMAND row that is on the screen at all, in order. The
        tier-two programmes do not exist until the Citadel does - they are
        not shown greyed out, because a locked row you cannot even read
        the price of is just a row that wastes the space."""
        return [b for b in BASE_UPGRADES if self.base_open(b)]

    def base_sections(self):
        """The COMMAND rows, split into the posts they belong to.

        The war's programmes are the concrete post's and the kingdom's are
        the keep's, and fielding either one stops the other paying - so
        they are not one list. A section with nothing open in it is not
        offered, which is why this is a list and not a fixed pair."""
        rows = self.base_rows()
        # THE KEEP'S first, by name rather than by tier: the row that
        # BUYS the keep is an evolution and carries no tier of its own,
        # so it would otherwise sit in the war's list.
        keep = [b for b in rows if b["key"] in CATKEEP_ROWS]
        rest = [b for b in rows if b["key"] not in CATKEEP_ROWS]
        out = []
        for title, got in (("THE WAR'S PROGRAMMES",
                            [b for b in rest if b.get("tier", 1) == 1]),
                           ("THE CITADEL",
                            [b for b in rest if b.get("tier", 1) != 1]),
                           ("THE CAT KINGDOM",
                            [b for b in keep
                             if b["key"] not in ALLIANCE_ROWS]),
                           ("THE ALLIANCE",
                            [b for b in keep
                             if b["key"] in ALLIANCE_ROWS])):
            if got:
                out.append((title, got))
        return out

    def base_levels(self):
        """The whole board, as the Game wants it: key -> level.

        The keep is reported as zero when it is owned but not fielded, so
        the run behaves exactly as it did before it was ever bought."""
        got = {b["key"]: self.base_level(b["key"]) for b in BASE_UPGRADES}
        if not self.keep_on:
            got[CATKEEP_KEY] = 0
        return got

    def buy_base(self, key):
        lvl = self.base_level(key)
        cost = base_cost(key, lvl)
        if cost is None or self.rp < cost:
            return False
        if not self.base_open(BASE_BY_KEY[key]):
            return False
        self.rp -= cost
        self.base[key] = lvl + 1
        self.save()
        return True

    def award(self, rp, wave, diff_key):
        # the Requisition Office is paid on the way in, so it compounds with
        # itself: every tour run to afford the next level pays for more of it
        rp = int(round(rp * (1.0 + self.base_gain("requisition") / 100.0)))
        # CLAUDE, on the way out. Applied AFTER the Requisition Office so
        # the two multiply rather than one of them being folded into the
        # other - and applied here because `award` is the one door every
        # payout in the game already goes through.
        if getattr(self, "rpx", False):
            rp = int(round(rp * RP_MUL))
        self.rp += max(0, int(rp))
        if wave > self.best.get(diff_key, 0):
            self.best[diff_key] = wave
        self.save()


