def draw_crown(surf, cx, cy, s, main, dark, blades=5, lean=0.0):
    """A crown of blades over a head. The mark of what rebuilt these.

    `s` is the head's own size - the crown is drawn in proportion to it -
    and `lean` tips the whole thing for a machine that is not upright."""
    ca, sa = math.cos(lean), math.sin(lean)

    def R(px, py):
        return (cx + px * ca - py * sa, cy + px * sa + py * ca)

    # the band it all sits on
    band = [R(-s * 0.46, -s * 0.02), R(s * 0.46, -s * 0.02),
            R(s * 0.40, -s * 0.20), R(-s * 0.40, -s * 0.20)]
    pygame.draw.polygon(surf, main, band)
    pygame.draw.polygon(surf, dark, band, max(1, int(s * 0.035)))
    # and the blades: the middle one tallest, the outer ones swept out
    for i in range(blades):
        k = (i / (blades - 1.0)) * 2.0 - 1.0 if blades > 1 else 0.0
        tall = s * (1.02 - 0.42 * abs(k))
        base = k * s * 0.36
        tip = k * s * 0.62
        pts = [R(base - s * 0.075, -s * 0.16),
               R(base + s * 0.075, -s * 0.16),
               R(tip, -s * 0.16 - tall)]
        pygame.draw.polygon(surf, main, pts)
        pygame.draw.polygon(surf, dark, pts, max(1, int(s * 0.030)))
        # a lit edge down the leading side of each blade
        pygame.draw.line(surf, shade(main, 1.45),
                         R(base, -s * 0.16), R(tip, -s * 0.16 - tall * 0.92),
                         max(1, int(s * 0.030)))


_HEAD = {}


def _head_top(kind, half=10, need=0.40, solid=8):
    """How far above its feet this plate puts its HEAD, at s=1.

    Looks down a narrow column on the centre line, because the topmost point
    of a plate is usually a wing, an aerial or a gun barrel and the head is
    the thing in the middle.

    It also has to be a RUN of rows rather than one. The Sapphire carries a
    detached bar two units thick, and then a gap, and then its crest: seat a
    crown on the bar and it hangs in the air over the hole underneath, which
    is exactly what it did. So a row only counts as the top of the head if
    the column stays filled for `solid` units below it.

    Measured once and kept - it is a full plate render."""
    key = (kind, half, need, solid)
    got = _HEAD.get(key)
    if got is None:
        pad, base = 420, 620
        lay = pygame.Surface((pad * 2, base + 60), pygame.SRCALPHA)
        draw_boss_front(lay, kind, pad, base, 1.0)
        want = need * half * 2
        got, run = 0, 0
        for y in range(base):
            n = sum(1 for x in range(pad - half, pad + half)
                    if lay.get_at((x, y))[3] > 60)
            if n >= want:
                run += 1
                if run >= solid:
                    got = base - (y - run + 1)
                    break
            else:
                run = 0
        _HEAD[key] = got
    return got


def loom_scale():
    """Art scale for a machine that stands over the board rather than on it.

    Chosen so the whole span - the swept plate off both shoulders is the
    widest part, at 1.7 either side - sits inside the sector you can
    actually see, with a margin. Derived from the view rather than written
    down, so it stays right if the viewport ever changes."""
    return MAP_W * 0.92 / 3.4


PLAIN_ROLES = (
    ("spawner", (118, 186, 108)),      # it puts men or armour on the road
    ("support", (150, 154, 162)),      # walls, radar, workshops, supply
    ("air",     (108, 176, 232)),      # it can only answer aircraft
    ("splash",  (228, 108, 62)),       # it goes off over an area
    ("long",    (196, 138, 226)),      # it reaches most of the way across
    ("gun",     (226, 198, 96)),       # and everything else
)
_PLAIN_COL = {}


def plain_role(kind):
    """Which of the six an emplacement belongs to, for the plain view."""
    d = TOWER_TYPES[kind]
    if kind in SPAWNER_SQUADS:
        return "spawner"
    if not d.get("dmg") or not d.get("rng"):
        return "support"
    if d.get("hits_air") and not d.get("hits_ground"):
        return "air"
    if d.get("splash"):
        return "splash"
    if d.get("rng", 0) >= 400:
        return "long"
    return "gun"


def plain_colour(kind):
    got = _PLAIN_COL.get(kind)
    if got is None:
        role = plain_role(kind)
        got = next(c for r, c in PLAIN_ROLES if r == role)
        _PLAIN_COL[kind] = got
    return got


