_PLAIN_ARM = {}
_PUPPETS = {}


def model_puppet(kind):
    """One Enemy per model, kept and reposed rather than rebuilt. It is
    never in `game.enemies` - it exists to be drawn."""
    got = _PUPPETS.get(kind)
    if got is None:
        got = _PUPPETS[kind] = Enemy(kind, 1, DIFF_BY_KEY["normal"],
                                     "kingdom")
        got.alt = 0
    return got


def plain_arm_colour(key):
    got = _PLAIN_ARM.get(key)
    if got is None:
        arm = ALLY_UNITS[key].get("arm", "infantry")
        got = next((c for r, c in PLAIN_ARMS if r == arm),
                   PLAIN_ARMS[-1][1])
        _PLAIN_ARM[key] = got
    return got


def draw_boss_front(surf, kind, cx, cy, s):
    """One boss, facing the viewer. `cy` is ground level; `s` scales it."""
    if kind in V_FRONT:
        # red lacquer, black iron, gold on every edge that was meant to
        # last - and each of the five a different shape on the ground.
        w, h, form = V_FRONT[kind]
        lac = ENEMY_TYPES[kind]["col"]
        dk, gold = shade(lac, 0.34), (222, 186, 104)
        lit = shade(lac, 1.30)

        def box(x0, y0, x1, y1, col, edge=None):
            r = [(cx + x0 * s, cy - y0 * s), (cx + x1 * s, cy - y0 * s),
                 (cx + x1 * s, cy - y1 * s), (cx + x0 * s, cy - y1 * s)]
            pygame.draw.polygon(surf, col, r)
            pygame.draw.polygon(surf, edge or dk, r,
                                max(1, int(s * 0.035)))

        if form == "tank":
            # a supertank: two track units, a slab, and the guns
            for sgn in (-1, 1):
                box(sgn * w * 0.42, 0, sgn * w, h * 0.30, (44, 40, 40))
                for i in range(6):
                    q = -w + i * (w * 0.34)
                    pygame.draw.circle(
                        surf, (86, 80, 78),
                        (int(cx + sgn * abs(q) * s * 0.62),
                         int(cy - h * 0.14 * s)), max(2, int(s * 0.09)))
            box(-w * 0.92, h * 0.26, w * 0.92, h * 0.66, lac, gold)
            box(-w * 0.46, h * 0.62, w * 0.46, h * 0.92, lit, gold)
            for i in range(3):                    # the plasma barrels
                q = (i - 1) * w * 0.34
                box(q - w * 0.07, h * 0.70, q + w * 0.07, h * 1.34,
                    (52, 46, 46))
                pygame.draw.circle(surf, (255, 170, 110),
                                   (int(cx + q * s), int(cy - h * 1.34 * s)),
                                   max(2, int(s * 0.09)))
        elif form == "abom":
            # three machines fused and none of the joins clean
            for sgn in (-1, 1):
                box(sgn * w * 0.30, 0, sgn * w * 0.98, h * 0.52,
                    shade(lac, 0.80))
                for i in range(4):                # the laser bank
                    q = h * (0.58 + i * 0.11)
                    pygame.draw.line(
                        surf, (255, 120, 96),
                        (cx + sgn * w * 0.34 * s, cy - q * s),
                        (cx + sgn * w * 1.16 * s, cy - q * s),
                        max(1, int(s * 0.05)))
            box(-w * 0.62, h * 0.34, w * 0.62, h * 1.02, lac, gold)
            # the maw
