        WOUND = (112, 40, 46)

        def _strings(n, top, spread, into):
            """What is holding it up. They come down from ABOVE the plate,
            which is the whole of the nation in one mark."""
            for i in range(n):
                fx = (i / max(1, n - 1.0) - 0.5) * spread
                L(fx * 0.55, -134, fx, into, THREAD, 1)

        def _stitch(pts):
            for (sx, sy, ln, tilt) in pts:
                ex, ey = sx + ln * tilt, sy + ln
                L(sx, sy, ex, ey, WOUND, 2)
                for j in range(3):
                    f = (j + 0.5) / 3.0
                    mx, my = sx + (ex - sx) * f, sy + (ey - sy) * f
                    L(mx - 4, my - 2, mx + 4, my + 2, THREAD, 1)

