# ----------------------------------------------------------------------------
# THE CORRIDOR. The opening, and the only scene in the game that plays
# before the menu rather than after a tour.
#
# There are fifteen cutscenes in this file and every one of them is a
# PAYOFF - the siege ends, the forge opens, the sun goes out. Nothing set
# any of it up. A player started the game, picked NORMAL off a list, and
# was holding a road against red shapes for reasons nobody had said.
#
# What it has to establish, and no more than that:
#
#   - the player is GREEN TEAM, which the game does not otherwise say out
#     loud until one line of dialogue in chapter four
#   - the road is the whole reason. One corridor, everything behind it
#   - the Crimson Pact asked, and was already moving when it asked
#   - it is a HOLDING action, not a conquest
#
# ...and one line that is a fuse rather than an explanation: THEY WILL
# TELL YOU THE ENEMY IS A MACHINE / SOMEBODY IS DRIVING IT. That is the
# photograph in the Blood Red's cockpit, hours of play early, and it is
# the only thing here the scene does not answer itself.
#
# It does NOT say who is right. The scene after the siege is won opens
# with "they will call this a victory - it was not", and a triumphant
# opening would make a liar of it before it was ever spoken.
# ----------------------------------------------------------------------------
IN_LINE_LIFE = 3.0
IN_SPEECH = [
    (1.2, "THERE IS ONE ROAD THROUGH THIS VALLEY."),
    (4.6, "EVERYTHING BEHIND US COMES DOWN IT."),
    (8.0, "IN THE SPRING THE CRIMSON PACT ASKED US TO STAND ASIDE."),
    (11.4, "THEY DID NOT SAY WHAT FOR."),
    (14.8, "THEY WERE ALREADY MOVING WHEN THEY ASKED."),
    (18.2, "GREEN TEAM IS WHAT IS LEFT OF THE ARMY THAT SAID NO."),
    (21.6, "WE ARE NOT WINNING. WE ARE HOLDING."),
    (25.0, "THEY WILL TELL YOU THE ENEMY IS A MACHINE."),
    (28.4, "SOMEBODY IS DRIVING IT."),
    (31.8, "YOU HAVE THE GUNS, THE GROUND, AND THE TIME BETWEEN WAVES."),
    (35.2, "THAT IS THE WHOLE WAR."),
]
IN_RED_AT = 8.0             # the far end starts to glow
IN_MARCH_AT = 14.8          # ...and it is full of shapes, walking
IN_HOLD_AT = 18.2           # the line stands up in the foreground
IN_GUNS_AT = 31.8           # and the emplacements go in beside the road
IN_TITLE_AT = 39.4
IN_SUB_AT = 42.4
IN_END = 47.4
IN_VP_Y = 372               # the vanishing point, where the road ends


def in_valley(surf, t):
    """Sky, ridges and the road, in one-point perspective. The whole scene
    is this shape - everything else stands on it."""
    red = clamp((t - IN_RED_AT) / 9.0, 0.0, 1.0)
    cx = WIN_W // 2
    # ---- sky: cold at the top, and the far end going wrong -------------
    for y in range(0, IN_VP_Y + 60, 4):
        f = y / float(IN_VP_Y + 60)
        col = (clamp(int(18 + 44 * f + 52 * red * f * f), 0, 255),
               clamp(int(24 + 44 * f - 10 * red * f), 0, 255),
               clamp(int(34 + 46 * f - 18 * red * f), 0, 255))
        pygame.draw.rect(surf, col, (0, y, WIN_W, 4))
    if red > 0:                                   # the glow at the far end
        gl = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
        for r in range(9, 0, -1):
            pygame.draw.circle(gl, (150, 30, 26, int(13 * red)),
                               (cx, IN_VP_Y), 34 + r * 26)
        surf.blit(gl, (0, 0))
    # ---- the ground ----------------------------------------------------
    pygame.draw.rect(surf, (26, 32, 26),
                     (0, IN_VP_Y, WIN_W, WIN_H - IN_VP_Y))
    # ---- the road: a trapezoid to the vanishing point ------------------
    pygame.draw.polygon(surf, (62, 62, 56),
                        [(cx - 26, IN_VP_Y), (cx + 26, IN_VP_Y),
                         (cx + 430, WIN_H), (cx - 430, WIN_H)])
    for i in range(1, 9):                          # the centre line
        f = (i / 9.0) ** 2.4
        y = IN_VP_Y + (WIN_H - IN_VP_Y) * f
        pygame.draw.rect(surf, (128, 126, 104),
                         (cx - max(1, int(4 * f)), y,
                          max(2, int(8 * f)), max(2, int(26 * f))))
    # ---- the ridges either side, closing it in -------------------------
    for sgn in (-1, 1):
        pygame.draw.polygon(surf, (14, 20, 20), [
            (cx + sgn * 30, IN_VP_Y),
            (cx + sgn * 250, IN_VP_Y - 66),
            (cx + sgn * 520, IN_VP_Y - 150),
            (cx + sgn * 900, IN_VP_Y - 96),
            (cx + sgn * 900, WIN_H), (cx + sgn * 470, WIN_H)])


def in_column(surf, t):
    """The Pact on the road. They start at the vanishing point as marks and
    are recognisable by the time the scene ends, which is the whole of what
    the opening has to say about them."""
    if t < IN_MARCH_AT:
        return
    cx = WIN_W // 2
    walk = clamp((t - IN_MARCH_AT) / 26.0, 0.0, 1.0)
    for i in range(14):
        # each one is further along the road than the one behind it
        f = ((i * 0.073 + walk * 0.62) % 1.0) ** 2.2
        if f < 0.012:
            continue
        y = IN_VP_Y + (WIN_H - IN_VP_Y) * f
        h = 4 + 116 * f
        x = cx + ((i * 37) % 7 - 3) * (12 + 46 * f)
        col = (clamp(int(96 + 92 * f), 0, 255), int(26 + 24 * f),
               int(24 + 22 * f))
        if i % 4 == 3:                             # something with a hull
            pygame.draw.rect(surf, col,
                             (x - h * 0.52, y - h * 0.50, h * 1.04, h * 0.34))
            pygame.draw.rect(surf, col,
                             (x - h * 0.26, y - h * 0.70, h * 0.44, h * 0.24))
            pygame.draw.line(surf, col, (x + h * 0.10, y - h * 0.60),
                             (x + h * 0.86, y - h * 0.64),
                             max(1, int(h * 0.07)))
            pygame.draw.rect(surf, (18, 14, 16),
                             (x - h * 0.52, y - h * 0.17, h * 1.04, h * 0.17))
        else:                                       # ...and somebody walking
            sw = math.sin(t * 4.4 + i) * h * 0.10
            pygame.draw.line(surf, col, (x, y - h * 0.52), (x, y - h * 0.16),
                             max(1, int(h * 0.17)))
            pygame.draw.circle(surf, col, (int(x), int(y - h * 0.62)),
                               max(1, int(h * 0.11)))
            for sgn in (-1, 1):
                pygame.draw.line(surf, col, (x, y - h * 0.16),
                                 (x + sgn * sw, y), max(1, int(h * 0.08)))


def in_gun(surf, x, gy, h, col, up):
    """An emplacement going in: the pit, the mount, and a barrel that comes
    up to the horizontal as `up` runs 0 -> 1."""
    pygame.draw.rect(surf, col,
                     (x - h * 0.62, gy - h * 0.34, h * 1.24, h * 0.34))
    pygame.draw.rect(surf, col,
                     (x - h * 0.30, gy - h * 0.62, h * 0.60, h * 0.32))
    a = -1.15 + 1.15 * up
    pygame.draw.line(surf, col, (x, gy - h * 0.56),
                     (x + math.cos(a) * h * 1.10,
                      gy - h * 0.56 + math.sin(a) * h * 1.10),
                     max(2, int(h * 0.15)))


class IntroCutscene:
    """THE CORRIDOR. Why there is a line, and why it is you holding it.

    Same contract as the other fifteen - `update`, `draw`, `skip`, `done`.
    The one thing it does that none of them do is ask for MUSIC: the menu
    piece, under all of it, because THE GREY HOUR is the game's own theme
    and this is the first thing a player ever hears."""

    TRACK = MENU_TRACK

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()
        self.rnd = random.Random(11)
        # the line that stands up at IN_HOLD_AT, decided once so it does
        # not shuffle itself every frame
        self.line = [(96 + i * 118 + self.rnd.randrange(-16, 16),
                      self.rnd.choice((2, 2, 2, 0)),
                      74 + self.rnd.randrange(-8, 14))
                     for i in range(11)]

    def skip(self):
        """One press jumps to the title; a second ends it."""
        if self.t < IN_TITLE_AT - 0.4:
            self.t = IN_TITLE_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for at, snd in ((IN_RED_AT, "leak"), (IN_MARCH_AT, "wave"),
                        (IN_HOLD_AT, "build"), (IN_GUNS_AT, "build"),
                        (IN_TITLE_AT, "upgrade")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= IN_END:
            self.done = True

    def draw(self, sc):
        t = self.t
        sc.fill((10, 12, 16))
        in_valley(sc, t)
        in_column(sc, t)
        # ---- the guns, going in beside the road ------------------------
        if t >= IN_GUNS_AT:
            up = clamp((t - IN_GUNS_AT) / 2.6, 0.0, 1.0)
            for sgn, dx, gy, h in ((-1, 300, 690, 56), (1, 322, 700, 60),
                                   (-1, 470, 620, 40), (1, 486, 616, 38)):
                in_gun(sc, WIN_W // 2 + sgn * dx, gy, h, (34, 46, 34), up)
        # ---- the line itself -------------------------------------------
        if t >= IN_HOLD_AT:
            rise = clamp((t - IN_HOLD_AT) / 1.6, 0.0, 1.0)
            for x, pose, h in self.line:
                cs_soldier(sc, x, WIN_H - 26, h * (0.55 + 0.45 * rise),
                           (22, 34, 26), pose, t)
        # ---- the narration ---------------------------------------------
        for at, line in IN_SPEECH:
            if not at <= t < at + IN_LINE_LIFE:
                continue
            a = min(clamp((t - at) / 0.5, 0, 1),
                    clamp((at + IN_LINE_LIFE - t) / 0.6, 0, 1))
            img = FONTS.render(line, 24, (226, 230, 216)).copy()
            img.set_alpha(int(255 * a))
            sc.blit(img, img.get_rect(center=(WIN_W // 2, 112)))
        # ---- and the title ---------------------------------------------
        if t >= IN_TITLE_AT - 1.2:
            dim = clamp((t - (IN_TITLE_AT - 1.2)) / 1.6, 0, 1)
            sh = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
            sh.fill((0, 0, 0, int(224 * dim)))
            sc.blit(sh, (0, 0))
        if t >= IN_TITLE_AT:
            a = clamp((t - IN_TITLE_AT) / 1.0, 0, 1)
            img = FONTS.render("OPERATION: IRON LINE", 58,
                               (206, 176, 78)).copy()
            img.set_alpha(int(255 * a))
            sc.blit(img, img.get_rect(center=(WIN_W // 2, 330)))
            w = int(300 * a)
            pygame.draw.line(sc, (150, 40, 36),
                             (WIN_W // 2 - w, 380), (WIN_W // 2 + w, 380), 2)
        if t >= IN_SUB_AT:
            a = clamp((t - IN_SUB_AT) / 1.0, 0, 1)
            img = FONTS.render("HOLD THE CORRIDOR.", 26,
                               (226, 230, 216)).copy()
            img.set_alpha(int(255 * a))
            sc.blit(img, img.get_rect(center=(WIN_W // 2, 424)))
        if t > IN_END - 1.4:                            # out to black
            a = clamp((t - (IN_END - 1.4)) / 1.4, 0, 1)
            sh = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
            sh.fill((0, 0, 0, int(255 * a)))
            sc.blit(sh, (0, 0))
        FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                   (120, 116, 108), "right")


# ----------------------------------------------------------------------------
# THE CUTSCENE. Plays once, the first time the siege is won.
#
# Four beats on one wide stage that the camera pans across: the line
# celebrating, the ground between, the wreck of the Blood Red, and then what
# was found in its cockpit. Everything is drawn, like the rest of the game.
# ----------------------------------------------------------------------------
# (start, line). Each is on screen for CS_LINE_LIFE, and they are spaced
# further apart than that - two lines drawn over each other is unreadable.
CS_LINE_LIFE = 3.0
CS_SPEECH = [
    (1.0, "THEY WILL CALL THIS A VICTORY."),
    (4.4, "IT WAS NOT. IT WAS A DEBT, AND WE PAID IT."),
    (7.8, "EVERY SOLDIER WHO HELD THIS LINE PAID IT IN FULL."),
    (11.2, "REMEMBER THEIR NAMES."),
    (14.6, "THAT IS THE ONLY HONOUR THERE IS."),
]
CS_PAN_START, CS_PAN_END = 18.6, 24.6        # celebration -> the wreck
CS_PHOTO_AT = 27.6                            # the photo comes up
CS_LINE1_AT = 32.6
CS_LINE2_AT = 35.6
CS_REDACT_AT = 39.2
CS_END = 45.6
CS_STAGE_W = 2400                             # the stage is wider than the view


def cs_soldier(surf, x, y, h, col, pose=0, t=0.0):
    """One figure in side elevation, silhouetted against the sky."""
    hd = h * 0.16
    pygame.draw.circle(surf, col, (int(x), int(y - h + hd)), int(hd))
    pygame.draw.line(surf, col, (x, y - h + hd * 1.6), (x, y - h * 0.42),
                     max(2, int(h * 0.16)))                       # torso
    for sgn in (-1, 1):                                            # legs
        pygame.draw.line(surf, col, (x, y - h * 0.44),
                         (x + sgn * h * 0.16, y), max(2, int(h * 0.11)))
    if pose == 0:                       # rifle held aloft in both hands
        bob = math.sin(t * 3.0 + x * 0.05) * h * 0.05
        ax, ay = x, y - h * 1.02 - bob
        pygame.draw.line(surf, col, (x, y - h * 0.78), (ax - h * 0.22, ay),
                         max(2, int(h * 0.10)))
        pygame.draw.line(surf, col, (x, y - h * 0.78), (ax + h * 0.22, ay),
                         max(2, int(h * 0.10)))
        pygame.draw.line(surf, col, (ax - h * 0.40, ay + h * 0.05),
                         (ax + h * 0.40, ay - h * 0.05),
                         max(2, int(h * 0.07)))                   # the rifle
    elif pose == 1:                     # both arms up
        bob = math.sin(t * 2.4 + x * 0.07) * h * 0.07
        for sgn in (-1, 1):
            pygame.draw.line(surf, col, (x, y - h * 0.76),
                             (x + sgn * h * 0.30, y - h * 1.06 - bob),
                             max(2, int(h * 0.10)))
    else:                               # standing, helmet bowed
        pygame.draw.line(surf, col, (x, y - h * 0.74),
                         (x + h * 0.20, y - h * 0.44), max(2, int(h * 0.10)))
        pygame.draw.line(surf, col, (x, y - h * 0.74),
                         (x - h * 0.16, y - h * 0.40), max(2, int(h * 0.10)))


def cs_wreck(surf, cx, gy, sc, t):
    """The Blood Red, broken. The silhouette it had, with pieces missing."""
    WH = (176, 168, 168)
    RD = (128, 40, 44)
    DK = (44, 30, 32)

    def P(pts, col, w=0):
        pygame.draw.polygon(surf, col, [(cx + a * sc, gy + b * sc)
                                        for a, b in pts], w)

    def L(x1, y1, x2, y2, col, w=3):
        pygame.draw.line(surf, col, (cx + x1 * sc, gy + y1 * sc),
                         (cx + x2 * sc, gy + y2 * sc), max(1, int(w * sc)))
    # the hull, slumped forward onto its knees
    P([(-52, -6), (-18, -10), (-6, -54), (-46, -50)], RD)
    P([(-52, -6), (-18, -10), (-6, -54), (-46, -50)], DK, 3)
    P([(-40, -52), (26, -60), (34, -104), (-30, -96)], WH)     # torso, tilted
    P([(-40, -52), (26, -60), (34, -104), (-30, -96)], DK, 3)
    P([(-24, -66), (16, -72), (20, -92), (-20, -86)], RD)      # chest panel
    # one pauldron still on, one torn away and lying in the dirt
    P([(-30, -100), (14, -112), (22, -84), (-24, -76)], WH)
    P([(-30, -100), (14, -112), (22, -84), (-24, -76)], DK, 3)
    L(-24, -96, 14, -82, DK, 4)
    L(-24, -82, 14, -96, DK, 4)
    P([(58, -14), (104, -22), (110, -4), (60, 0)], WH)         # torn-off plate
    P([(58, -14), (104, -22), (110, -4), (60, 0)], DK, 3)
    # the head, hanging
    P([(6, -118), (34, -122), (36, -102), (8, -98)], (150, 146, 146))
    P([(6, -118), (34, -122), (36, -102), (8, -98)], DK, 3)
    L(10, -110, 32, -113, (86, 30, 32), 4)                     # dead visor
    L(14, -122, 30, -142, WH, 5)                               # one horn left
    # the polearm, snapped, planted in the ground
    L(-96, 0, -66, -70, (60, 52, 52), 5)
    for i in range(4):
        a2 = i * 1.5708 + 0.5
        tx2, ty2 = -66 + math.cos(a2) * 20, -70 + math.sin(a2) * 20
        P([(tx2, ty2), (-66 + math.cos(a2 + 0.5) * 8,
                        -70 + math.sin(a2 + 0.5) * 8), (-66, -70),
           (-66 + math.cos(a2 - 0.5) * 8, -70 + math.sin(a2 - 0.5) * 8)],
          (150, 146, 146))
    # fire and smoke still coming off it
    rnd = random.Random(int(t * 3) % 97)
    for i in range(9):
        fx = cx + rnd.uniform(-40, 30) * sc
        fy = gy - rnd.uniform(20, 90) * sc
        f = 0.5 + 0.5 * math.sin(t * 4 + i)
        pygame.draw.circle(surf, (int(200 + 40 * f), int(90 + 60 * f), 40),
                           (fx, fy), (2 + 3 * f) * sc)
    for i in range(7):
        sx = cx + math.sin(t * 0.4 + i) * 26 * sc
        sy = gy - (60 + ((t * 24 + i * 40) % 220)) * sc
        a2 = max(0, 90 - ((t * 24 + i * 40) % 220) * 0.4)
        srf = pygame.Surface((int(46 * sc), int(46 * sc)), pygame.SRCALPHA)
        pygame.draw.circle(srf, (70, 66, 66, int(a2)),
                           (int(23 * sc), int(23 * sc)), int(20 * sc))
        surf.blit(srf, (sx - 23 * sc, sy - 23 * sc))


def cs_photo(surf, cx, cy, sc, blood, redact, tears=0.0):
    """The photograph found in the cockpit. `blood`, `redact` and `tears`
    are 0..1. Tears cut pale runs down through the stain - the print has
    been held and wept over since, and it shows."""
    W, H = int(430 * sc), int(320 * sc)
    x0, y0 = int(cx - W / 2), int(cy - H / 2)
    pygame.draw.rect(surf, (238, 232, 218), (x0 - 9, y0 - 9, W + 18, H + 18))
    pygame.draw.rect(surf, (176, 168, 152), (x0 - 9, y0 - 9, W + 18, H + 18), 2)
    pygame.draw.rect(surf, (150, 156, 148), (x0, y0, W, H))       # the print
    for i in range(0, H, 3):                                       # old film
        pygame.draw.line(surf, (142, 148, 141), (x0, y0 + i),
                         (x0 + W, y0 + i), 1)
    gy = y0 + H - int(18 * sc)

    def figure(fx, h, coat, skin, hair, kind):
        pygame.draw.line(surf, coat, (fx, gy - h * 0.46), (fx, gy),
                         max(3, int(h * 0.30)))                    # legs/skirt
        pygame.draw.rect(surf, coat,
                         (fx - h * 0.20, gy - h * 0.80, h * 0.40, h * 0.40))
        pygame.draw.circle(surf, skin, (int(fx), int(gy - h * 0.90)),
                           int(h * 0.13))
        pygame.draw.arc(surf, hair,
                        (fx - h * 0.15, gy - h * 1.05, h * 0.30, h * 0.30),
                        0.2, 3.0, max(2, int(h * 0.07)))
        if kind == "general":                                      # cap + braid
            pygame.draw.rect(surf, (58, 62, 58),
                             (fx - h * 0.16, gy - h * 1.06, h * 0.32,
                              h * 0.09))
            pygame.draw.line(surf, (196, 168, 70),
                             (fx - h * 0.14, gy - h * 0.70),
                             (fx + h * 0.14, gy - h * 0.70), 2)
        if kind == "girl":                                          # a ribbon
            pygame.draw.circle(surf, (206, 96, 120),
                               (int(fx + h * 0.14), int(gy - h * 0.98)),
                               max(2, int(h * 0.06)))
        return (fx, gy - h * 0.92)                                 # eye height

    hh = H * 0.66
    e_gen = figure(x0 + W * 0.27, hh, (74, 78, 74), (214, 178, 152),
                   (58, 50, 46), "general")
    e_wife = figure(x0 + W * 0.73, hh, (120, 74, 86), (222, 190, 166),
                    (70, 54, 48), "wife")
    e_girl = figure(x0 + W * 0.50, hh * 0.62, (176, 150, 96), (226, 198, 176),
                    (96, 68, 52), "girl")
    # the blood, soaked into the print from one corner
    if blood > 0:
        b = pygame.Surface((W, H), pygame.SRCALPHA)
        rnd = random.Random(11)
        # soaked in from the bottom-left corner and creeping up. It has to
        # read as a stain on a photograph, not as paint over the faces.
        for i in range(46):
            f = rnd.random()
            if f > blood:
                continue
            r = rnd.uniform(8, 30) * sc * (0.5 + 0.5 * blood)
            bx = rnd.gauss(W * 0.16, W * 0.20)
            by = rnd.gauss(H * 0.88, H * 0.16)
            pygame.draw.circle(b, (98, 10, 14, int(70 + 70 * blood)),
                               (int(bx), int(by)), int(r))
        for i in range(7):                       # a few runs down the print
            bx = W * (0.06 + rnd.random() * 0.42)
            top = H * (0.52 + rnd.random() * 0.22)
            pygame.draw.line(b, (92, 10, 14, int(90 * blood)),
                             (int(bx), int(top)), (int(bx), int(H)),
                             int(rnd.uniform(3, 9) * sc))
        surf.blit(b, (x0, y0))
    # tears: pale runs where the print has been wept on and rubbed
    if tears > 0:
        tr = pygame.Surface((W, H), pygame.SRCALPHA)
        rnd2 = random.Random(23)
        for i in range(11):
            if rnd2.random() > tears:
                continue
            tx = W * (0.16 + rnd2.random() * 0.70)
            top = H * rnd2.uniform(0.10, 0.46)
            wdt = int(rnd2.uniform(4, 13) * sc)
            for k in range(int(H - top)):
                al = int(52 * tears * (1.0 - k / max(1.0, H - top)) + 16 * tears)
                pygame.draw.line(tr, (228, 232, 226, al),
                                 (int(tx), int(top + k)),
                                 (int(tx + wdt), int(top + k)))
            pygame.draw.circle(tr, (236, 240, 234, int(60 * tears)),
                               (int(tx + wdt / 2), int(top)), int(wdt * 0.7))
        surf.blit(tr, (x0, y0))
    # and the bars
    if redact > 0:
        for (ex, ey) in (e_gen, e_wife):
            bw = int(hh * 0.42 * min(1.0, redact * 1.6))
            bh = int(hh * 0.11)
            pygame.draw.rect(surf, (10, 10, 10),
                             (int(ex - bw / 2), int(ey - bh / 2), bw, bh))
    pygame.draw.rect(surf, (120, 126, 118), (x0, y0, W, H), 2)


# ----------------------------------------------------------------------------
# VENGEANCE. Plays once, after Blood Red Revenge - the end of the campaign.
#
# The photograph a third time. She has carried it through two chapters and it
# has been wept on. She is not going to get up from this one, and she spends
# what is left of her calling someone we never see.
# ----------------------------------------------------------------------------
VG_PHOTO_AT = 0.9            # the print fades up, filling the frame
VG_PULL_AT, VG_PULL_END = 3.4, 8.0     # camera pulls back off it, onto her
VG_RADIO = [(9.0, "THIS IS AMARANTH ACTUAL."),
            (12.0, "THE LINE IS GONE. I AM WHAT IS LEFT OF IT."),
            (15.4, "MERGE YOUR ARMY WITH MINE."),
            (18.6, "...ALL OF IT. EVERY GUN YOU HAVE.")]
VG_RADIO_LIFE = 3.0
VG_GRIP_AT = 22.2            # the hand closes on the print
VG_LINE1_AT = 24.0           # KEEP FIGHTING FOR...
VG_LINE2_AT = 26.8           # VENGEANCE.
VG_BOOM_AT = 29.6            # and the whole thing goes up
VG_EYES_AT = 31.4            # something is still awake in the dark
VG_CUT_AT = 36.0             # hard cut to black
VG_END = 38.0


def vg_her(surf, cx, gy, sc, grip, t):
    """Her, down against a slab and not getting up, seen from the side. The
    field is burning behind her, so she is a silhouette with a warm edge -
    which is the only way a figure this dark reads at all.

    `grip` 0..1 closes the hand on the photograph."""
    DARK = (46, 38, 38)          # above the ground tone, or she is a hole
    LINE = (12, 10, 11)          # and an edge, so the forms separate
    EDGE = (226, 132, 52)        # firelight down her right side
    SKIN = (148, 112, 100)
    BLOOD = (126, 20, 24)

    def P(pts, col, w=0):
        pygame.draw.polygon(surf, col, [(cx + px * sc, gy + py * sc)
                                        for px, py in pts], w)

    def L(x1, y1, x2, y2, col, w=3):
        pygame.draw.line(surf, col, (cx + x1 * sc, gy + y1 * sc),
                         (cx + x2 * sc, gy + y2 * sc), max(1, int(w * sc)))
    breath = math.sin(t * 1.5) * 0.9          # she is still breathing, barely
    # the slab she is propped against
    P([(22, 2), (56, 2), (50, -58), (26, -52)], (26, 22, 23))
    P([(22, 2), (56, 2), (50, -58), (26, -52)], (54, 44, 40), 2)
    # legs, out flat along the ground
    for leg in ([(-62, -6), (-18, -14), (-14, -2), (-60, 4)],
                [(-20, -10), (4, -22), (10, -8), (-16, -1)]):
        P(leg, DARK)
        P(leg, LINE, 2)
    # torso, propped up against the slab
    torso = [(2, -20 + breath), (26, -56 + breath), (14, -66 + breath),
             (-10, -28 + breath)]
    P(torso, DARK)
    P(torso, LINE, 2)
    L(-10, -28 + breath, 14, -66 + breath, EDGE, 2)        # the lit edge
    # the wound, and what is running out of it
    P([(0, -34), (14, -46), (18, -38), (4, -27)], BLOOD)
    for i in range(4):
        L(2 + i * 5, -30, -2 + i * 5, -2, BLOOD, 2)
    # head, tipped back against the slab
    hx, hy = 20, -74 + breath
    pygame.draw.circle(surf, SKIN, (int(cx + hx * sc), int(gy + hy * sc)),
                       int(9 * sc))
    pygame.draw.circle(surf, (18, 15, 16),
                       (int(cx + hx * sc), int(gy + hy * sc)),
                       int(9 * sc), max(1, int(2 * sc)))
    L(hx + 2, hy - 7, hx + 14, hy - 2, (20, 17, 18), 8)    # hair, fallen back
    # the ribbon. Filthy, and the last thing of theirs she has.
    pygame.draw.circle(surf, (176, 60, 76),
                       (int(cx + (hx + 12) * sc), int(gy + (hy - 5) * sc)),
                       max(2, int(3.4 * sc)))
    L(hx + 13, hy - 4, hx + 22, hy + 3, (152, 52, 66), 2)
    # the radio arm, up at her mouth
    L(12, -52 + breath, hx - 3, hy + 7, DARK, 8)
    pygame.draw.rect(surf, (38, 40, 36),
                     (cx + (hx - 8) * sc, gy + (hy + 2) * sc, 7 * sc, 11 * sc))
    L(hx - 5, hy + 2, hx - 5, hy - 6, (68, 70, 62), 2)     # aerial
    if math.sin(t * 9.0) > 0.4:                            # the set is live
        pygame.draw.circle(surf, (120, 226, 140),
                           (int(cx + (hx - 2) * sc), int(gy + (hy + 5) * sc)),
                           max(1, int(1.6 * sc)))
    # and the other arm, holding the print out in front of her
    close = 1.0 - 0.30 * grip
    fx, fy = -30 * close + 4, -46 - 6 * grip
    L(0, -30 + breath, fx, fy, DARK, 8)
    L(0, -30 + breath, fx, fy, EDGE, 1)
    pygame.draw.circle(surf, SKIN, (int(cx + fx * sc), int(gy + fy * sc)),
                       int((6.5 - 1.6 * grip) * sc))
    if grip > 0:                                # the fist closes, knuckles out
        for i in range(3):
            kp = (cx + (fx - 4 + i * 4) * sc, gy + (fy - 5) * sc)
            pygame.draw.circle(surf, SKIN, (int(kp[0]), int(kp[1])),
                               max(1, int(2.0 * grip * sc)))
    return (cx + fx * sc, gy + fy * sc)         # where the print is held


class VengeanceCutscene:
    """The end of the campaign. Skippable, and it only plays once."""

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()
        rnd = random.Random(31)
        # fires burning down the field behind her
        self.fires = [(rnd.uniform(0, WIN_W), rnd.uniform(560, 700),
                       rnd.uniform(14, 42), rnd.uniform(0, 6.283))
                      for _ in range(11)]
        self.embers = [[rnd.uniform(0, WIN_W), rnd.uniform(0, WIN_H),
                        rnd.uniform(-14, 14), rnd.uniform(-46, -14),
                        rnd.uniform(1.4, 3.4)] for _ in range(70)]
        self.wreck = [(rnd.uniform(-40, WIN_W + 40), rnd.uniform(300, 560),
                       rnd.uniform(40, 150), rnd.uniform(30, 90))
                      for _ in range(9)]

    def skip(self):
        if self.t < VG_GRIP_AT - 0.4:
            self.t = VG_GRIP_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for (lx, ly, vx, vy, r) in self.embers:
            pass
        for e in self.embers:
            e[0] += e[2] * dt
            e[1] += e[3] * dt
            if e[1] < -10:
                e[1] = WIN_H + 10
        for at, snd in ((VG_RADIO[0][0], "deny"), (VG_BOOM_AT, "boom"),
                        (VG_CUT_AT, "leak")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= VG_END:
            self.done = True

    def draw(self, sc):
        t = self.t
        if t >= VG_CUT_AT:                       # the cut is hard, not a fade
            sc.fill((0, 0, 0))
            FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                       (48, 46, 44), "right")
            return
        # ---- after the blast: darkness, and something still awake --------
        if t >= VG_BOOM_AT:
            f = (t - VG_BOOM_AT)
            if f < 0.55:                         # the flash itself
                q = 1.0 - f / 0.55
                v = int(255 * q)
                sc.fill((v, int(v * 0.86), int(v * 0.62)))
                FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                           (48, 46, 44), "right")
                return
            sc.fill((0, 0, 0))
            if t >= VG_EYES_AT:
                e = clamp((t - VG_EYES_AT) / 2.2, 0, 1)
                # one slow blink, so they read as something looking back
                blink = 1.0
                bt = t - VG_EYES_AT - 3.0
                if 0.0 < bt < 0.34:
                    blink = abs(math.cos(bt / 0.34 * math.pi))
                for g in (-1, 1):
                    ex = WIN_W // 2 + g * 62
                    ey = WIN_H // 2 - 10
                    rw, rh = 34, int(15 * blink) + 1
                    glow = pygame.Surface((240, 240), pygame.SRCALPHA)
                    for r2, al in ((104, 8), (68, 12), (38, 20)):
                        pygame.draw.circle(glow, (246, 176, 44,
                                                  int(al * e * blink)),
                                           (120, 120), r2)
                    sc.blit(glow, (ex - 120, ey - 120))
                    pygame.draw.ellipse(sc, (int(214 * e), int(150 * e),
                                             int(36 * e)),
                                        (ex - rw, ey - rh, rw * 2, rh * 2))
                    pygame.draw.ellipse(sc, (int(255 * e), int(226 * e),
                                             int(150 * e)),
                                        (ex - rw * 0.5, ey - rh * 0.6,
                                         rw, rh * 1.2))
            FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                       (48, 46, 44), "right")
            return
        # ---- the field: a horizon, and everything on it burning ----------
        HZ = 486
        sc.fill((13, 11, 12))
        sky = pygame.Surface((WIN_W, HZ), pygame.SRCALPHA)
        for i in range(HZ):                      # smoke, lit from below
            q = (i / float(HZ)) ** 2.4
            pygame.draw.line(sky, (150, 62, 26, int(46 * q)),
                             (0, i), (WIN_W, i))
        sc.blit(sky, (0, 0))
        pygame.draw.rect(sc, (19, 16, 17), (0, HZ, WIN_W, WIN_H - HZ))
        for (fx, _fy, fr, ph) in self.fires:     # fires along the horizon
            fl = 0.6 + 0.4 * math.sin(t * 2.6 + ph)
            fy = HZ - 6
            g2 = pygame.Surface((int(fr * 10), int(fr * 10)), pygame.SRCALPHA)
            for r2, al in ((4.4, 7), (2.8, 12), (1.4, 22)):
                pygame.draw.circle(g2, (230, 126, 40, int(al * fl)),
                                   (int(fr * 5), int(fr * 5)), int(fr * r2))
            sc.blit(g2, (fx - fr * 5, fy - fr * 5))
            pygame.draw.ellipse(sc, (int(220 * fl), int(102 * fl), 28),
                                (fx - fr * 0.45, fy - fr * 0.5,
                                 fr * 0.9, fr * 0.8))
        for (wx, _wy, ww, wh) in self.wreck:     # burnt-out hulls on the line
            top = HZ - wh
            pygame.draw.polygon(sc, (17, 14, 15),
                                [(wx, HZ), (wx + ww * 0.12, top),
                                 (wx + ww * 0.82, top - wh * 0.22),
                                 (wx + ww, HZ)])
            pygame.draw.line(sc, (86, 44, 22), (wx + ww * 0.12, top),
                             (wx + ww * 0.82, top - wh * 0.22), 2)
        # the ground she is lying on, catching the light
        gl = pygame.Surface((WIN_W, WIN_H - HZ), pygame.SRCALPHA)
        for i in range(WIN_H - HZ):
            q = 1.0 - i / float(WIN_H - HZ)
            pygame.draw.line(gl, (168, 74, 28, int(30 * q * q)),
                             (0, i), (WIN_W, i))
        sc.blit(gl, (0, HZ))
        for e in self.embers:
            pygame.draw.circle(sc, (238, 158, 62), (int(e[0]), int(e[1])),
                               int(e[4]))
        # the fire she came to rest beside. Without something bright directly
        # behind her she is a dark shape on dark ground and reads as nothing.
        near_fire = 0.72 + 0.28 * math.sin(t * 3.1)
        nf = pygame.Surface((900, 900), pygame.SRCALPHA)
        for r2, al in ((430, 10), (300, 16), (190, 24), (96, 34)):
            pygame.draw.circle(nf, (238, 126, 40, int(al * near_fire)),
                               (450, 450), r2)
        sc.blit(nf, (WIN_W // 2 - 450 + 120, 640 - 450))
        pygame.draw.ellipse(sc, (int(226 * near_fire), int(112 * near_fire), 30),
                            (WIN_W // 2 + 96, 620, 54, 30))
        # ---- her, and the print ------------------------------------------
        pull = clamp((t - VG_PULL_AT) / (VG_PULL_END - VG_PULL_AT), 0, 1)
        pull = pull * pull * (3 - 2 * pull)
        grip = clamp((t - VG_GRIP_AT) / 1.4, 0, 1)
        hand = None
        if pull > 0:
            hand = vg_her(sc, WIN_W // 2 - 40, 646,
                          3.2 * (0.55 + 0.45 * pull), grip, t)
        # the photograph: fills the frame, then ends up in her hand
        psc = 1.55 * (1 - pull) + 0.34 * pull
        hx2, hy2 = (hand if hand else (WIN_W // 2, WIN_H // 2))
        px = WIN_W // 2 * (1 - pull) + hx2 * pull
        py = WIN_H // 2 * (1 - pull) + hy2 * pull
        fade = clamp((t - VG_PHOTO_AT) / 1.8, 0, 1)
        if fade > 0:
            cs_photo(sc, px, py, psc, 1.0, 1.0, tears=fade)
            if fade < 1:
                v = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
                v.fill((0, 0, 0, int(255 * (1 - fade))))
                sc.blit(v, (0, 0))
        # ---- her half of the call ----------------------------------------
        for (at, line) in VG_RADIO:
            if at <= t < at + VG_RADIO_LIFE:
                a2 = clamp((t - at) / 0.5, 0, 1) * clamp(
                    (at + VG_RADIO_LIFE - t) / 0.6, 0, 1)
                surf = FONTS.render(line, 21, (206, 202, 194)).copy()
                surf.set_alpha(int(255 * a2))
                sc.blit(surf, surf.get_rect(center=(WIN_W // 2, 132)))
        # ---- and what she says last --------------------------------------
        if t >= VG_LINE1_AT:
            a2 = clamp((t - VG_LINE1_AT) / 0.9, 0, 1)
            surf = FONTS.render("KEEP FIGHTING FOR...", 34,
                                (232, 228, 220)).copy()
            surf.set_alpha(int(255 * a2))
            sc.blit(surf, surf.get_rect(center=(WIN_W // 2, 250)))
        if t >= VG_LINE2_AT:
            a2 = clamp((t - VG_LINE2_AT) / 0.7, 0, 1)
            # blood red, and bigger than anything else in the scene
            surf = FONTS.render("VENGEANCE.", 62, (168, 14, 20)).copy()
            surf.set_alpha(int(255 * a2))
            sc.blit(surf, surf.get_rect(center=(WIN_W // 2, 322)))
        FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                   (96, 92, 90), "right")


class Cutscene:
    """The sequence after the siege. Skippable, and it only plays once."""

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()
        self.rnd = random.Random(4)
        self.soldiers = [(120 + i * 104 + self.rnd.randrange(-20, 20),
                          self.rnd.choice((0, 0, 1, 2)),
                          82 + self.rnd.randrange(-10, 16))
                         for i in range(10)]

    def skip(self):
        """One press jumps to the photo; a second ends it."""
        if self.t < CS_PHOTO_AT - 0.4:
            self.t = CS_PHOTO_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for at, snd in ((CS_PHOTO_AT, "leak"), (CS_REDACT_AT, "deny")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= CS_END:
            self.done = True

    # -- drawing ---------------------------------------------------------
    def _sky(self, sc):
        for i in range(0, WIN_H, 4):
            f = i / float(WIN_H)
            col = (int(lerp(22, 96, f ** 1.6)), int(lerp(26, 52, f ** 1.6)),
                   int(lerp(44, 44, f ** 1.6)))
            pygame.draw.rect(sc, col, (0, i, WIN_W, 4))
        # a low sun behind the smoke
        pygame.draw.circle(sc, (150, 86, 56), (int(WIN_W * 0.16), 486), 104)
        pygame.draw.circle(sc, (186, 112, 62), (int(WIN_W * 0.16), 486), 72)

    def draw(self, sc):
        t = self.t
        self._sky(sc)
        # the camera walks the stage from the celebration to the wreck
        f = clamp((t - CS_PAN_START) / (CS_PAN_END - CS_PAN_START), 0.0, 1.0)
        f = f * f * (3 - 2 * f)                       # ease it
        cam = f * (CS_STAGE_W - WIN_W)
        gy = 566
        pygame.draw.rect(sc, (34, 32, 30), (0, gy, WIN_W, WIN_H - gy))
        pygame.draw.line(sc, (58, 52, 46), (0, gy), (WIN_W, gy), 3)
        for i in range(60):                            # rubble along the line
            rx = (i * 137 % CS_STAGE_W) - cam
            if -40 < rx < WIN_W + 40:
                pygame.draw.circle(sc, (48, 44, 40),
                                   (int(rx), gy + 8 + (i * 29) % 40),
                                   4 + (i % 4))
        # ---- the line, celebrating ---------------------------------------
        for (x, pose, h) in self.soldiers:
            sx = x - cam
            if -60 < sx < WIN_W + 60:
                cs_soldier(sc, sx, gy, h, (16, 18, 18), pose, t)
        fx = 700 - cam                                 # a flag over them
        if -80 < fx < WIN_W + 80:
            pygame.draw.line(sc, (20, 20, 20), (fx, gy), (fx, gy - 190), 5)
            wav = math.sin(t * 2.2) * 8
            pygame.draw.polygon(sc, (26, 24, 24),
                                [(fx, gy - 190), (fx + 104, gy - 176 + wav),
                                 (fx, gy - 142)])
        # ---- the wreck ---------------------------------------------------
        wx = 1760 - cam
        if -300 < wx < WIN_W + 300:
            cs_wreck(sc, wx, gy, 2.05, t)
        # ---- the speech --------------------------------------------------
        if t < CS_PAN_START + 1.5:
            for at, line in CS_SPEECH:
                age = t - at
                if age < 0:
                    continue
                a = (clamp(age / 0.7, 0, 1)
                     * clamp((CS_LINE_LIFE - age) / 0.7, 0, 1))
                if a <= 0.01:
                    continue
                # FONTS.render hands back a CACHED surface - fading it in
                # place would leave that alpha on every other use of the
                # same string, so fade a copy
                surf = FONTS.render(line, 25, (238, 234, 222)).copy()
                surf.set_alpha(int(255 * a))
                sc.blit(surf, surf.get_rect(center=(WIN_W // 2, 596)))
        # ---- the photograph ----------------------------------------------
        if t >= CS_PHOTO_AT - 0.6:
            fade = clamp((t - (CS_PHOTO_AT - 0.6)) / 1.1, 0, 1)
            sh = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
            sh.fill((0, 0, 0, int(232 * fade)))
            sc.blit(sh, (0, 0))
            rise = 1.0 - (1.0 - clamp((t - CS_PHOTO_AT) / 1.4, 0, 1)) ** 2
            blood = clamp((t - CS_PHOTO_AT - 1.0) / 2.2, 0, 1)
            red = clamp((t - CS_REDACT_AT) / 0.28, 0, 1)
            cs_photo(sc, WIN_W // 2, 330 - int(24 * (1 - rise)),
                     0.9 + 0.1 * rise, blood, red)
            for at, line, size in ((CS_LINE1_AT,
                                    "YOU MAY HAVE WON THE BATTLE.", 27),
                                   (CS_LINE2_AT,
                                    "BUT THE WAR IS NOT OVER.", 31)):
                if t < at:
                    continue
                a = clamp((t - at) / 0.8, 0, 1)
                col = (226, 62, 58) if size > 28 else (232, 228, 216)
                surf = FONTS.render(line, size, col).copy()
                surf.set_alpha(int(255 * a))
                sc.blit(surf, surf.get_rect(
                    center=(WIN_W // 2, 566 if size < 30 else 610)))
        if t > CS_END - 1.6:                           # fade to black
            a = clamp((t - (CS_END - 1.6)) / 1.6, 0, 1)
            sh = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
            sh.fill((0, 0, 0, int(255 * a)))
            sc.blit(sh, (0, 0))
        FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                   (120, 116, 108), "right")


# ----------------------------------------------------------------------------
# THE FORGE. Plays once, on first entering chapter three.
#
# The answer to the photograph: the machine going up, and the girl whose eyes
# were never redacted, grown, standing under it. She still wears the ribbon.
# ----------------------------------------------------------------------------
FG_RISE_AT = 1.0            # the gantry lights come up
FG_TILT_START, FG_TILT_END = 5.0, 13.0     # camera cranes up the machine
FG_EYE_AT = 15.5            # the machine wakes
FG_HER_AT = 17.5            # she walks out onto the gantry
FG_LINE_AT = 22.5           # "IT IS FINALLY TIME."
FG_CUT_AT = 27.0            # hard cut to black - no fade
FG_END = 29.5


def fg_worker(surf, x, y, h, col, t, i):
    """A yard hand crossing the floor. They walk - the hall is working, and
    a still figure at this size just reads as a post."""
    step = t * 2.6 + i * 1.9
    bob = abs(math.sin(step)) * h * 0.05
    pygame.draw.circle(surf, col, (int(x), int(y - bob - h * 0.86)),
                       max(1, int(h * 0.14)))
    pygame.draw.line(surf, col, (x, y - bob - h * 0.78),
                     (x, y - bob - h * 0.36), max(2, int(h * 0.17)))
    swing = math.sin(step) * h * 0.24
    pygame.draw.line(surf, col, (x, y - bob - h * 0.72),
                     (x - swing, y - bob - h * 0.42), max(1, int(h * 0.09)))
    for sgn in (-1, 1):
        pygame.draw.line(surf, col, (x, y - bob - h * 0.38),
                         (x + sgn * math.sin(step) * h * 0.28, y),
                         max(1, int(h * 0.11)))


_FG_GLOW = {}


def _fg_glow(rad):
    """One soft red bloom per radius, built once and kept. The machine wears
    about twenty emitters and none of them can afford a new surface a frame."""
    key = max(3, int(rad))
    g = _FG_GLOW.get(key)
    if g is None:
        g = pygame.Surface((key * 6, key * 6), pygame.SRCALPHA)
        for i in range(key * 3, 0, -1):
            q = 1.0 - i / (key * 3.0)
            pygame.draw.circle(g, (255, 66, 46, int(2 + 30 * q * q * q)),
                               (key * 3, key * 3), i)
        g = g.convert_alpha()
        _FG_GLOW[key] = g
    return g


# The Vermilion's proportions, measured off the reference against landmarks
# that are actually visible in it - skull top, pod tops, crotch, elbow, fist -
# and kept here so the thing cannot drift. The two ratios that carry the whole
# read are the last pair: the shoulders are over three times the width of the
# chest, and the skull is under half the chest wide. Get those wrong and it
# stops being a titan and starts being a robot.
FG_H = 200.0                # feet to the top of the skull
FG_SKULL = 0.12             # skull top down to the shoulder line
FG_TORSO = 0.375            # shoulder line down to the crotch
FG_CHEST = 45.0             # chest width, in the same units
FG_SPAN_R = 3.17            # shoulder span / chest width
FG_HEAD_R = 2.50            # chest width / skull width
FG_THIGH_R = 0.65           # thigh width / chest width
FG_KNEE = 0.25              # knee height above the floor
FG_REACH = 0.375            # the fists come down to the upper thigh

# THE SAPPHIRE GUARDIAN is built on the Vermilion's skeleton. The numbers are
# derived from FG_* rather than copied, so the two are the same machine at
# two sizes and cannot drift apart: change the Vermilion's build and the
# Guardian's follows it.
#
# Only the height is its own. The gallery plate allows 135 units over the
# ground line and the V-fin, backpack blades and scale bar all reach about
# 1.2x the body, so the body has to come in under about 112.
SG_H = 102.0                            # ground to the top of the helmet
SG_HEAD = FG_SKULL                      # .120 helmet, same as the skull
SG_SHOULDER = 1.0 - FG_SKULL            # .880 the shoulder line
SG_HIP = SG_SHOULDER - FG_TORSO         # .505 the crotch
SG_KNEE = FG_KNEE                       # .250
SG_CHEST = FG_CHEST / FG_H              # .225 chest width
SG_SPAN = SG_CHEST * FG_SPAN_R / 2.0    # .357 shoulder HALF-width
SG_WAIST = SG_CHEST * FG_THIGH_R        # .146 half the hip block
SG_HEADW = SG_CHEST / FG_HEAD_R / 2.0   # .045 half the helmet


def fg_machine(surf, cx, gy, sc, built, eye, lift=1.0):
    """The Vermilion going up: near-black armour, and every line of it drawn
    by what it has lit. `built` 0..1 is how much of it exists, `eye` 0..1 how
    awake it is - the emitters come up together, so waking is one event."""
    def tone(col):
        # `lift` opens the armour up for the recognition plate in EXTRAS,
        # where there is no hall light to model it. Geometry never changes.
        return tuple(min(255, int(v * lift)) for v in col)
    DKR = tone((24, 15, 16))    # armour in shadow
    MID = tone((40, 25, 26))    # armour
    SEAM = (8, 5, 6)
    RIM = tone((138, 44, 34))   # an edge in the light
    BAND = (104, 28, 24)        # the strips that wrap its limbs

    TOP = -FG_H                                      # -200, skull
    SHOULDER = TOP + FG_SKULL * FG_H                 # -176
    CROTCH = SHOULDER + FG_TORSO * FG_H              # -101
    KNEE = -FG_KNEE * FG_H                           # -50
    FIST = -FG_REACH * FG_H                          # -75
    BALL = SHOULDER + 21                             # -155, shoulder joint
    ELBOW = -120
    CH = FG_CHEST / 2.0                              # 22.5, chest half-width
    HALF = FG_CHEST * FG_SPAN_R / 2.0                # 71, shoulder half-span
    HW = FG_CHEST / FG_HEAD_R / 2.0                  # 10.4, skull half-width
    TH = FG_CHEST * FG_THIGH_R                       # 29, thigh width
    lamps = []

    def P(pts, col, w=0):
        pygame.draw.polygon(surf, col, [(cx + x * sc, gy + y * sc)
                                        for x, y in pts], w)

    def L(x1, y1, x2, y2, col, w=2):
        pygame.draw.line(surf, col, (cx + x1 * sc, gy + y1 * sc),
                         (cx + x2 * sc, gy + y2 * sc), max(1, int(w * sc)))

    def slab(pts):
        P(pts, MID)
        P(pts, SEAM, 3)

    # ---- the ring set behind the shoulders -------------------------------
    if built > 0.45:
        rad = HALF * 0.70
        box = pygame.Rect(cx - rad * sc, gy + (SHOULDER + 30) * sc - rad * sc,
                          rad * 2 * sc, rad * 2 * sc)
        pygame.draw.arc(surf, DKR, box, 0.16, 2.98, max(2, int(10 * sc)))
        pygame.draw.arc(surf, RIM, box, 0.16, 2.98, max(1, int(2 * sc)))
    # ---- legs. They are under it from the first frame --------------------
    for g in (-1, 1):
        slab([(g * 6, CROTCH), (g * (6 + TH), CROTCH),
              (g * (9 + TH), KNEE - 4), (g * 9, KNEE - 4)])       # thigh
        P([(g * 11, KNEE - 8), (g * (7 + TH), KNEE - 8),
           (g * (8 + TH), KNEE + 8), (g * 10, KNEE + 8)], DKR)    # knee block
        slab([(g * 11, KNEE + 2), (g * (8 + TH), KNEE + 2),
              (g * (6 + TH), -9), (g * 13, -9)])                  # shin
        P([(g * 3, -9), (g * (11 + TH), -9), (g * (13 + TH), 3),
           (g * 1, 3)], DKR)                                      # foot
        L(g * 10, CROTCH + 26, g * (7 + TH), CROTCH + 26, BAND, 4)
        L(g * 13, -26, g * (6 + TH), -26, BAND, 4)
        lamps.append((g * (9 + TH / 2), KNEE, 5))
    L(-(6 + TH), CROTCH, -(9 + TH), KNEE - 4, RIM, 2)             # the lit side
    L(-(8 + TH), KNEE + 2, -(6 + TH), -9, RIM, 2)
    # ---- torso: a slab that flares out to the shoulder line ---------------
    if built > 0.15:
        slab([(-CH * 0.66, CROTCH), (CH * 0.66, CROTCH),
              (CH * 0.80, CROTCH - 16), (-CH * 0.80, CROTCH - 16)])
        L(-CH * 0.62, CROTCH - 8, CH * 0.62, CROTCH - 8, BAND, 4)  # hip band
        L(-CH * 0.66, CROTCH - 1, CH * 0.66, CROTCH - 1, SEAM, 3)
        for g in (-1, 1):
            L(g * CH * 0.30, CROTCH - 15, g * CH * 0.52, CROTCH - 2, SEAM, 2)
        slab([(-CH * 0.82, CROTCH - 14), (CH * 0.82, CROTCH - 14),
              (CH, SHOULDER), (-CH, SHOULDER)])
        P([(-CH * 0.58, CROTCH - 20), (CH * 0.58, CROTCH - 20),
           (CH * 0.74, SHOULDER + 8), (-CH * 0.74, SHOULDER + 8)], DKR)
        L(-CH * 0.82, CROTCH - 14, -CH, SHOULDER, RIM, 2)
        L(-CH, SHOULDER, CH, SHOULDER, RIM, 2)
        P([(-CH * 0.54, SHOULDER - 4), (CH * 0.54, SHOULDER - 4),
           (CH * 0.44, SHOULDER + 12), (-CH * 0.44, SHOULDER + 12)], DKR)
    if built > 0.30:
        # the cross down its chest - the shape you see first and remember
        pygame.draw.rect(surf, BAND, (cx - 4.5 * sc, gy + (SHOULDER + 6) * sc,
                                      9 * sc, 58 * sc))
        L(-CH * 0.72, SHOULDER + 20, CH * 0.72, SHOULDER + 20, BAND, 6)
        lamps.append((0, SHOULDER + 40, 10))                  # core
        for g in (-1, 1):
            lamps.append((g * CH * 0.54, SHOULDER + 13, 5.5))  # pec emitters
    # ---- shoulder pods, the widest thing on it ----------------------------
    if built > 0.45:
        for g in (-1, 1):
            slab([(g * CH * 1.00, SHOULDER - 19), (g * HALF, SHOULDER - 10),
                  (g * (HALF - 4), SHOULDER + 26), (g * CH * 1.08,
                                                    SHOULDER + 20)])
            for fx, fy in ((0.30, -9), (0.72, -3), (0.50, 11)):
                lamps.append((g * (CH + (HALF - CH) * fx), SHOULDER + fy, 7.5))
        L(-CH, SHOULDER - 19, -HALF, SHOULDER - 10, RIM, 2)
        L(-HALF, SHOULDER - 10, -(HALF - 4), SHOULDER + 26, RIM, 2)
    # ---- the skull, dropped down between them -----------------------------
    if built > 0.55:
        slab([(-HW, TOP), (HW, TOP), (HW, SHOULDER + 4), (-HW, SHOULDER + 4)])
        L(-HW, TOP, HW, TOP, RIM, 2)
        L(-HW, TOP, -HW, SHOULDER + 4, RIM, 2)
        # the visor: one slot cut across its face. A pair of round eyes read
        # as portholes at the size this thing is usually seen at.
        P([(-HW + 1.6, TOP + 6), (HW - 1.6, TOP + 6),
           (HW - 1.6, TOP + 15), (-HW + 1.6, TOP + 15)], (11, 6, 7))
        L(-HW, TOP + 17, HW, TOP + 17, SEAM, 2)               # chin seam
        # The crown. Five blades off the brow, fanning out and back - it
        # wears one because it is the last thing they ever built, and they
        # meant it to be looked at.
        if eye > 0:
            for g in (-1, 1):                                 # cheek vents
                lamps.append((g * (HW - 1.6), TOP + 21, 1.5))
    # ---- arms, heavy, hung well clear of the chest -------------------------
    if built > 0.70:
        # AX is the arm's inner edge. It has to clear the thigh (6 + TH) or
        # the arms and legs read as one mass down each side.
        AX = 6 + TH + 4
        AW = 26                        # and stay narrower than pod to hip
        for g in (-1, 1):
            bx = g * (AX + AW / 2)
            pygame.draw.circle(surf, MID, (int(cx + bx * sc),
                                           int(gy + BALL * sc)), int(14 * sc))
            pygame.draw.circle(surf, SEAM, (int(cx + bx * sc),
                                            int(gy + BALL * sc)),
                               int(14 * sc), max(1, int(3 * sc)))
            lamps.append((bx, BALL, 7.0))
            slab([(g * AX, BALL - 10), (g * (AX + AW - 2), BALL - 14),
                  (g * (AX + AW), ELBOW + 4), (g * (AX + 3), ELBOW + 8)])
            slab([(g * (AX + 3), ELBOW + 6), (g * (AX + AW), ELBOW),
                  (g * (AX + AW + 1), FIST - 4), (g * (AX + 5), FIST + 2)])
            P([(g * (AX + 4), FIST - 2), (g * (AX + AW + 2), FIST - 8),
               (g * (AX + AW + 3), FIST + 18), (g * (AX + 6), FIST + 24)], DKR)
            L(g * (AX + 2), ELBOW - 14, g * (AX + AW - 1), ELBOW - 18, BAND, 4)
            L(g * (AX + 5), FIST - 18, g * (AX + AW), FIST - 22, BAND, 4)
            lamps.append((g * (AX + AW * 0.6), FIST + 9, 4.5))
        L(-(AX + AW - 2), BALL - 14, -(AX + AW), ELBOW + 4, RIM, 2)
        L(-(AX + AW), ELBOW, -(AX + AW + 1), FIST - 4, RIM, 2)
    # ---- everything it has lit, last, so nothing paints over the bloom ----
    for (lx, ly, lr) in lamps:
        px, py = int(cx + lx * sc), int(gy + ly * sc)
        rr = max(2, int(lr * sc))
        pygame.draw.circle(surf, (18, 10, 11), (px, py), rr)
        pygame.draw.circle(surf, SEAM, (px, py), rr, max(1, int(rr * 0.18)))
        core = (int(52 + 203 * eye), int(14 + 52 * eye), int(12 + 38 * eye))
        pygame.draw.circle(surf, core, (px, py), max(1, int(rr * 0.66)))
        if eye > 0.04:
            g = _fg_glow(rr)
            g.set_alpha(int(255 * min(1.0, eye)))
            surf.blit(g, (px - g.get_width() // 2, py - g.get_height() // 2))
    if built > 0.55 and eye > 0:
        half = (HW - 2.4) * sc
        vy = gy + (TOP + 10.5) * sc
        lit = (int(58 + 197 * eye), int(16 + 54 * eye), int(14 + 40 * eye))
        pygame.draw.line(surf, lit, (cx - half, vy), (cx + half, vy),
                         max(2, int(5 * sc)))
        pygame.draw.line(surf, (255, int(150 + 80 * eye), 130),
                         (cx - half * 0.86, vy), (cx + half * 0.86, vy),
                         max(1, int(1.8 * sc)))
        if eye > 0.04:
            gl = _fg_glow(max(3, int(4 * sc)))
            gl.set_alpha(int(210 * min(1.0, eye)))
            for f in (-0.62, 0.0, 0.62):
                surf.blit(gl, (cx + half * f - gl.get_width() // 2,
                               vy - gl.get_height() // 2))


# ----------------------------------------------------------------------------
# THE FOLDER. Plays once, on first entering chapter four.
#
# Two rooms. In the first, your own commander loses his composure over what
# the scouts brought back. In the second, nobody is losing anything: the
# Syndicate is calmly putting a dead man back together, which is the answer
# to why everything they field keeps getting up again.
# ----------------------------------------------------------------------------
CM_LINE_LIFE = 2.9          # the tightest gap between lines is 3.0s
CM_LINES = [(2.0, "THE SCOUTS ARE BACK. ALL OF THEM."),
            (5.4, "THE SYNDICATE HAS PLANS DRAWN UP FOR US."),
            (8.8, "NOT A FRONT. NOT A PUSH."),
            (11.8, "THEY MEAN TO END GREEN TEAM."),
            (15.2, "AND THERE IS SOMETHING ELSE IN THE FOLDER."),
            (18.6, "SOMETHING THEY WOULD NOT PUT A NAME ON.")]
CM_MARCH_AT = 22.4          # the floor starts keeping time
CM_HEAR_AT = 24.6           # "...TELL ME YOU HEAR THAT."
CM_CUT_AT = 28.8            # hard cut, to somewhere much calmer
CM_CORE_AT = 32.0           # the core is brought up
CM_HEAL_AT = 34.6           # and what it is for
CM_SIT_AT = 38.6            # he sits up
CM_FLARE_AT = 41.4
CM_BLACK_AT = 43.4          # hard cut to black
CM_END = 45.4


def cm_figure(surf, x, gy, h, col, pose=0.0, arm=0.0):
    """A body in a command post, at whatever scale the room is drawn at."""
    pygame.draw.line(surf, col, (x, gy - h * 0.46), (x, gy), int(h * 0.20))
    pygame.draw.rect(surf, col, (x - h * 0.13, gy - h * 0.80,
                                 h * 0.26, h * 0.40))
    pygame.draw.circle(surf, col, (int(x), int(gy - h * 0.90)),
                       int(h * 0.115))
    # the arm he is gesturing with
    pygame.draw.line(surf, col, (x, gy - h * 0.74),
                     (x + math.cos(arm) * h * 0.34,
                      gy - h * 0.74 + math.sin(arm) * h * 0.30),
                     int(h * 0.085))
    pygame.draw.line(surf, col, (x, gy - h * 0.72),
                     (x - h * 0.18 * pose, gy - h * 0.44), int(h * 0.08))


class CommandCutscene:
    """Chapter four's opening. Skippable, and it only plays once."""

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()
        rnd = random.Random(17)
        self.dust = [[rnd.uniform(0, WIN_W), rnd.uniform(60, 560),
                      rnd.uniform(6, 22), rnd.uniform(1.0, 2.4)]
                     for _ in range(60)]
        self.staff = [(280, 1.0), (980, -1.0)]
        # all three keep to the left: one of them standing over the slab
        # hid the only thing in the room worth looking at
        self.techs = [(232, 0.9), (368, 1.05), (654, 0.95)]

    def skip(self):
        if self.t < CM_CUT_AT - 0.4:
            self.t = CM_CUT_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for d in self.dust:
            d[1] += d[3] * dt * (14 if self.t >= CM_MARCH_AT else 4)
            if d[1] > 600:
                d[1] = 60
        for at, snd in ((CM_MARCH_AT, "leak"), (CM_CUT_AT, "deny"),
                        (CM_CORE_AT, "upgrade"), (CM_FLARE_AT, "boom"),
                        (CM_BLACK_AT, "leak")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= CM_END:
            self.done = True

    # ---- room one: the command post ------------------------------------
    def _post(self, sc, t):
        march = clamp((t - CM_MARCH_AT) / 1.4, 0, 1)
        # the whole room keeps time once they are close enough to hear
        beat = math.sin(t * 5.6) * march
        shake = int(beat * 4)
        sc.fill((16, 22, 17))
        pygame.draw.rect(sc, (23, 31, 24), (0, 96, WIN_W, 470))
        for i in range(9):                              # corrugated wall
            pygame.draw.line(sc, (17, 24, 18), (i * 150 + shake, 96),
                             (i * 150 + shake, 566), 5)
        # the lamp, which is the first thing to notice anything
        lx = WIN_W // 2 + int(beat * 26)
        pygame.draw.line(sc, (40, 46, 38), (WIN_W // 2, 96), (lx, 176), 3)
        pygame.draw.circle(sc, (46, 52, 44), (lx, 184), 17)
        pygame.draw.circle(sc, (206, 214, 168), (lx, 184), 11)
        cone = pygame.Surface((520, 420), pygame.SRCALPHA)
        pygame.draw.polygon(cone, (198, 210, 150, 22),
                            [(260, 0), (520, 420), (0, 420)])
        sc.blit(cone, (lx - 260, 190))
        # the map table, and the folder open on it
        pygame.draw.rect(sc, (30, 40, 30), (398 + shake, 452, 490, 96))
        pygame.draw.rect(sc, (54, 68, 48), (398 + shake, 452, 490, 12))
        pygame.draw.rect(sc, (44, 62, 44), (426 + shake, 458, 320, 62))
        for i in range(5):
            pygame.draw.line(sc, (78, 104, 72),
                             (438 + shake + i * 62, 462),
                             (452 + shake + i * 62, 516), 2)
        pygame.draw.rect(sc, (206, 202, 178), (770 + shake, 456, 96, 66))
        pygame.draw.rect(sc, (150, 40, 36), (778 + shake, 462, 80, 9))
        for i in range(4):
            pygame.draw.line(sc, (120, 118, 104), (778 + shake, 480 + i * 10),
                             (854 + shake, 480 + i * 10), 2)
        # radio racks down the left
        for i in range(3):
            pygame.draw.rect(sc, (28, 36, 30), (86 + shake, 300 + i * 84,
                                                120, 74))
            pygame.draw.rect(sc, (44, 54, 44), (86 + shake, 300 + i * 84,
                                                120, 74), 2)
            for j in range(3):
                lit = (150, 220, 130) if (int(t * 3) + i + j) % 3 else (60, 70, 56)
                pygame.draw.circle(sc, lit, (104 + shake + j * 18,
                                             316 + i * 84), 4)
        # the staff, standing very still, and the commander who is not
        for (sx, face) in self.staff:
            cm_figure(sc, sx + shake, 566, 116, (14, 20, 15), 0.0, 0.4 * face)
        pace = math.sin(t * 0.9)
        cx = WIN_W // 2 + pace * 150
        arm = -0.9 + math.sin(t * 4.2) * 0.5
        if t >= CM_HEAR_AT:                    # he has stopped moving
            cx = WIN_W // 2 + 40
            arm = -0.2
        cm_figure(sc, cx + shake, 566, 168, (10, 16, 12),
                  math.cos(t * 0.9) * 0.6, arm)
        pygame.draw.rect(sc, (176, 148, 60),
                         (cx - 12 + shake, 566 - 168 * 0.80, 24, 5))
        pygame.draw.rect(sc, (20, 26, 20), (0, 566, WIN_W, WIN_H - 566))
        for d in self.dust:                    # grit shaken off the roof
            pygame.draw.circle(sc, (120, 130, 104), (int(d[0] + shake),
                                                     int(d[1])), 1)
        for (at, line) in CM_LINES:
            if at <= t < at + CM_LINE_LIFE:
                a = clamp((t - at) / 0.4, 0, 1) * clamp(
                    (at + CM_LINE_LIFE - t) / 0.5, 0, 1)
                surf = FONTS.render(line, 25, (214, 224, 198)).copy()
                surf.set_alpha(int(255 * a))
                sc.blit(surf, surf.get_rect(center=(WIN_W // 2, 660)))
        if t >= CM_HEAR_AT:
            a = clamp((t - CM_HEAR_AT) / 0.6, 0, 1)
            surf = FONTS.render("...TELL ME YOU HEAR THAT.", 30,
                                (236, 226, 190)).copy()
            surf.set_alpha(int(255 * a))
            sc.blit(surf, surf.get_rect(center=(WIN_W // 2, 660)))

    # ---- room two: the scientific quarters ------------------------------
    def _lab(self, sc, t):
        core = clamp((t - CM_CORE_AT) / 1.6, 0, 1)
        heal = clamp((t - CM_HEAL_AT) / 3.0, 0, 1)
        sit = clamp((t - CM_SIT_AT) / 1.6, 0, 1)
        flare = clamp((t - CM_FLARE_AT) / 1.4, 0, 1)
        sc.fill((14, 13, 11))
        pygame.draw.rect(sc, (21, 20, 17), (0, 90, WIN_W, 500))
        for i in range(11):                             # tiled wall
            pygame.draw.line(sc, (27, 25, 20), (i * 118, 90),
                             (i * 118, 590), 3)
        pygame.draw.line(sc, (27, 25, 20), (0, 320), (WIN_W, 320), 3)
        pygame.draw.rect(sc, (18, 17, 15), (0, 590, WIN_W, WIN_H - 590))
        # the column, and the core suspended in it
        cx, cy = 430, 372
        pygame.draw.rect(sc, (26, 26, 24), (cx - 74, 150, 148, 300))
        pygame.draw.rect(sc, (44, 44, 40), (cx - 74, 150, 148, 300), 3)
        pygame.draw.rect(sc, (30, 30, 27), (cx - 92, 442, 184, 40))
        if core > 0:
            g = pygame.Surface((520, 520), pygame.SRCALPHA)
            puls = 0.72 + 0.28 * math.sin(t * 3.4)
            for r, al in ((250, 9), (170, 13), (104, 20), (54, 30)):
                pygame.draw.circle(g, (250, 206, 60,
                                       int(al * core * puls)),
                                   (260, 260), r)
            sc.blit(g, (cx - 260, cy - 260))
            pygame.draw.circle(sc, (206, 160, 34), (cx, cy),
                               int(38 * core * puls))
            pygame.draw.circle(sc, (252, 214, 86), (cx, cy),
                               int(25 * core * puls))
            pygame.draw.circle(sc, (255, 248, 208), (cx, cy),
                               int(12 * core * puls))
        # the cable, and the light that runs down it when it is asked to
        pts = [(cx + 74, cy + 30), (640, 470), (760, 506), (856, 512)]
        pygame.draw.lines(sc, (38, 36, 32), False, pts, 9)
        pygame.draw.lines(sc, (58, 54, 46), False, pts, 4)
        if heal > 0:
            n = int(len(pts) * 1.0)
            for i in range(6):
                f = ((t * 0.9 + i / 6.0) % 1.0)
                px = cx + 74 + (856 - cx - 74) * f
                py = cy + 30 + (512 - cy - 30) * (f ** 0.7)
                pygame.draw.circle(sc, (255, 226, 120), (int(px), int(py)),
                                   int(5 * heal))
        # the slab, and the man on it
        pygame.draw.rect(sc, (30, 30, 28), (790, 508, 300, 22))
        pygame.draw.rect(sc, (46, 46, 42), (790, 508, 300, 5))
        for sx in (818, 1058):
            pygame.draw.rect(sc, (26, 26, 24), (sx, 530, 14, 62))
        # the man himself: legs flat on the slab, and a torso that comes up
        # off it on a hinge at the hips rather than sliding across the frame
        SKIN = (168, 132, 116)
        BODY = (52, 50, 46)          # above the floor tone, or he is invisible
        EDGE = (16, 15, 14)
        hipx, hipy = 962, 498
        pygame.draw.line(sc, EDGE, (824, 502), (hipx, hipy), 36)   # legs
        pygame.draw.line(sc, BODY, (826, 502), (hipx, hipy), 30)
        pygame.draw.rect(sc, (34, 33, 30), (810, 484, 28, 36))     # boots
        pygame.draw.rect(sc, EDGE, (810, 484, 28, 36), 2)
        # ONE convention for the hinge: negative angle is up the screen, and
        # both the torso and the head are placed from it. They used to use
        # opposite signs, so the head came away from the body as he rose.
        ang = -sit * 1.18
        tl = 96
        tx = hipx + tl * math.cos(ang)
        ty = hipy + tl * math.sin(ang)
        pygame.draw.line(sc, EDGE, (hipx, hipy), (tx, ty), 40)     # torso
        pygame.draw.line(sc, BODY, (hipx, hipy), (tx, ty), 34)
        hxx = hipx + (tl + 26) * math.cos(ang)
        hyy = hipy + (tl + 26) * math.sin(ang)
        pygame.draw.circle(sc, SKIN, (int(hxx), int(hyy)), 17)
        pygame.draw.circle(sc, (20, 18, 17), (int(hxx), int(hyy)), 17, 3)
        # the arm that moves first
        if sit > 0.25:
            gr = (sit - 0.25) / 0.75
            a0 = (hipx + 52 * math.cos(ang), hipy + 52 * math.sin(ang))
            a1 = (hipx + 60 + 30 * gr, hipy - 30 * gr)
            pygame.draw.line(sc, EDGE, a0, a1, 20)
            pygame.draw.line(sc, BODY, a0, a1, 15)
            pygame.draw.circle(sc, SKIN, (int(a1[0]), int(a1[1])), 8)
        if heal < 1.0:                               # the wounds, closing
            for i, f in enumerate((0.28, 0.52, 0.76)):
                wx = hipx + (tl * f) * math.cos(ang)
                wy = hipy + (tl * f) * math.sin(ang)
                r = int(10 * (1.0 - heal))
                if r > 0:
                    pygame.draw.circle(sc, (132, 24, 26), (int(wx), int(wy)), r)
        if heal > 0:                                 # and the light in him
            gl = pygame.Surface((300, 150), pygame.SRCALPHA)
            pygame.draw.ellipse(gl, (250, 206, 70, int(44 * heal)),
                                (0, 0, 300, 150))
            sc.blit(gl, (846, 432))
        # the people who do this every day and are not impressed
        for (tx, sc2) in self.techs:
            h2 = 128 * sc2
            cm_figure(sc, tx, 592, h2, (14, 14, 13), 0.0, 0.5)
            # a lab coat, which is the only pale thing in the room
            pygame.draw.polygon(sc, (188, 186, 176),
                                [(tx - h2 * 0.15, 592 - h2 * 0.80),
                                 (tx + h2 * 0.15, 592 - h2 * 0.80),
                                 (tx + h2 * 0.19, 592 - h2 * 0.20),
                                 (tx - h2 * 0.19, 592 - h2 * 0.20)])
            pygame.draw.line(sc, (140, 138, 128), (tx, 592 - h2 * 0.78),
                             (tx, 592 - h2 * 0.22), 2)
        if t >= CM_FLARE_AT:                         # it is brought up hard
            w = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
            w.fill((255, 232, 150, int(210 * flare)))
            sc.blit(w, (0, 0))

    def draw(self, sc):
        t = self.t
        if t >= CM_BLACK_AT:
            sc.fill((0, 0, 0))
            FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                       (48, 46, 44), "right")
            return
        if t < CM_CUT_AT:
            self._post(sc, t)
        else:
            self._lab(sc, t)
        FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                   (96, 100, 88), "right")


# ----------------------------------------------------------------------------
# SECOND SUN. Plays once, after THE LONG DUSK.
#
# They do not bury their dead. The Calamity comes off the field on a hoist,
# goes straight onto a table, and the same fluid that closes a rifleman's
# wounds is driven into something the size of a building. It works. It works
# far better than anyone in the room wanted it to.
# ----------------------------------------------------------------------------
SS_RUSH_AT = 0.8            # the body comes through the doors
SS_TABLE_AT = 5.2           # it is on the table
SS_INJECT_AT = 8.4          # the injector comes down
SS_FLUID_AT = 10.6          # and goes in
SS_SHAKE_AT = 15.2          # the room starts to move
SS_ERUPT_AT = 20.0          # it does not stay down
SS_CUT_AT = 23.4            # hard cut, to our side of the line
SS_LOOM_AT = 26.4           # and what is standing over them
SS_BLACK_AT = 32.6
SS_END = 34.6


SS_BODY = {}                    # the body on the table, drawn once per light


def ss_lying(surf, kind, cx, bottom, sc, tint=0.0):
    """A Calamity on its back. The gallery elevation is a standing figure, so
    it is drawn once and turned on its side - the same machine, which is the
    point: the thing on the table is the thing you fought.

    It is cropped to its own bounds first. draw_boss_front does not centre a
    machine in the surface it is given, so rotating the raw surface left the
    body sitting off the table.

    Redrawing the elevation every frame cost 6ms on its own, so the cold body
    is kept. The light on it is not baked into the cache - it climbs smoothly
    for four seconds, and caching a surface per step just moved the 30ms into
    two dozen hitches during the one shot that has to look calm."""
    key = (kind, round(sc, 3))
    box = SS_BODY.get(key)
    if box is None:
        box = pygame.Surface((1000, 1000), pygame.SRCALPHA)
        draw_boss_front(box, kind, 500, 840, sc)
        r = box.get_bounding_rect()
        if not r.width or not r.height:
            return
        box = pygame.transform.rotate(box.subsurface(r).copy(), 90)
        SS_BODY[key] = box = box.convert_alpha()
    if tint > 0:
        # Added, not multiplied. A multiply blend takes the alpha down with
        # it, which faded the body out at exactly the moment it is supposed
        # to be lighting up from the inside.
        box = box.copy()
        gl = pygame.Surface(box.get_size())
        gl.fill((int(96 * tint), int(66 * tint), int(12 * tint)))
        box.blit(gl, (0, 0), special_flags=pygame.BLEND_RGB_ADD)
    surf.blit(box, (cx - box.get_width() // 2,
                    bottom - box.get_height()))


class SecondSunCutscene:
    """What the Syndicate does after THE LONG DUSK. Skippable, plays once."""

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()
        rnd = random.Random(23)
        self.crew = [(rnd.uniform(120, 1160), rnd.uniform(0.62, 0.86))
                     for _ in range(7)]
        self.grit = [[rnd.uniform(0, WIN_W), rnd.uniform(60, 560),
                      rnd.uniform(1.2, 2.8)] for _ in range(70)]
        self.line = [(x, rnd.uniform(0.86, 1.08)) for x in
                     (196, 300, 404, 508, 612, 716)]

    def skip(self):
        if self.t < SS_CUT_AT - 0.4:
            self.t = SS_CUT_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        shake = 1.0 if self.t >= SS_SHAKE_AT else 0.2
        for g in self.grit:
            g[1] += g[2] * dt * 40 * shake
            if g[1] > 600:
                g[1] = 60
        for at, snd in ((SS_INJECT_AT, "build"), (SS_FLUID_AT, "upgrade"),
                        (SS_SHAKE_AT, "leak"), (SS_ERUPT_AT, "boom"),
                        (SS_CUT_AT, "deny"), (SS_BLACK_AT, "leak")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= SS_END:
            self.done = True

    # ---- the theatre ----------------------------------------------------
    def _ward(self, sc, t):
        quake = clamp((t - SS_SHAKE_AT) / 1.6, 0, 1)
        sh = int(math.sin(t * 22) * 7 * quake)
        erupt = clamp((t - SS_ERUPT_AT) / 1.2, 0, 1)
        fluid = clamp((t - SS_FLUID_AT) / 4.0, 0, 1)
        sc.fill((13, 12, 11))
        pygame.draw.rect(sc, (20, 19, 17), (0, 80, WIN_W, 520))
        for i in range(10):
            pygame.draw.line(sc, (27, 25, 22), (i * 130 + sh, 80),
                             (i * 130 + sh, 600), 3)
        pygame.draw.line(sc, (27, 25, 22), (0, 300), (WIN_W, 300), 3)
        for i in range(4):                              # ward lamps
            lx = 200 + i * 300 + sh
            pygame.draw.rect(sc, (46, 44, 40), (lx - 46, 96, 92, 12))
            pygame.draw.rect(sc, (214, 206, 178), (lx - 40, 100, 80, 5))
        pygame.draw.rect(sc, (18, 17, 15), (0, 600, WIN_W, WIN_H - 600))
        # the table, and how far in it has been wheeled
        roll = clamp((t - SS_RUSH_AT) / (SS_TABLE_AT - SS_RUSH_AT), 0, 1)
        roll = roll * roll * (3 - 2 * roll)
        tx = int(-360 + (WIN_W // 2 + 360) * roll) + sh
        pygame.draw.rect(sc, (34, 33, 30), (tx - 300, 556, 600, 22))
        for wx in (tx - 250, tx - 90, tx + 90, tx + 250):
            pygame.draw.rect(sc, (26, 25, 23), (wx - 8, 578, 16, 34))
            pygame.draw.circle(sc, (48, 46, 42), (wx, 614), 9)
        # the body on it, and what is being done to it
        ss_lying(sc, "supernova" if erupt > 0.35 else "sunfall",
                 tx, 560, 2.3, fluid * 0.8)
        if t >= SS_INJECT_AT:                           # the injector
            drop = clamp((t - SS_INJECT_AT) / 1.8, 0, 1)
            iy = 150 + 250 * drop
            pygame.draw.rect(sc, (40, 38, 34), (tx - 26, 96, 52, iy - 96))
            pygame.draw.rect(sc, (62, 60, 54), (tx - 34, iy - 60, 68, 60))
            pygame.draw.rect(sc, (24, 22, 20), (tx - 22, iy - 52, 44, 44))
            if fluid > 0:
                pygame.draw.rect(sc, (250, 200, 60),
                                 (tx - 20, iy - 50 + 42 * (1 - fluid),
                                  40, 42 * fluid))
            pygame.draw.rect(sc, (150, 148, 140), (tx - 4, iy, 8, 44))
            if fluid > 0:
                gl = pygame.Surface((360, 360), pygame.SRCALPHA)
                for r, al in ((170, 9), (110, 14), (58, 22)):
                    pygame.draw.circle(gl, (252, 206, 70,
                                            int(al * fluid)), (180, 180), r)
                sc.blit(gl, (tx - 180, 470 - 180))
        # The team, in front of the table. They are lit from behind by the
        # thing they are working on, so they read as silhouettes with a pale
        # coat - close enough to see, not close enough to be safe.
        back = 0.0 if t < SS_SHAKE_AT else min(1.0, (t - SS_SHAKE_AT) / 2.4)
        for (cx2, s2) in self.crew:
            hh = 168 * s2
            bx = cx2 + (cx2 - WIN_W / 2) * 0.40 * back
            gy2 = 690
            cm_figure(sc, bx + sh, gy2, hh, (44, 42, 38), 0.0, 0.4 - back)
            pygame.draw.polygon(sc, (140, 138, 130),
                                [(bx - hh * 0.11, gy2 - hh * 0.74),
                                 (bx + hh * 0.11, gy2 - hh * 0.74),
                                 (bx + hh * 0.15, gy2 - hh * 0.26),
                                 (bx - hh * 0.15, gy2 - hh * 0.26)])
            pygame.draw.circle(sc, (58, 56, 50),
                               (int(bx + sh), int(gy2 - hh * 0.90)),
                               int(hh * 0.115))
        for g in self.grit:
            pygame.draw.circle(sc, (128, 116, 92),
                               (int(g[0] + sh), int(g[1])), 1)
        if erupt > 0:                                   # it does not stay down
            w = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
            w.fill((255, 248, 232, int(255 * erupt)))
            sc.blit(w, (0, 0))

    # ---- our side of the line -------------------------------------------
    def _line(self, sc, t):
        loom = clamp((t - SS_LOOM_AT) / 3.4, 0, 1)
        sc.fill((14, 16, 15))
        for i in range(190):                            # a bad sky
            q = i / 189.0
            pygame.draw.line(sc, (int(22 + 40 * q), int(20 + 26 * q),
                                  int(18 + 14 * q)), (0, i), (WIN_W, i))
        gy = 596
        # what is standing on the horizon, coming up out of it
        if loom > 0:
            hz = gy + 120 - int(300 * loom)
            gl = pygame.Surface((1100, 700), pygame.SRCALPHA)
            for r, al in ((470, 8), (320, 11), (180, 16)):
                pygame.draw.circle(gl, (250, 160, 40, int(al * loom)),
                                   (550, 350), r)
            sc.blit(gl, (WIN_W // 2 - 550, hz - 350))
            draw_boss_front(sc, "supernova", WIN_W // 2, hz, 3.0 * loom + 0.4)
        pygame.draw.rect(sc, (17, 20, 17), (0, gy, WIN_W, WIN_H - gy))
        pygame.draw.line(sc, (30, 36, 28), (0, gy), (WIN_W, gy), 4)
        for i in range(0, WIN_W, 90):                   # the parapet
            pygame.draw.rect(sc, (22, 27, 22), (i, gy - 16, 74, 20))
        for (x, s2) in self.line:                       # our people, looking up
            hh = 128 * s2
            cm_figure(sc, x, gy + 6, hh, (10, 13, 11), 0.0, -1.1)
            pygame.draw.rect(sc, (14, 18, 14),
                             (x - hh * 0.14, gy + 6 - hh * 1.02,
                              hh * 0.28, hh * 0.10))
        if t >= SS_LOOM_AT + 1.6:
            a = clamp((t - SS_LOOM_AT - 1.6) / 1.0, 0, 1)
            surf = FONTS.render("IT GOT BACK UP.", 32,
                                (232, 226, 210)).copy()
            surf.set_alpha(int(255 * a))
            sc.blit(surf, surf.get_rect(center=(WIN_W // 2, 700)))

    def draw(self, sc):
        t = self.t
        if t >= SS_BLACK_AT:
            sc.fill((0, 0, 0))
            FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                       (48, 46, 44), "right")
            return
        if t < SS_CUT_AT:
            self._ward(sc, t)
        else:
            self._line(sc, t)
        FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                   (96, 92, 88), "right")


# ----------------------------------------------------------------------------
# BLUE SUN. Plays once, after AMBER HORIZON.
#
# They win. The line holds, the last siege engine burns, and for about nine
# seconds the war is over. Then somebody looks up.
# ----------------------------------------------------------------------------
BL_LINE_LIFE = 3.4
BL_LINES = (
    (3.6, "NOT SO FAST."),
    (7.0, "I HAVE A FEELING SOMETHING BAD IS GOING TO HAPPEN AGAIN."),
    (10.4, "THIS HAS ALREADY HAPPENED A LOT. WE NEED TO B-"),
)
BL_SCREAM_AT = 12.8         # he is cut off by one of his own men
BL_TESS_AT = 15.4           # and by what is coming up out of the horizon
BL_TURN_AT = 20.2           # the sun goes over
BL_SKY_AT = 22.0            # and takes the sky with it
BL_WING_AT = 26.0           # something is in front of it
BL_EYE_AT = 30.0            # and it opens its eye
BL_BLACK_AT = 34.6
BL_END = 36.6

BL_AMBER = ((250, 176, 74), (196, 112, 52), (86, 48, 34))   # sky, top to low
BL_BLUE = ((70, 150, 255), (28, 74, 190), (10, 18, 58))


def bl_mix(a, b, k):
    return tuple(int(a[i] + (b[i] - a[i]) * k) for i in range(3))


# The 16 corners of a hypercube, and the 32 edges that join the pairs one
# coordinate apart. It is the one shape in this game nobody built.
BL_VERTS = tuple((x, y, z, w) for x in (-1, 1) for y in (-1, 1)
                 for z in (-1, 1) for w in (-1, 1))
BL_EDGES = tuple((i, j) for i in range(16) for j in range(i + 1, 16)
                 if sum(1 for k in range(4)
                        if BL_VERTS[i][k] != BL_VERTS[j][k]) == 1)


def bl_tesseract(surf, cx, cy, size, spin, col, alpha=255, width=3):
    """A four-dimensional cube, turned in two planes at once and flattened
    twice to get here. The inner cube swelling through the outer one is the
    fourth axis passing through our three.

    All 32 edges at one weight came out as a scribble, so the two cubes are
    drawn solid and the eight struts between them are dropped back - that is
    what makes the shape legible as a box inside a box."""
    ca, sa = math.cos(spin), math.sin(spin)
    cb, sb = math.cos(spin * 0.63), math.sin(spin * 0.63)
    pts = []
    for (x, y, z, w) in BL_VERTS:
        x, w = x * ca - w * sa, x * sa + w * ca        # turn through XW
        y, z = y * cb - z * sb, y * sb + z * cb        # and through YZ
        k4 = 2.6 / (3.3 - w)                           # 4D -> 3D
        x, y, z = x * k4, y * k4, z * k4
        k3 = 3.0 / (3.9 - z)                           # 3D -> 2D
        pts.append((cx + x * k3 * size, cy + y * k3 * size))
    lay = pygame.Surface(surf.get_size(), pygame.SRCALPHA)
    for r, a in ((size * 1.9, 0.10), (size * 1.2, 0.16)):   # it carries light
        pygame.draw.circle(lay, col + (int(alpha * a),),
                           (int(cx), int(cy)), int(r))
    for i, j in BL_EDGES:
        strut = BL_VERTS[i][3] != BL_VERTS[j][3]
        pygame.draw.line(lay, col + (int(alpha * (0.34 if strut else 1.0)),),
                         pts[i], pts[j], max(1, width - 1 if strut else width))
    for p in pts:
        pygame.draw.circle(lay, (226, 244, 255, alpha),
                           (int(p[0]), int(p[1])), width)
    surf.blit(lay, (0, 0))


def bl_winged(surf, cx, cy, sc, spread, eye):
    """The figure in front of the sun. It is drawn as a hole in the light -
    flat black, no detail - because at this distance that is all it is.

    The wing is one closed outline: a leading edge that sweeps up and out,
    and a trailing edge set a tapering chord below it, scalloped between the
    feather tips. Straight polygons with strut lines drawn over them read as
    a moth, and a trailing edge notched at a fixed depth reads as teeth - the
    notch has to come off the chord, so it closes up as the wing narrows."""
    K = (5, 6, 12)
    span = 260 * sc * spread
    hy = cy - 96 * sc                                  # the head
    N = 7

    def lead(q):
        return cy - (60 + 132 * q ** 0.7) * sc * spread

    def chord(q):
        return (152 * (1 - q) ** 0.5 + 28) * sc * spread

    for sgn in (-1, 1):
        pts = [(cx + sgn * span * (i / float(N)), lead(i / float(N)))
               for i in range(N + 1)]
        for i in range(N, -1, -1):                     # back along the quills
            q = i / float(N)
            pts.append((cx + sgn * span * q, lead(q) + chord(q)))
            if i:                                      # scalloped between
                m = (i - 0.5) / N
                pts.append((cx + sgn * span * m,
                            lead(m) + chord(m) * 0.70))
        pygame.draw.polygon(surf, K, pts)
    pygame.draw.polygon(surf, K, [                     # the body
        (cx - 22 * sc, cy - 76 * sc), (cx + 22 * sc, cy - 76 * sc),
        (cx + 30 * sc, cy + 34 * sc), (cx + 14 * sc, cy + 112 * sc),
        (cx - 14 * sc, cy + 112 * sc), (cx - 30 * sc, cy + 34 * sc)])
    pygame.draw.circle(surf, K, (int(cx), int(hy)), int(34 * sc))
    if eye > 0:                                        # and the eye
        er = 21 * sc
        gl = pygame.Surface((int(er * 20), int(er * 20)), pygame.SRCALPHA)
        m = gl.get_width() // 2
        for r, al in ((er * 8, 20), (er * 4.4, 40), (er * 2.2, 84)):
            pygame.draw.circle(gl, (90, 170, 255, int(al * eye)), (m, m),
                               int(r))
        surf.blit(gl, (cx - m, hy - m))
        pygame.draw.ellipse(surf, (168, 222, 255),
                            (cx - er * 1.45, hy - er * 0.62 * eye,
                             er * 2.9, er * 1.24 * eye))
        pygame.draw.ellipse(surf, (30, 96, 190),
                            (cx - er * 0.72, hy - er * 0.50 * eye,
                             er * 1.44, er * 1.00 * eye))
        pygame.draw.ellipse(surf, (6, 12, 30),
                            (cx - er * 0.24, hy - er * 0.46 * eye,
                             er * 0.48, er * 0.92 * eye))


# ----------------------------------------------------------------------------
# OPERATION KITTEN's two scenes.
#
# THE BREAK plays the moment the Calico dies on the twenty-fifth wave. It
# opens on a victory card, because as far as the sector is concerned the
# operation is over, and then something comes through the card.
#
# THE PAINT plays at the hundredth, and it is the Calico again, at the size
# it has got to by then.
# ----------------------------------------------------------------------------
KB_CARD_AT = 0.6            # a perfectly ordinary victory screen
KB_CRACK_AT = 4.2           # with a crack in it
KB_SPREAD_AT = 5.4
KB_HAND_AT = 7.6            # and something coming through it
KB_GRAB_AT = 10.4
KB_FLOOD_AT = 12.6
KB_BLACK_AT = 15.0
KB_END = 16.6

KP_FACE_AT = 0.5            # it is looking at you
KP_WRONG_AT = 3.4           # and it has stopped pretending
KP_LINE_AT = 5.6            # "I'LL PAINT THE WORLD RED."
KP_CUT_AT = 9.2             # and then what it is going to do it with
KP_BLACK_AT = 14.2
KP_END = 15.8


def kb_meat(surf, cx, cy, r, t, seed=0, tone=(150, 34, 42)):
    """A lump of it. Drawn as a wobbling blob with a rim, because a smooth
    circle reads as a ball and this is not meant to."""
    rnd = random.Random(seed)
    pts = []
    for i in range(14):
        ang = i / 14.0 * 6.2832
        rr = r * (0.78 + 0.30 * rnd.random())
        rr *= 1.0 + 0.10 * math.sin(t * 2.2 + i * 1.3)
        pts.append((cx + math.cos(ang) * rr, cy + math.sin(ang) * rr * 0.92))
    pygame.draw.polygon(surf, tone, pts)
    pygame.draw.polygon(surf, shade(tone, 0.62), pts, max(1, int(r * 0.07)))
    for i in range(4):                                   # things in it
        a2 = rnd.uniform(0, 6.283)
        d = rnd.uniform(0, r * 0.55)
        p = (cx + math.cos(a2) * d, cy + math.sin(a2) * d)
        pygame.draw.circle(surf, shade(tone, 1.35), p, max(1, int(r * 0.13)))


def kb_hand(surf, cx, cy, s, reach, t):
    """A hand, if you are generous about the word: five of something coming
    through, with a coat still on parts of it."""
    ARM = (156, 40, 48)
    FUR = (216, 150, 96)
    pygame.draw.line(surf, ARM, (cx, cy + 260 * s),
                     (cx, cy - 40 * s * reach), int(74 * s))
    kb_meat(surf, cx, cy - 30 * s * reach, 78 * s, t, 3, ARM)
    for i in range(5):
        q = (i - 2) / 2.0
        ang = -1.5708 + q * 0.78
        ln = (150 + 60 * abs(q)) * s * reach
        tipx = cx + math.cos(ang) * ln
        tipy = cy - 30 * s * reach + math.sin(ang) * ln
        midx = cx + math.cos(ang) * ln * 0.55
        midy = cy - 30 * s * reach + math.sin(ang) * ln * 0.55 \
            + math.sin(t * 2 + i) * 8 * s
        pygame.draw.lines(surf, ARM, False,
                          [(cx, cy - 30 * s * reach), (midx, midy),
                           (tipx, tipy)], int((26 - abs(q) * 5) * s))
        pygame.draw.circle(surf, FUR, (int(midx), int(midy)),
                           max(1, int(13 * s)))
        pygame.draw.polygon(surf, (240, 236, 224), [        # a claw
            (tipx, tipy),
            (tipx + math.cos(ang - 0.4) * 30 * s,
             tipy + math.sin(ang - 0.4) * 30 * s),
            (tipx + math.cos(ang + 0.5) * 12 * s,
             tipy + math.sin(ang + 0.5) * 12 * s)])
    for i in range(6):                                   # calico, still
        rnd = random.Random(90 + i)
        px = cx + rnd.uniform(-70, 70) * s
        py = cy - rnd.uniform(0, 210) * s * reach
        pygame.draw.circle(surf, FUR, (int(px), int(py)),
                           max(1, int(rnd.uniform(8, 20) * s)))


def kb_shards(surf, t, spread, rnd_seed=5):
    """The frame coming apart. The cracks are fixed, the gaps between them
    are not."""
    rnd = random.Random(rnd_seed)
    for i in range(22):
        x0 = rnd.uniform(0, WIN_W)
        y0 = rnd.uniform(0, WIN_H)
        ang = rnd.uniform(0, 6.283)
        ln = rnd.uniform(60, 420) * spread
        pygame.draw.line(surf, (16, 8, 10),
                         (x0, y0),
                         (x0 + math.cos(ang) * ln, y0 + math.sin(ang) * ln),
                         max(1, int(2 + 5 * spread)))
        pygame.draw.line(surf, (232, 226, 220),
                         (x0 + 1, y0 - 1),
                         (x0 + math.cos(ang) * ln + 1,
                          y0 + math.sin(ang) * ln - 1),
                         max(1, int(1 + 2 * spread)))


class KittenBreakCutscene:
    """What happens to the victory screen. Skippable, plays once."""

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()

    def skip(self):
        if self.t < KB_HAND_AT - 0.4:
            self.t = KB_HAND_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for at, snd in ((KB_CRACK_AT, "deny"), (KB_HAND_AT, "boom"),
                        (KB_GRAB_AT, "leak"), (KB_FLOOD_AT, "boom"),
                        (KB_BLACK_AT, "leak")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= KB_END:
            self.done = True

    def draw(self, sc):
        t = self.t
        if t >= KB_BLACK_AT:
            sc.fill((0, 0, 0))
            FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                       (52, 20, 24), "right")
            return
        flood = clamp((t - KB_FLOOD_AT) / 1.4, 0, 1)
        # the victory card, which is entirely sincere
        sc.fill((36, 58, 44))
        for i in range(0, WIN_H, 6):
            pygame.draw.line(sc, (44, 70, 52), (0, i), (WIN_W, i))
        cx = WIN_W // 2
        for sgn in (-1, 1):
            pygame.draw.line(sc, (140, 226, 150),
                             (cx + sgn * 120, 176), (cx + sgn * 320, 176), 3)
        FONTS.draw(sc, "OPERATION COMPLETE", (cx, 190), 52, (168, 240, 176),
                   "center")
        FONTS.draw(sc, "THE CALICO HAS BEEN RECOVERED", (cx, 262), 22,
                   (222, 244, 226), "center")
        FONTS.draw(sc, "25 WAVES HELD    NO CASUALTIES    GOOD WORK",
                   (cx, 300), 15, (176, 208, 182), "center")
        draw_calico(sc, cx, 560, 3.2, t, blink=t < KB_CRACK_AT)
        if t >= KB_CRACK_AT:
            spread = clamp((t - KB_CRACK_AT) / (KB_SPREAD_AT - KB_CRACK_AT),
                           0, 1)
            kb_shards(sc, t, spread)
        if t >= KB_HAND_AT:
            reach = clamp((t - KB_HAND_AT) / 2.2, 0, 1)
            grab = clamp((t - KB_GRAB_AT) / 1.8, 0, 1)
            sh = int(math.sin(t * 26) * 9 * grab)
            kb_hand(sc, cx + sh, WIN_H + 40, 1.5 + grab * 0.6, reach, t)
            for i in range(int(14 * grab)):
                kb_meat(sc, (i * 173) % WIN_W, (i * 271) % WIN_H,
                        20 + 44 * grab, t, 40 + i)
        if flood > 0:
            lay = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
            lay.fill((132, 12, 18, int(255 * flood)))
            sc.blit(lay, (0, 0))
        FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                   (150, 140, 138), "right")


# ---------------------------------------------------------------------------
# THE LAUNCH. Where the Cat Prince came from - and it is not a story about
# a prince. It is a story about two people who could see what was coming,
# who had one ship and one seat, and who put the baby in it and then went
# and got their armour.
# ---------------------------------------------------------------------------
LA_ROOM_AT = 1.0
LA_LIFT_AT = 6.4        # the ship goes
LA_GEAR_AT = 11.0       # ...and they turn round and put the plate on
LA_STAND_AT = 16.0      # and they are standing in the doorway
LA_END = 22.0


class LaunchCutscene:
    """A yellow kitten, a ship, and two people not getting in it."""

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()

    def skip(self):
        if self.t < LA_GEAR_AT - 0.4:
            self.t = LA_GEAR_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for at, snd in ((LA_LIFT_AT, "boom"), (LA_GEAR_AT, "build"),
                        (LA_STAND_AT, "upgrade")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= LA_END:
            self.done = True

    def _room(self, sc, t):
        lit = 1.0 - clamp((t - LA_LIFT_AT) / 3.0, 0.0, 0.55)
        sc.fill((int(20 * lit) + 10, int(16 * lit) + 8, int(28 * lit) + 12))
        # a window, and something wrong outside it
        w = pygame.Rect(WIN_W - 470, 90, 330, 250)
        pygame.draw.rect(sc, (46, 30, 60), w)
        for i in range(60):
            sx = w.x + (i * 137) % w.w
            sy = w.y + (i * 89) % w.h
            pygame.draw.circle(sc, (206, 196, 226), (sx, sy),
                               1 + (i % 3 == 0))
        # the thing on the horizon that they can already see
        gl = 0.5 + 0.5 * math.sin(t * 0.9)
        pygame.draw.rect(sc, (70, 56, 40), (w.x, w.bottom - 60, w.w, 60))
        for sgn in (-1, 1):
            pygame.draw.polygon(sc, (30, 26, 34),
                                [(w.centerx + sgn * 30, w.bottom),
                                 (w.centerx + sgn * 46, w.bottom - 130),
                                 (w.centerx + sgn * 18, w.bottom - 130)])
        pygame.draw.circle(sc, (int(200 + 40 * gl), int(170 + 40 * gl), 96),
                           (w.centerx, w.bottom - 140), 9)
        pygame.draw.rect(sc, (96, 84, 110), w, 4)
        pygame.draw.rect(sc, (30, 24, 36), (0, WIN_H - 190, WIN_W, 190))

    def _ship(self, sc, t):
        f = clamp((t - LA_ROOM_AT) / (LA_LIFT_AT - LA_ROOM_AT), 0.0, 1.0)
        up = clamp((t - LA_LIFT_AT) / 3.6, 0.0, 1.0)
        x = 330
        y = WIN_H - 250 - up * (WIN_H + 120)
        if up >= 1.0:
            return
        # a small ship with one seat in it
        pygame.draw.polygon(sc, (226, 216, 200),
                            [(x, y - 96), (x + 44, y + 20),
                             (x + 30, y + 62), (x - 30, y + 62),
                             (x - 44, y + 20)])
        pygame.draw.polygon(sc, (170, 156, 140),
                            [(x, y - 96), (x + 44, y + 20),
                             (x + 30, y + 62), (x - 30, y + 62),
                             (x - 44, y + 20)], 3)
        pygame.draw.circle(sc, (120, 200, 236), (x, y - 22), 24)
        pygame.draw.circle(sc, (206, 240, 255), (x, y - 22), 24, 3)
        # ...and the kitten in it, yellow, asleep, and much too small
        if f > 0.05:
            pygame.draw.circle(sc, (250, 214, 118), (x, y - 20), 13)
            for sgn in (-1, 1):
                pygame.draw.polygon(sc, (250, 214, 118),
                                    [(x + sgn * 5, y - 30),
                                     (x + sgn * 13, y - 42),
                                     (x + sgn * 12, y - 27)])
            pygame.draw.line(sc, (60, 48, 30), (x - 6, y - 20),
                             (x - 2, y - 20), 2)
            pygame.draw.line(sc, (60, 48, 30), (x + 2, y - 20),
                             (x + 6, y - 20), 2)
        if up > 0.02:
            for _ in range(6):
                pygame.draw.circle(
                    sc, (255, 218, 150),
                    (int(x + random.uniform(-26, 26)),
                     int(y + 62 + random.uniform(0, 60))),
                    random.randint(3, 9))

    def _parents(self, sc, t):
        if t < LA_ROOM_AT:
            return
        gear = clamp((t - LA_GEAR_AT) / 3.0, 0.0, 1.0)
        stand = clamp((t - LA_STAND_AT) / 2.4, 0.0, 1.0)
        for i, sgn in enumerate((-1, 1)):
            bx = WIN_W * 0.5 + sgn * 110 + stand * sgn * 40
            by = WIN_H - 210
            coat = (236, 176, 92) if i == 0 else (226, 226, 232)
            plate = (int(lerp(coat[0], 176, gear)),
                     int(lerp(coat[1], 150, gear)),
                     int(lerp(coat[2], 120, gear)))
            pygame.draw.rect(sc, plate, (bx - 26, by - 62, 52, 78),
                             border_radius=10)
            pygame.draw.circle(sc, coat, (int(bx), int(by - 78)), 22)
            for s2 in (-1, 1):
                pygame.draw.polygon(sc, coat,
                                    [(bx + s2 * 8, by - 94),
                                     (bx + s2 * 21, by - 116),
                                     (bx + s2 * 19, by - 90)])
            for s2 in (-1, 1):
                pygame.draw.circle(sc, (26, 26, 30),
                                   (int(bx + s2 * 8), int(by - 78)), 3)
            if gear > 0.2:      # the plate goes on
                pygame.draw.rect(sc, (250, 206, 96),
                                 (bx - 30, by - 66, 60, 16),
                                 border_radius=5)
                pygame.draw.circle(sc, (250, 206, 96),
                                   (int(bx), int(bx * 0 + by - 78)), 24, 3)
            if stand > 0.4:     # ...and they pick something up
                pygame.draw.line(sc, (206, 196, 176),
                                 (bx + sgn * 30, by - 70),
                                 (bx + sgn * 30, by + 18), 7)

    def draw(self, sc):
        t = self.t
        self._room(sc, t)
        self._ship(sc, t)
        self._parents(sc, t)
        lines = [(LA_ROOM_AT, "There was one ship and one seat in it."),
                 (LA_LIFT_AT, "So they used it."),
                 (LA_GEAR_AT, "And then they went and got their armour."),
                 (LA_STAND_AT, "Nobody on that planet ran."),
                 (19.4, "It is a very long way from here.")]
        say = None
        for at, txt in lines:
            if t >= at:
                say = (at, txt)
        if say:
            a = clamp((t - say[0]) / 0.7, 0.0, 1.0)
            FONTS.draw(sc, say[1], (WIN_W // 2, WIN_H - 86), 23,
                       (int(236 * a), int(226 * a), int(198 * a)), "center")
        if t > 1.2:
            FONTS.draw(sc, "SPACE to skip", (WIN_W // 2, WIN_H - 40), 13,
                       (110, 106, 100), "center")


# ---------------------------------------------------------------------------
# THE ESCAPE. You did not win. You got everybody out while two things that
# are not you argued about the planet.
# ---------------------------------------------------------------------------
ES_LIFT_AT = 1.4
ES_LOOK_AT = 6.0
ES_FAR_AT = 12.0
ES_END = 19.0


class EscapeCutscene:
    """Going home, with the sky still going off behind you."""

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()

    def skip(self):
        if self.t < ES_FAR_AT - 0.4:
            self.t = ES_FAR_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for at, snd in ((ES_LIFT_AT, "wave"), (ES_LOOK_AT, "boom")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= ES_END:
            self.done = True

    def draw(self, sc):
        t = self.t
        far = clamp((t - ES_FAR_AT) / 5.0, 0.0, 1.0)
        sc.fill((int(8 + 6 * far), int(8 + 4 * far), int(18 + 10 * far)))
        rnd = random.Random(88)
        for _ in range(190):
            sx = rnd.randrange(0, WIN_W)
            sy = rnd.randrange(0, WIN_H)
            pygame.draw.circle(sc, (206, 206, 226), (sx, sy),
                               1 + (rnd.random() < 0.12))
        # the planet you are leaving, shrinking
        R = int(340 * (1.0 - far * 0.82))
        px, py = WIN_W * 0.32, WIN_H * 0.86 + far * 90
        pygame.draw.circle(sc, (86, 68, 92), (int(px), int(py)), R)
        pygame.draw.circle(sc, (120, 96, 126), (int(px), int(py)), R, 3)
        # ...and the two of them still at it on the surface
        if t > ES_LOOK_AT:
            gl = 0.5 + 0.5 * math.sin(t * 3.0)
            fx, fy = px + R * 0.34, py - R * 0.74
            pygame.draw.circle(sc, (255, 236, 176), (int(fx), int(fy)),
                               int((10 + 8 * gl) * (1.0 - far * 0.7)))
            pygame.draw.circle(sc, (60, 236, 220),
                               (int(fx + 26 * (1 - far)), int(fy + 8)),
                               int((7 + 5 * gl) * (1.0 - far * 0.7)))
            for k in range(3):
                a2 = t * 1.4 + k * 2.1
                pygame.draw.line(
                    sc, (206, 255, 250),
                    (fx, fy),
                    (fx + math.cos(a2) * 40 * (1 - far),
                     fy + math.sin(a2) * 40 * (1 - far)), 2)
        # the ship, going the other way
        lift = clamp((t - ES_LIFT_AT) / 3.0, 0.0, 1.0)
        sx = WIN_W * 0.62 + lift * 130
        sy = WIN_H * 0.58 - lift * 150
        pygame.draw.polygon(sc, (222, 216, 202),
                            [(sx + 62, sy), (sx - 30, sy - 26),
                             (sx - 48, sy), (sx - 30, sy + 26)])
        pygame.draw.polygon(sc, (150, 142, 132),
                            [(sx + 62, sy), (sx - 30, sy - 26),
                             (sx - 48, sy), (sx - 30, sy + 26)], 3)
        for j in range(4):
            pygame.draw.circle(sc, (140, 206, 240),
                               (int(sx - 16 + j * 16), int(sy - 2)), 4)
        for _ in range(5):
            pygame.draw.circle(
                sc, (255, 214, 150),
                (int(sx - 52 - random.uniform(0, 70)),
                 int(sy + random.uniform(-9, 9))),
                random.randint(2, 6))
        lines = [(ES_LIFT_AT, "Everybody is aboard."),
                 (ES_LOOK_AT, "Behind you, the two of them are still at it."),
                 (ES_FAR_AT, "Neither one was ever fighting for you."),
                 (16.0, "You just needed them busy.")]
        say = None
        for at, txt in lines:
            if t >= at:
                say = (at, txt)
        if say:
            a = clamp((t - say[0]) / 0.7, 0.0, 1.0)
            FONTS.draw(sc, say[1], (WIN_W // 2, WIN_H - 84), 23,
                       (int(226 * a), int(232 * a), int(240 * a)), "center")
        if t > 1.2:
            FONTS.draw(sc, "SPACE to skip", (WIN_W // 2, WIN_H - 40), 13,
                       (108, 112, 120), "center")


LH_WALK_AT = 1.2        # the cat starts up the headland
LH_TOP_AT = 7.0         # ...and the fih is put down at the door
LH_LIGHT_AT = 9.6       # the lamp turns over
LH_TURN_AT = 12.0       # and what is standing there stops being a fih
LH_BACK_AT = 18.5       # the cat goes home. It goes home alone.
LH_END = 24.0


class LighthouseCutscene:
    """What a fih becomes if somebody walks it far enough."""

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()

    def skip(self):
        if self.t < LH_TURN_AT - 0.4:
            self.t = LH_TURN_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for at, snd in ((LH_TOP_AT, "build"), (LH_LIGHT_AT, "upgrade"),
                        (LH_TURN_AT, "boom"), (LH_BACK_AT, "wave")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= LH_END:
            self.done = True

    # -- the pieces -------------------------------------------------------
    def _sky(self, sc, t):
        lit = clamp((t - LH_LIGHT_AT) / 2.0, 0.0, 1.0)
        top = (int(10 + 8 * lit), int(14 + 12 * lit), int(30 + 18 * lit))
        bot = (int(26 + 26 * lit), int(30 + 30 * lit), int(46 + 26 * lit))
        for i in range(0, WIN_H, 4):
            f = i / float(WIN_H)
            pygame.draw.rect(sc, (lerp(top[0], bot[0], f),
                                  lerp(top[1], bot[1], f),
                                  lerp(top[2], bot[2], f)),
                             (0, i, WIN_W, 4))
        # the sea, and the headland it stands on
        sea = WIN_H - 150
        pygame.draw.rect(sc, (14, 26, 40), (0, sea, WIN_W, WIN_H - sea))
        for i in range(46):
            yy = sea + 6 + (i * 7) % (WIN_H - sea - 10)
            w = 40 + (i * 37) % 180
            xx = (i * 211 + int(t * 14)) % (WIN_W + 200) - 100
            pygame.draw.line(sc, (26, 44 + int(18 * lit), 62),
                             (xx, yy), (xx + w, yy), 2)
        pygame.draw.polygon(sc, (16, 20, 22),
                            [(WIN_W - 520, WIN_H), (WIN_W - 430, sea - 40),
                             (WIN_W - 250, sea - 96),
                             (WIN_W - 60, sea - 30), (WIN_W, WIN_H)])

    def _tower(self, sc, t):
        bx, by = WIN_W - 250, WIN_H - 246
        pygame.draw.polygon(sc, (206, 202, 194),
                            [(bx - 34, by), (bx + 34, by),
                             (bx + 22, by - 210), (bx - 22, by - 210)])
        for i in range(4):           # the bands
            yy = by - 26 - i * 48
            pygame.draw.polygon(sc, (176, 62, 58),
                                [(bx - 33 + i * 2, yy),
                                 (bx + 33 - i * 2, yy),
                                 (bx + 31 - i * 2, yy - 20),
                                 (bx - 31 + i * 2, yy - 20)])
        pygame.draw.rect(sc, (40, 46, 50), (bx - 28, by - 242, 56, 34))
        lit = clamp((t - LH_LIGHT_AT) / 1.4, 0.0, 1.0)
        if lit > 0.01:
            spin = (t - LH_LIGHT_AT) * 1.5
            for k in (0, 1):
                a = spin + k * 3.1416
                beam = pygame.Surface((WIN_W * 2, WIN_H * 2),
                                      pygame.SRCALPHA)
                pygame.draw.polygon(
                    beam, (255, 250, 214, int(52 * lit)),
                    [(WIN_W, WIN_H),
                     (WIN_W + math.cos(a - 0.10) * 1700,
                      WIN_H + math.sin(a - 0.10) * 1700),
                     (WIN_W + math.cos(a + 0.10) * 1700,
                      WIN_H + math.sin(a + 0.10) * 1700)])
                sc.blit(beam, (bx - WIN_W, by - 225 - WIN_H))
            pygame.draw.circle(sc, (255, 252, 226), (bx, by - 225),
                               int(13 * lit))
        pygame.draw.polygon(sc, (36, 42, 46),
                            [(bx - 34, by - 242), (bx + 34, by - 242),
                             (bx, by - 268)])

    def _cat(self, sc, t):
        """A very long cat, a very long way off. It never gets any closer
        to the lens - the whole point is that this is happening to the
        fish and it is happening far away from you."""
        f = clamp((t - LH_WALK_AT) / (LH_TOP_AT - LH_WALK_AT), 0.0, 1.0)
        if t > LH_BACK_AT:
            f = 1.0 - clamp((t - LH_BACK_AT) / 4.2, 0.0, 1.0)
        x = lerp(150, WIN_W - 330, f)
        y = lerp(WIN_H - 176, WIN_H - 252, f)
        L = 168
        col = (226, 222, 210)
        pygame.draw.rect(sc, col, (x - L // 2, y - 9, L, 18),
                         border_radius=9)
        pygame.draw.rect(sc, (168, 164, 156), (x - L // 2, y + 3, L, 6),
                         border_radius=3)
        for i in range(4):           # legs
            lx = x - L // 2 + 16 + i * (L - 32) // 3
            sw = math.sin(t * 5.0 + i) * 4 * (0 if f in (0.0, 1.0) else 1)
            pygame.draw.line(sc, col, (lx, y + 8), (lx + sw, y + 26), 5)
        hx = x + L // 2
        pygame.draw.circle(sc, col, (int(hx), int(y - 4)), 15)
        for sgn in (-1, 1):
            pygame.draw.polygon(sc, col,
                                [(hx - 4 + sgn * 9, y - 15),
                                 (hx - 1 + sgn * 13, y - 30),
                                 (hx + 4 + sgn * 5, y - 16)])
        pygame.draw.line(sc, col, (x - L // 2, y - 2),
                         (x - L // 2 - 26, y - 20), 5)
        return x, y

    def _fih(self, sc, t, x, y):
        """The fih, walked up on a lead. Small, ordinary, a fish."""
        pygame.draw.line(sc, (150, 146, 138), (x + 70, y - 6),
                         (x + 118, y + 14), 2)
        fx, fy = x + 124, y + 16
        pygame.draw.polygon(sc, (150, 226, 255),
                            [(fx + 17, fy), (fx + 2, fy - 11),
                             (fx - 15, fy - 4), (fx - 15, fy + 4),
                             (fx + 2, fy + 11)])
        pygame.draw.polygon(sc, (104, 178, 210),
                            [(fx - 15, fy), (fx - 26, fy - 9),
                             (fx - 26, fy + 9)])
        pygame.draw.circle(sc, (250, 252, 250), (fx + 8, fy - 3), 3)
        pygame.draw.circle(sc, (18, 26, 30), (fx + 8, fy - 3), 1)

    def _become(self, sc, t):
        """And what is standing at the door afterwards. Almost nothing
        about it says fih any more. It is still a fish, and that is the
        only part of it that is."""
        g = clamp((t - LH_TURN_AT) / 3.4, 0.0, 1.0)
        if g <= 0.01:
            return
        cx, cy = WIN_W - 470, WIN_H - 330
        S = 26 + 104 * g
        pulse = 0.5 + 0.5 * math.sin(t * 2.4)
        halo = pygame.Surface((int(S * 5), int(S * 5)), pygame.SRCALPHA)
        pygame.draw.circle(halo, (150, 240, 255, int(30 + 26 * pulse)),
                           (int(S * 2.5), int(S * 2.5)), int(S * 2.2))
        sc.blit(halo, (cx - S * 2.5, cy - S * 2.5))
        # a plated hull rather than a body: segments, not scales
        for i in range(6):
            q = i / 5.0
            w = S * (1.15 - 0.16 * i)
            h = S * (0.62 - 0.07 * i)
            ox = cx - S * 0.9 + q * S * 1.9
            pygame.draw.ellipse(sc, (int(28 + 40 * q), int(74 + 60 * q),
                                     int(96 + 70 * q)),
                                (ox - w / 2, cy - h / 2, w, h))
            pygame.draw.ellipse(sc, (150, 226, 255),
                                (ox - w / 2, cy - h / 2, w, h), 2)
        # the tail is a fan of blades
        for k in range(5):
            a = -0.62 + k * 0.31
            pygame.draw.polygon(sc, (96, 186, 226),
                                [(cx - S * 1.0, cy),
                                 (cx - S * 1.0 - math.cos(a) * S * 0.72,
                                  cy - math.sin(a) * S * 0.72),
                                 (cx - S * 0.86 - math.cos(a) * S * 0.44,
                                  cy - math.sin(a) * S * 0.44)])
        # ...and the lamp. It is not carrying one any more. It IS one.
        for r, al in ((S * 1.1, 40), (S * 0.7, 70), (S * 0.36, 150)):
            gl = pygame.Surface((int(r * 2), int(r * 2)), pygame.SRCALPHA)
            pygame.draw.circle(gl, (255, 252, 226, al), (int(r), int(r)),
                               int(r))
            sc.blit(gl, (cx + S * 0.55 - r, cy - S * 0.1 - r))
        pygame.draw.circle(sc, (255, 255, 244),
                           (int(cx + S * 0.55), int(cy - S * 0.1)),
                           max(3, int(S * 0.20 * (0.85 + 0.15 * pulse))))
        # no eye anywhere on it, and that is the point
        for sgn in (-1, 1):
            pygame.draw.line(sc, (206, 246, 255),
                             (cx - S * 0.2, cy + sgn * S * 0.30),
                             (cx + S * 0.9, cy + sgn * S * 0.10),
                             max(1, int(S * 0.05)))

    def draw(self, sc):
        t = self.t
        self._sky(sc, t)
        self._tower(sc, t)
        if t < LH_TURN_AT + 0.4:
            x, y = self._cat(sc, t)
            if t < LH_TOP_AT:
                self._fih(sc, t, x, y)
            elif t < LH_TURN_AT:
                self._fih(sc, t, WIN_W - 372, WIN_H - 262)
        else:
            self._cat(sc, t)
        self._become(sc, t)
        lines = [(LH_WALK_AT, "He walks it up the headland every evening."),
                 (LH_TOP_AT, "He puts it down at the door and he waits."),
                 (LH_LIGHT_AT, "The lamp turns over."),
                 (LH_TURN_AT, "It is still a fish."),
                 (16.4, "Nothing else about it is."),
                 (LH_BACK_AT, "He goes home. He goes home on his own.")]
        say = None
        for at, txt in lines:
            if t >= at:
                say = (at, txt)
        if say:
            a = clamp((t - say[0]) / 0.7, 0.0, 1.0)
            col = (int(226 * a), int(232 * a), int(226 * a))
            FONTS.draw(sc, say[1], (WIN_W // 2, WIN_H - 78), 22, col,
                       "center")
        if t > 1.4:
            FONTS.draw(sc, "SPACE to skip", (WIN_W // 2, WIN_H - 34), 13,
                       (110, 118, 116), "center")


class KittenPaintCutscene:
    """The hundredth wave. Skippable, plays once."""

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()

    def skip(self):
        if self.t < KP_CUT_AT - 0.4:
            self.t = KP_CUT_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for at, snd in ((KP_WRONG_AT, "deny"), (KP_LINE_AT, "leak"),
                        (KP_CUT_AT, "boom"), (KP_BLACK_AT, "leak")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= KP_END:
            self.done = True

    def _face(self, sc, t):
        """The Calico, filling the frame, looking straight down the lens."""
        wrong = clamp((t - KP_WRONG_AT) / 3.0, 0, 1)
        cx, cy = WIN_W // 2, 340
        sc.fill((int(22 + 40 * wrong), 10, 12))
        gl = pygame.Surface((900, 900), pygame.SRCALPHA)
        for r, al in ((420, 20), (280, 26), (160, 40)):
            pygame.draw.circle(gl, (150, 26, 32, al), (450, 450), r)
        sc.blit(gl, (cx - 450, cy - 450))
        GING = (int(232 - 70 * wrong), int(160 - 90 * wrong),
                int(94 - 50 * wrong))
        pygame.draw.ellipse(sc, GING, (cx - 300, cy - 250, 600, 520))
        for sgn in (-1, 1):                              # ears
            pygame.draw.polygon(sc, GING, [
                (cx + sgn * 110, cy - 210),
                (cx + sgn * (250 + 40 * wrong), cy - 430 - 60 * wrong),
                (cx + sgn * 268, cy - 150)])
        for (px, py, pr, pc) in ((-140, -60, 96, (52, 42, 40)),
                                 (156, 40, 78, (248, 244, 236)),
                                 (60, -140, 60, (52, 42, 40))):
            pygame.draw.circle(sc, (lerp(pc[0], 128, wrong),
                                    lerp(pc[1], 20, wrong),
                                    lerp(pc[2], 26, wrong)),
                               (cx + px, cy + py), pr)
        # the eyes. They stay green the whole way, which is the worst part.
        for sgn in (-1, 1):
            ex, ey = cx + sgn * 120, cy - 40
            pygame.draw.circle(sc, (126, 214, 118), (ex, ey), 62)
            pygame.draw.circle(sc, (22, 44, 24), (ex, ey), 62, 5)
            pygame.draw.ellipse(sc, (14, 24, 16),
                                (ex - 13, ey - 56 + 20 * wrong,
                                 26, 112 - 40 * wrong))
        for i in range(int(7 * wrong)):                  # and then there are more
            ang = i * 1.7
            ex = int(cx + math.cos(ang) * (220 + i * 12))
            ey = int(cy + math.sin(ang) * (170 + i * 9))
            pygame.draw.circle(sc, (126, 214, 118), (ex, ey), 22)
            pygame.draw.ellipse(sc, (14, 24, 16), (ex - 5, ey - 18, 10, 36))
        pygame.draw.polygon(sc, (232, 150, 168),         # nose
                            [(cx - 26, cy + 96), (cx + 26, cy + 96),
                             (cx, cy + 126)])
        if wrong > 0.4:                                  # a mouth, eventually
            m = (wrong - 0.4) / 0.6
            pygame.draw.ellipse(sc, (40, 8, 12),
                                (cx - 150 * m, cy + 130, 300 * m, 120 * m))
            for i in range(9):
                q = i / 8.0
                tx = cx - 150 * m + 300 * m * q
                pygame.draw.polygon(sc, (244, 238, 228), [
                    (tx - 10 * m, cy + 132), (tx + 10 * m, cy + 132),
                    (tx, cy + 132 + 46 * m)])
        if t >= KP_LINE_AT:
            a = clamp((t - KP_LINE_AT) / 0.8, 0, 1)
            img = FONTS.render("I'LL PAINT THE WORLD RED.", 40,
                               (196, 16, 24)).copy()
            img.set_alpha(int(255 * a))
            sc.blit(img, img.get_rect(center=(WIN_W // 2, 690)))

    def _mass(self, sc, t):
        """What it is going to do it with."""
        rise = clamp((t - KP_CUT_AT) / 3.6, 0, 1)
        sc.fill((26, 8, 10))
        for y in range(0, WIN_H, 4):
            q = y / float(WIN_H)
            pygame.draw.line(sc, (int(40 + 60 * q), int(8 + 10 * q),
                                  int(12 + 12 * q)), (0, y), (WIN_W, y), 4)
        base = WIN_H + 260 - int(520 * rise)
        rnd = random.Random(19)
        for i in range(60):
            px = rnd.uniform(-60, WIN_W + 60)
            py = base + rnd.uniform(-40, 420)
            kb_meat(sc, px, py, rnd.uniform(40, 130) * (0.6 + rise), t,
                    200 + i, (int(120 + rnd.uniform(0, 60)), 26, 34))
        for i in range(int(20 * rise)):                  # eyes in it
            rnd2 = random.Random(300 + i)
            ex = int(rnd2.uniform(60, WIN_W - 60))
            ey = int(base + rnd2.uniform(-10, 300))
            pygame.draw.circle(sc, (126, 214, 118), (ex, ey), 16)
            pygame.draw.ellipse(sc, (14, 24, 16), (ex - 4, ey - 13, 8, 26))
        if t >= KP_CUT_AT + 2.4:
            a = clamp((t - KP_CUT_AT - 2.4) / 1.0, 0, 1)
            img = FONTS.render("A GREAT WRITHING MASS", 34,
                               (238, 214, 210)).copy()
            img.set_alpha(int(255 * a))
            sc.blit(img, img.get_rect(center=(WIN_W // 2, 92)))

    def draw(self, sc):
        t = self.t
        if t >= KP_BLACK_AT:
            sc.fill((0, 0, 0))
            FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                       (52, 20, 24), "right")
            return
        if t < KP_CUT_AT:
            self._face(sc, t)
        else:
            self._mass(sc, t)
        FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                   (150, 130, 130), "right")


class BlueSunCutscene:
    """What was watching, finally looking back. Skippable, plays once."""

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()
        self._sky_key = None
        self._sky = None
        rnd = random.Random(41)
        # the men on the parapet. One of them is the one who looks up.
        self.crowd = [[x + rnd.uniform(-14, 14), rnd.uniform(0.88, 1.12),
                       rnd.uniform(0, 6.28), rnd.uniform(0.8, 1.3)]
                      for x in range(150, 1180, 96)]
        # the one who looks up stands well off centre, so what he shouts is
        # not read across the face of the sun
        self.screamer = min(range(len(self.crowd)),
                            key=lambda i: abs(self.crowd[i][0] - 300))
        self.smoke = [[rnd.uniform(0, WIN_W), rnd.uniform(380, 540),
                       rnd.uniform(6, 20), rnd.uniform(3, 11)]
                      for _ in range(26)]

    def skip(self):
        if self.t < BL_TESS_AT - 0.4:
            self.t = BL_TESS_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for sm in self.smoke:
            sm[0] += sm[3] * dt * 2.2
            sm[1] -= sm[3] * dt * 1.6
            if sm[1] < 320:
                sm[1] = 545
                sm[0] = (sm[0] + 137) % WIN_W
        for at, snd in ((BL_SCREAM_AT, "deny"), (BL_TESS_AT, "upgrade"),
                        (BL_TURN_AT, "leak"), (BL_WING_AT, "boom"),
                        (BL_EYE_AT, "deny"), (BL_BLACK_AT, "leak")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= BL_END:
            self.done = True

    # ---- how far over the sky has gone ----------------------------------
    def _turn(self, t):
        return clamp((t - BL_SKY_AT) / 3.6, 0, 1)

    def _sun(self, t):
        return clamp((t - BL_TURN_AT) / 1.4, 0, 1)

    def _gradient(self, gy, turn):
        """The sky, banded top to horizon. Drawn scanline by scanline this
        was 560 lines a frame and most of the scene's cost; it is a still
        image for all but the four seconds the sky is actually moving, so it
        is rounded to a step and kept until the step changes."""
        key = int(turn * 96)
        if key != self._sky_key:
            k = key / 96.0
            top = bl_mix(BL_AMBER[0], BL_BLUE[0], k)
            mid = bl_mix(BL_AMBER[1], BL_BLUE[1], k)
            low = bl_mix(BL_AMBER[2], BL_BLUE[2], k)
            strip = pygame.Surface((1, gy))
            for y in range(gy):
                q = y / float(gy)
                a, b, kk = (top, mid, q / 0.55) if q < 0.55 else \
                           (mid, low, (q - 0.55) / 0.45)
                strip.set_at((0, y), bl_mix(a, b, kk))
            self._sky = pygame.transform.scale(strip, (WIN_W, gy)).convert()
            self._sky_key = key
        return self._sky

    def draw(self, sc):
        t = self.t
        if t >= BL_BLACK_AT:
            sc.fill((0, 0, 0))
            FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                       (44, 46, 52), "right")
            return
        turn, sun = self._turn(t), self._sun(t)
        gy, sy, sr = 560, 366, 96
        sc.blit(self._gradient(gy, turn), (0, 0))
        # ---- and the sun sitting in it -------------------------------
        halo = pygame.Surface((900, 900), pygame.SRCALPHA)
        hc = bl_mix((255, 214, 120), (96, 178, 255), sun)
        for r, al in ((430, 26), (300, 34), (190, 52), (120, 92)):
            pygame.draw.circle(halo, hc + (al,), (450, 450), r)
        sc.blit(halo, (WIN_W // 2 - 450, sy - 450))
        pygame.draw.circle(sc, bl_mix((255, 236, 176), (152, 216, 255), sun),
                           (WIN_W // 2, sy), sr)
        pygame.draw.circle(sc, bl_mix((255, 250, 226), (206, 238, 255), sun),
                           (WIN_W // 2, sy), int(sr * 0.72))
        # ---- what is coming up out of the horizon --------------------
        if BL_TESS_AT <= t:
            rise = clamp((t - BL_TESS_AT) / 5.0, 0, 1)
            ty = gy - 40 - (gy - 40 - sy) * (rise * rise * (3 - 2 * rise))
            fade = clamp((t - BL_TESS_AT) / 0.9, 0, 1)
            if t >= BL_WING_AT:                        # it hands over
                fade *= max(0.0, 1 - (t - BL_WING_AT) / 1.6)
            if fade > 0:
                bl_tesseract(sc, WIN_W // 2, ty, 66 + 56 * rise,
                             (t - BL_TESS_AT) * 1.15, (128, 206, 255),
                             int(255 * fade), 3)
        # ---- the figure in front of it -------------------------------
        if t >= BL_WING_AT:
            grow = clamp((t - BL_WING_AT) / 2.6, 0, 1)
            eye = clamp((t - BL_EYE_AT) / 1.6, 0, 1)
            bob = math.sin(t * 1.3) * 7
            # kept small enough that the blue disc still rings it -
            # it is standing in front of the sun, not replacing it
            bl_winged(sc, WIN_W // 2, sy + 26 + bob, 0.44 + 0.54 * grow,
                      grow, eye)
        # ---- our side of it ------------------------------------------
        pygame.draw.rect(sc, bl_mix((44, 30, 20), (10, 14, 34), turn),
                         (0, gy, WIN_W, WIN_H - gy))
        pygame.draw.line(sc, bl_mix((96, 62, 36), (22, 34, 70), turn),
                         (0, gy), (WIN_W, gy), 4)
        for i in range(0, WIN_W, 92):                  # the parapet they held
            pygame.draw.rect(sc, bl_mix((32, 22, 15), (8, 12, 28), turn),
                             (i, gy - 18, 76, 22))
        # what is left of the fight, going up. Solid circles read as
        # floating rocks, so it goes on thin.
        smk = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
        sc2 = bl_mix((132, 96, 62), (34, 50, 92), turn) + (54,)
        for sm in self.smoke:
            pygame.draw.circle(smk, sc2, (int(sm[0]), int(sm[1])),
                               int(sm[2]))
        sc.blit(smk, (0, 0))
        for i, (x, s2, ph, sp) in enumerate(self.crowd):
            hh = 116 * s2
            up = i == self.screamer and t >= BL_SCREAM_AT
            look = t >= BL_SCREAM_AT + 0.5
            if t < BL_SCREAM_AT:                       # they are celebrating
                jump = abs(math.sin(t * sp * 2.4 + ph)) * 15 * s2
                arm = -2.0 - math.sin(t * sp * 3.1 + ph) * 0.5
            else:                                      # and then they are not
                jump = 0.0
                arm = -1.5 if up else (-0.9 if look else 0.3)
            cm_figure(sc, x, gy + 4 - jump, hh,
                      bl_mix((18, 12, 8), (5, 8, 20), turn), 0.0, arm)
            if look or up:                             # heads tipped back
                pygame.draw.circle(
                    sc, bl_mix((22, 15, 10), (6, 10, 24), turn),
                    (int(x + hh * 0.05), int(gy + 4 - hh * 0.93)),
                    int(hh * 0.115))
        if BL_SCREAM_AT <= t < BL_SCREAM_AT + 2.6:
            x = self.crowd[self.screamer][0]
            a = clamp(1 - (t - BL_SCREAM_AT) / 2.6, 0, 1)
            img = FONTS.render("AAAAAAAH-", 34, (255, 240, 224)).copy()
            img.set_alpha(int(255 * a))
            sc.blit(img, img.get_rect(midbottom=(int(x), gy - 132)))
        # ---- and what the commander was still saying ------------------
        for at, line in BL_LINES:
            end = min(at + BL_LINE_LIFE, BL_SCREAM_AT)
            if at <= t < end:
                a = clamp((t - at) / 0.35, 0, 1) * clamp((end - t) / 0.3, 0, 1)
                img = FONTS.render(line, 24, (240, 234, 220)).copy()
                img.set_alpha(int(255 * a))
                sc.blit(img, img.get_rect(center=(WIN_W // 2, 664)))
        FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                   (150, 140, 130), "right")


class ForgeCutscene:
    """Chapter three's opening. Skippable, and it only plays once.

    Staged like a shot down a working hangar: the light comes from one gap
    between the bay doors, the air is thick with it, and everything in front
    of that light is black. The hall is never at rest - hands cross the floor
    the whole way through."""

    GY = 726                   # the hall floor
    DECK = 548                 # the catwalk she comes out onto
    SX, SW = 430, 116          # the gap between the bay doors, and its width

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()
        rnd = random.Random(9)
        # where the welders are working on the frame, and on what beat
        self.welds = [(rnd.uniform(-120, 120), rnd.uniform(-190, -20),
                       rnd.uniform(0, 6.283), rnd.uniform(1.4, 3.4))
                      for _ in range(11)]
        # yard hands: where they start, how fast and which way, how tall
        self.hands = [(rnd.uniform(0, WIN_W),
                       rnd.choice((-1, 1)) * rnd.uniform(15, 30),
                       rnd.uniform(48, 70)) for _ in range(11)]
        self.crates = []
        x = 8
        while x < WIN_W:
            w = rnd.choice((78, 104, 132))
            self.crates.append((x, w, rnd.choice((20, 26, 32))))
            x += w + rnd.choice((26, 54, 96, 140))
        self._dark = self._lit = self._haze = None

    # -- the hall itself. None of it moves, so it is built once and kept ----
    def _backdrop(self, k):
        """`k` is how much light is in the room: the scene cross-fades from
        a dark copy to a lit one."""
        def c(r, g, b):
            return (min(255, int(r * k) + 3), min(255, int(g * k) + 2),
                    min(255, int(b * k) + 3))
        s = pygame.Surface((WIN_W, WIN_H))
        s.fill(c(11, 6, 8))
        rnd = random.Random(4)
        for gx in range(0, WIN_W, 118):                     # the far wall
            for gy in range(64, self.GY, 132):
                v = rnd.uniform(0.7, 1.3)
                pygame.draw.rect(s, c(20 * v, 11 * v, 13 * v),
                                 (gx + 2, gy + 2, 114, 128))
            pygame.draw.line(s, c(30, 15, 17), (gx, 64), (gx, self.GY), 2)
        for col, gx in enumerate(range(0, WIN_W, 118)):     # panel lights
            for row, gy in enumerate(range(64, self.GY - 130, 132)):
                if (col * 2 + row * 3) % 5 == 0:
                    continue                    # some panels are simply dead
                w = 62 + (col * 17 + row * 29) % 30
                pygame.draw.rect(s, c(74, 18, 17), (gx + 20, gy + 44, w, 7))
                pygame.draw.rect(s, c(146, 30, 26), (gx + 20, gy + 45, w, 3))
        # the gap between the bay doors, and the light coming through it
        for i in range(self.SW // 2, 0, -1):
            q = (1.0 - i / (self.SW / 2.0)) ** 0.55
            pygame.draw.rect(s, c(64 + 191 * q, 18 + 80 * q, 16 + 62 * q),
                             (self.SX - i, 58, i * 2, self.GY - 58))
        bloom = pygame.Surface((560, WIN_H), pygame.SRCALPHA)
        for r, al in ((272, 7), (188, 9), (112, 13), (56, 17)):
            pygame.draw.rect(bloom, (228, 58, 44, int(al * k)),
                             (280 - r, 0, r * 2, WIN_H))
        s.blit(bloom, (self.SX - 280, 0))
        scat = pygame.Surface((WIN_W, 168), pygame.SRCALPHA)
        for i in range(168):        # light scattering off the floor, so that
            pygame.draw.line(scat,  # a body crossing it has something to be
                             (156, 42, 34, int(30 * (i / 167.0) ** 2.0)),
                             (0, i), (WIN_W, i))       # dark against
        s.blit(scat, (0, self.GY - 168))
        pygame.draw.rect(s, c(28, 14, 15), (0, self.GY, WIN_W, WIN_H - self.GY))
        pygame.draw.line(s, c(70, 24, 22), (0, self.GY), (WIN_W, self.GY), 2)
        for i in range(self.SW // 2, 0, -1):                # wet floor
            f = i / (self.SW / 2.0)
            pygame.draw.rect(s, c(120 - 70 * f, 34 - 22 * f, 30 - 20 * f),
                             (self.SX - i, self.GY, i * 2, WIN_H - self.GY))
        halo = pygame.Surface((940, 940), pygame.SRCALPHA)
        for r in range(470, 40, -18):
            q = 1.0 - r / 470.0
            pygame.draw.circle(halo, (168, 42, 33, int(4 + 20 * q * q * k)),
                               (470, 470), r)
        s.blit(halo, (WIN_W // 2 - 470, 400 - 470))
        vig = pygame.Surface((WIN_W, 260), pygame.SRCALPHA)
        for i in range(260):
            pygame.draw.line(vig, (7, 4, 6, int(255 * (1 - i / 259.0) ** 1.4)),
                             (0, i), (WIN_W, i))
        s.blit(vig, (0, 0))
        # roof trusses, black against everything
        pygame.draw.rect(s, (9, 5, 7), (0, 0, WIN_W, 34))
        for i in range(0, WIN_W, 96):
            pygame.draw.line(s, (13, 7, 9), (i, 34), (i + 48, 62), 4)
            pygame.draw.line(s, (13, 7, 9), (i + 48, 34), (i, 62), 4)
        pygame.draw.line(s, (13, 7, 9), (0, 62), (WIN_W, 62), 5)
        return s.convert()          # display format, so the blit is a copy

    def _hazepass(self):
        """The air. Thickest low and near the light."""
        h = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
        band = WIN_H // 24 + 2
        for i in range(24):
            al = 3 + int(15 * (i / 23.0) ** 1.5)
            pygame.draw.rect(h, (128, 28, 25, al), (0, i * (WIN_H // 24),
                                                    WIN_W, band))
        return h.convert_alpha()

    def _catwalk(self, sc, gy):
        """Foreground steel: a walkway across the shot, and the stair off it.
        All of it is black - it is between the camera and the light."""
        D, BLK = self.DECK, (5, 3, 4)
        pygame.draw.rect(sc, BLK, (0, D, WIN_W, 13))
        pygame.draw.line(sc, (30, 14, 14), (0, D), (WIN_W, D), 2)
        pygame.draw.line(sc, BLK, (0, D - 62), (1046, D - 62), 7)
        pygame.draw.line(sc, BLK, (0, D - 33), (1046, D - 33), 4)
        for x in range(18, 1047, 62):
            pygame.draw.line(sc, BLK, (x, D - 64), (x, D), 5)
        for x in range(60, WIN_W, 168):
            pygame.draw.line(sc, BLK, (x, D + 13), (x, gy), 5)
        for i in range(9):                                   # the stair down
            sx, sy = 110 + i * 26, D + 13 + i * 13
            pygame.draw.line(sc, BLK, (sx, sy), (sx + 27, sy), 5)
            pygame.draw.line(sc, BLK, (sx + 26, sy), (sx + 26, sy + 14), 4)

    def _her(self, sc, t):
        """Her, at the open end of the walkway. Everything about her is black
        except the ribbon, which is the whole point of the shot."""
        walk = clamp((t - FG_HER_AT) / 2.6, 0, 1)
        x = 1246 - 122 * walk
        y, h = self.DECK, 182
        BLK = (4, 2, 3)
        pygame.draw.polygon(sc, BLK, [(x - h * 0.17, y), (x + h * 0.16, y),
                                      (x + h * 0.11, y - h * 0.54),
                                      (x - h * 0.11, y - h * 0.54)])
        pygame.draw.rect(sc, BLK, (x - h * 0.11, y - h * 0.80,
                                   h * 0.22, h * 0.30))
        pygame.draw.polygon(sc, BLK, [(x - h * 0.17, y - h * 0.74),
                                      (x + h * 0.17, y - h * 0.74),
                                      (x + h * 0.13, y - h * 0.62),
                                      (x - h * 0.13, y - h * 0.62)])
        pygame.draw.circle(sc, BLK, (int(x), int(y - h * 0.90)),
                           int(h * 0.115))
        pygame.draw.line(sc, BLK, (x, y - h * 0.72),
                         (x - h * 0.19, y - h * 0.48), int(h * 0.085))
        # the light off the machine finds her edge
        pygame.draw.line(sc, (146, 42, 36), (x - h * 0.11, y - h * 0.84),
                         (x - h * 0.16, y - h * 0.02), 2)
        # the ribbon. The one thing carried over from the photograph, and the
        # only thing in the frame allowed to be brighter than the hall.
        pygame.draw.circle(sc, (255, 142, 152),
                           (int(x + h * 0.10), int(y - h * 0.95)),
                           max(2, int(h * 0.05)))
        pygame.draw.line(sc, (236, 112, 124), (x + h * 0.12, y - h * 0.93),
                         (x + h * 0.24, y - h * 0.78), 3)

    def skip(self):
        if self.t < FG_HER_AT - 0.4:
            self.t = FG_HER_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for at, snd in ((FG_EYE_AT, "upgrade"), (FG_CUT_AT, "leak")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= FG_END:
            self.done = True

    def draw(self, sc):
        t = self.t
        if t >= FG_CUT_AT:                       # the cut is hard, not a fade
            sc.fill((0, 0, 0))
            FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                       (48, 46, 44), "right")
            return
        if self._lit is None:
            self._dark = self._backdrop(0.18)
            self._lit = self._backdrop(1.0)
            self._haze = self._hazepass()
        lit = clamp((t - FG_RISE_AT) / 3.0, 0, 1)
        if lit >= 1.0:
            # once the hall is fully up there is nothing to cross-fade, and
            # a straight copy is worth several milliseconds a frame
            self._lit.set_alpha(None)
            sc.blit(self._lit, (0, 0))
        else:
            sc.blit(self._dark, (0, 0))
            if lit > 0:
                self._lit.set_alpha(int(255 * lit))
                sc.blit(self._lit, (0, 0))
        # the camera cranes up the machine as it is revealed. The floor stays
        # where it is and the machine is tall enough to reach the roof -
        # moving the ground instead walked it off the bottom of the frame.
        f = clamp((t - FG_TILT_START) / (FG_TILT_END - FG_TILT_START), 0, 1)
        f = f * f * (3 - 2 * f)
        gy = self.GY + int(26 * f)
        built = clamp(0.12 + f * 0.95, 0, 1)
        eye = clamp((t - FG_EYE_AT) / 1.6, 0, 1)
        fg_machine(sc, WIN_W // 2, gy, 3.53, built, eye)
        for (wx, wy, ph, rate) in self.welds:                # welders
            phase = math.sin(t * rate + ph)
            if phase > 0.72 and built > 0.2:
                px = WIN_W // 2 + wx * 3.53
                py = gy + wy * 3.53
                # an arc, not a bubble: a hot point, a tight halo, and sparks
                hot = 2 + int(5 * (phase - 0.72) * 3.6)
                fl = pygame.Surface((72, 72), pygame.SRCALPHA)
                for r, al in ((34, 16), (22, 26), (12, 44)):
                    pygame.draw.circle(fl, (255, 186, 148, al), (36, 36), r)
                sc.blit(fl, (px - 36, py - 36))
                pygame.draw.circle(sc, (255, 244, 226), (int(px), int(py)),
                                   hot)
                for k in range(3):
                    ang = ph * 3.1 + k * 2.4 + t * 5.0
                    d = 9 + 15 * (phase - 0.72) * 3.6
                    pygame.draw.circle(sc, (255, 202, 150),
                                       (int(px + math.cos(ang) * d),
                                        int(py + abs(math.sin(ang)) * d)), 2)
        for i, (x0, spd, h) in enumerate(self.hands):        # the yard, working
            fg_worker(sc, (x0 + spd * t) % (WIN_W + 200) - 100, gy - 2, h,
                      (6, 3, 5), t, i)
        sc.blit(self._haze, (0, 0))
        for (cx, cw, ch) in self.crates:                     # stacked stock
            pygame.draw.rect(sc, (5, 3, 4), (cx, gy - ch, cw, ch))
        self._catwalk(sc, gy)
        if t >= FG_HER_AT:
            self._her(sc, t)
        if t >= FG_LINE_AT:
            a = clamp((t - FG_LINE_AT) / 1.0, 0, 1)
            surf = FONTS.render("IT IS FINALLY TIME.", 30,
                                (238, 228, 224)).copy()
            surf.set_alpha(int(255 * a))
            sc.blit(surf, surf.get_rect(center=(WIN_W // 2, 668)))
        FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                   (96, 62, 60), "right")


# The two cutscenes, watchable again from EXTRAS. They stay dark until they
# have been seen once - a gallery that shows you an ending you have not
# reached yet is not a reward, it is a spoiler.
# ----------------------------------------------------------------------------
# THE QUIET YEARS. What happens after the Sapphire Guardian falls: the line
# stands to, waiting for whatever comes next - and nothing does. They go
# home. Five years pass. Then the general has a question about the shipping.
# ----------------------------------------------------------------------------
QY_LINES = (
    (1.2, 5.4, "STAND TO. EYES UP. IT NEVER COMES DOWN ALONE."),
    (6.0, 10.4, "...sir. There's nothing on the scope."),
    (11.0, 15.0, "Nothing at all. Not a contact anywhere."),
    (16.4, 21.0, "Then stand down. Get them inside and get them fed."),
    (22.0, 26.0, "It's over. Go home."),
)
QY_FIVE_AT = 27.5           # five years, in one card
QY_BRIEF_AT = 33.0          # and the general, with a chart
QY_BRIEF = (
    (34.0, 39.0, "Sixteen hulls in nine months. Ore, grain, fuel."),
    (39.6, 44.6, "Cut open, stripped, and let go again."),
    (45.2, 50.2, "No colours. No demands. Nothing on any register."),
    (50.8, 55.6, "Pirates, then. Modern ones. Find me their harbour."),
)
QY_ROAR_AT = 57.0           # something that is not a pirate
QY_BLACK_AT = 61.4
QY_END = 63.6


class QuietYearsCutscene:
    """The line stands down, five years pass, and the shipping starts
    going missing. Skippable, plays once."""

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()
        rnd = random.Random(1907)
        # the men on the parapet, still looking up
        self.crowd = [[x + rnd.uniform(-16, 16), rnd.uniform(0.9, 1.12),
                       rnd.uniform(0, 6.28), rnd.uniform(0.7, 1.2)]
                      for x in range(140, 1180, 104)]
        self.stars = [[rnd.uniform(0, WIN_W), rnd.uniform(40, 330),
                       rnd.uniform(0.6, 2.1)] for _ in range(70)]
        # the shipping lanes on the general's chart
        self.lanes = [[rnd.uniform(120, 1140), rnd.uniform(430, 640),
                       rnd.uniform(120, 300), rnd.uniform(0, 6.28)]
                      for _ in range(9)]
        self.marks = [[rnd.uniform(200, 1060), rnd.uniform(450, 620),
                       rnd.uniform(0, 6.28)] for _ in range(16)]

    def skip(self):
        if self.t < QY_FIVE_AT - 0.4:
            self.t = QY_FIVE_AT - 0.4
        elif self.t < QY_ROAR_AT - 0.4:
            self.t = QY_ROAR_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for at, snd in ((1.2, "deny"), (16.4, "build"), (22.0, "upgrade"),
                        (QY_FIVE_AT, "leak"), (QY_BRIEF_AT, "build"),
                        (QY_ROAR_AT, "boom"), (QY_BLACK_AT, "leak")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= QY_END:
            self.done = True

    # -- the three acts ----------------------------------------------------
    def _relief(self, t):
        """How far the line has come down off its guard, 0 to 1."""
        return clamp((t - 16.4) / 5.0, 0.0, 1.0)

    def draw(self, sc):
        t = self.t
        if t >= QY_BLACK_AT:
            sc.fill((0, 0, 0))
            f = clamp((t - QY_BLACK_AT) / 1.2, 0, 1)
            if f < 1.0:
                self._roar(sc, 1.0 - f)
            return
        elif t >= QY_ROAR_AT:
            self._roar(sc, 1.0)
        elif t >= QY_BRIEF_AT:
            self._brief(sc, t)
        elif t >= QY_FIVE_AT:
            self._card(sc, t)
        else:
            self._parapet(sc, t)
        FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                   (150, 140, 130), "right")

    # ---- act one: the wall, and nothing on it ---------------------------
    def _parapet(self, sc, t):
        ease = self._relief(t)
        gy = 552                        # the fire step they are standing on
        # the sky lightens as the alert comes off: dawn, and nothing in it
        top = (int(10 + 34 * ease), int(15 + 44 * ease), int(34 + 56 * ease))
        low = (int(30 + 116 * ease), int(34 + 92 * ease), int(48 + 62 * ease))
        for k in range(0, gy, 4):
            f = k / float(gy)
            f = f * f
            sc.fill((int(top[0] + (low[0] - top[0]) * f),
                     int(top[1] + (low[1] - top[1]) * f),
                     int(top[2] + (low[2] - top[2]) * f)), (0, k, WIN_W, 4))
        for sx, sy, k in self.stars:
            a = clamp(1.0 - ease * 1.25, 0.0, 1.0)
            if a <= 0.02:
                continue
            v = int(150 * a * (0.55 + 0.45 * math.sin(t * 2.0 + sx)))
            pygame.draw.circle(sc, (v, v, min(255, int(v * 1.2))),
                               (int(sx), int(sy)), max(1, int(k)))
        # searchlights, quartering an empty sky - and switched off at the end
        beam = clamp(1.0 - ease * 1.6, 0.0, 1.0)
        if beam > 0.02:
            lig = pygame.Surface((WIN_W, gy), pygame.SRCALPHA)
            for k, (bx, sw) in enumerate(((190, 0.9), (640, -0.7), (1090, 1.1))):
                a2 = -1.62 + math.sin(t * 0.45 * sw + k * 2.1) * 0.62
                for wsp, al in ((0.10, 26), (0.05, 34)):
                    pygame.draw.polygon(lig, (196, 214, 190, int(al * beam)), [
                        (bx, gy),
                        (bx + math.cos(a2 - wsp) * 900,
                         gy + math.sin(a2 - wsp) * 900),
                        (bx + math.cos(a2 + wsp) * 900,
                         gy + math.sin(a2 + wsp) * 900)])
            sc.blit(lig, (0, 0))
        # ---- the men, standing on the fire step ----------------------
        FIG = (16, 20, 17)
        for i2, (x, sc2, ph, bob) in enumerate(self.crowd):
            hh = 132 * sc2
            up = 1.0 - ease
            # rifle shouldered and up at the start, slung and down at the end
            arm = -1.24 * up + 0.46 * (1 - up)
            sag = ease * 5 * sc2 + math.sin(t * 1.1 + ph) * 1.6
            cm_figure(sc, x, gy + sag, hh, FIG, 0.22 * ease, arm)
            sx2 = x + math.cos(arm) * hh * 0.34
            sy2 = gy + sag - hh * 0.74 + math.sin(arm) * hh * 0.30
            bx2 = sx2 - math.cos(arm) * hh * 0.30
            by2 = sy2 - math.sin(arm) * hh * 0.30
            mx = sx2 + math.cos(arm) * hh * 0.34
            my = sy2 + math.sin(arm) * hh * 0.34
            pygame.draw.line(sc, (26, 24, 20), (bx2, by2), (mx, my),
                             max(2, int(4 * sc2)))
            # helmet brim, so a head reads as a helmet at this size
            hx, hy = x, gy + sag - hh * 0.90
            pygame.draw.rect(sc, FIG, (hx - hh * 0.15, hy - hh * 0.02,
                                       hh * 0.30, hh * 0.045))
        # the breath going out of them, once the order lands
        if ease > 0.2:
            for i2, (x, sc2, ph, bob) in enumerate(self.crowd):
                if i2 % 2:
                    continue
                rise = ((t * 24 + ph * 30) % 96)
                a = (clamp((ease - 0.2) * 2.2, 0, 1)
                     * clamp(1 - rise / 96.0, 0, 1))
                if a <= 0.03:
                    continue
                sf = pygame.Surface((36, 36), pygame.SRCALPHA)
                pygame.draw.circle(sf, (214, 226, 232, int(80 * a)), (18, 18),
                                   int(4 + rise * 0.10))
                sc.blit(sf, (x + 6, gy - 128 * sc2 - rise))
        # ---- the wall in front of them -------------------------------
        WALL, LIT, DK = (34, 38, 36), (52, 58, 54), (20, 23, 22)
        pygame.draw.rect(sc, WALL, (0, gy - 52, WIN_W, WIN_H - gy + 52))
        for k in range(0, WIN_W, 116):                 # merlons
            pygame.draw.rect(sc, WALL, (k + 14, gy - 96, 78, 48))
            pygame.draw.rect(sc, DK, (k + 14, gy - 96, 78, 48), 2)
            pygame.draw.rect(sc, LIT, (k + 14, gy - 96, 78, 4))
        pygame.draw.rect(sc, LIT, (0, gy - 52, WIN_W, 5))
        for row in range(0, 5):                        # stone courses
            yy = gy - 8 + row * 40
            pygame.draw.line(sc, DK, (0, yy), (WIN_W, yy), 2)
            for k in range(0, WIN_W, 92):
                off = 46 if row % 2 else 0
                pygame.draw.line(sc, DK, (k + off, yy), (k + off, yy + 40), 2)
        # a lamp or two burning along the inside of the wall
        for k in (170, 620, 1080):
            fl = 0.7 + 0.3 * math.sin(t * 6.0 + k)
            gl = pygame.Surface((90, 90), pygame.SRCALPHA)
            pygame.draw.circle(gl, (232, 176, 96, int(40 * fl)), (45, 45), 40)
            sc.blit(gl, (k - 45, gy + 46))
            pygame.draw.circle(sc, (238, 196, 122), (k, gy + 92), 4)
        self._say(sc, t, QY_LINES)

    # ---- the card: five years -------------------------------------------
    def _card(self, sc, t):
        sc.fill((0, 0, 0))
        f = clamp((t - QY_FIVE_AT) / 1.0, 0, 1)
        g = clamp((QY_BRIEF_AT - t) / 1.0, 0, 1)
        a = min(f, g)
        col = (int(214 * a), int(206 * a), int(178 * a))
        FONTS.draw(sc, "FIVE YEARS LATER", (WIN_W // 2, WIN_H // 2 - 26),
                   40, col, "center")
        w = int(360 * a)
        pygame.draw.rect(sc, col, (WIN_W // 2 - w // 2, WIN_H // 2 + 30, w, 2))

    # ---- act two: the general, and a chart with holes in it -------------
    def _brief(self, sc, t):
        sc.fill((16, 20, 25))
        # the room: a bunker, lit from over the table
        pygame.draw.rect(sc, (24, 30, 37), (0, 0, WIN_W, 470))
        for k in range(0, WIN_W, 150):                 # ribs down the walls
            pygame.draw.rect(sc, (19, 24, 30), (k, 0, 6, 470))
        for k in range(2):                             # cable runs
            pygame.draw.line(sc, (30, 38, 46), (0, 62 + k * 26),
                             (WIN_W, 50 + k * 30), 3)
        pygame.draw.rect(sc, (12, 16, 20), (0, 470, WIN_W, WIN_H - 470))
        # the lamp over the chart
        pygame.draw.line(sc, (40, 48, 56), (WIN_W // 2, 0), (WIN_W // 2, 108), 4)
        pygame.draw.polygon(sc, (46, 56, 64),
                            [(WIN_W // 2 - 74, 150), (WIN_W // 2 - 26, 106),
                             (WIN_W // 2 + 26, 106), (WIN_W // 2 + 74, 150)])
        pygame.draw.ellipse(sc, (250, 236, 196),
                            (WIN_W // 2 - 74, 140, 148, 20))
        cone = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
        pygame.draw.polygon(cone, (250, 236, 196, 20),
                            [(WIN_W // 2 - 66, 152), (WIN_W // 2 + 66, 152),
                             (WIN_W - 40, 700), (40, 700)])
        sc.blit(cone, (0, 0))
        # pinned paper on the back wall - hulls that did not come home
        for k, px in enumerate(range(760, 1200, 106)):
            pygame.draw.rect(sc, (54, 58, 52), (px, 190, 78, 104))
            pygame.draw.rect(sc, (30, 34, 30), (px, 190, 78, 104), 2)
            for ln in range(5):
                pygame.draw.line(sc, (86, 92, 82), (px + 9, 208 + ln * 16),
                                 (px + 69 - (ln % 3) * 14, 208 + ln * 16), 2)
            if k % 2 == 0:
                pygame.draw.line(sc, (188, 74, 66), (px + 10, 200),
                                 (px + 68, 284), 3)
        # the chart table, lit from above
        pygame.draw.rect(sc, (30, 42, 48), (300, 470, WIN_W - 380, 236),
                         border_radius=8)
        pygame.draw.rect(sc, (62, 82, 92), (300, 470, WIN_W - 380, 236), 3,
                         border_radius=8)
        glow = pygame.Surface((WIN_W - 380, 236), pygame.SRCALPHA)
        pygame.draw.ellipse(glow, (128, 190, 220, 40), (0, 0, WIN_W - 380, 236))
        sc.blit(glow, (300, 470))
        # the lanes, and the ships that are no longer on them
        clip = sc.get_clip()
        sc.set_clip(pygame.Rect(304, 474, WIN_W - 388, 228))
        for lx, ly, ll, la in self.lanes:
            pygame.draw.line(sc, (78, 118, 138), (lx, ly),
                             (lx + math.cos(la) * ll,
                              ly + math.sin(la) * ll * 0.4), 1)
        show = clamp((t - QY_BRIEF_AT - 1.6) / 8.0, 0, 1)
        for i2, (mx, my, ma) in enumerate(self.marks):
            if i2 / float(len(self.marks)) > show:
                continue
            pulse = 0.6 + 0.4 * math.sin(t * 4.0 + i2)
            pygame.draw.line(sc, (232, 96, 84), (mx - 8, my - 8),
                             (mx + 8, my + 8), 2)
            pygame.draw.line(sc, (232, 96, 84), (mx + 8, my - 8),
                             (mx - 8, my + 8), 2)
            pygame.draw.circle(sc, (232, 96, 84), (int(mx), int(my)),
                               int(11 + 7 * pulse), 1)
        sc.set_clip(clip)
        FONTS.draw(sc, "SHIPPING - LOSSES", (WIN_W // 2 + 60, 484), 15,
                   (150, 190, 210), "center")
        FONTS.draw(sc, f"{int(16 * show):02d} HULLS", (WIN_W - 104, 484), 15,
                   (232, 96, 84), "right")
        # the general, in the light of his own chart
        gx, gy2, H = 196, 706, 372
        arm = -0.55 + math.sin(t * 0.9) * 0.30
        cm_figure(sc, gx + 5, gy2, H, (52, 62, 72), 0.4, arm)   # rim
        cm_figure(sc, gx, gy2, H, (11, 14, 18), 0.4, arm)
        cap_y = gy2 - H * 0.90
        pygame.draw.rect(sc, (11, 14, 18),                  # cap
                         (gx - H * 0.135, cap_y - H * 0.075,
                          H * 0.27, H * 0.075), border_radius=3)
        pygame.draw.rect(sc, (9, 11, 15),                   # peak
                         (gx + H * 0.02, cap_y - H * 0.012, H * 0.19, H * 0.02))
        pygame.draw.rect(sc, (188, 162, 84),                # cap band
                         (gx - H * 0.135, cap_y - H * 0.024, H * 0.27, 4))
        for dy2 in (0.60, 0.565):                           # ribbons and braid
            pygame.draw.rect(sc, (196, 168, 84),
                             (gx - H * 0.10, gy2 - H * dy2, H * 0.09, 5))
        for dx in (-0.115, 0.115):
            pygame.draw.rect(sc, (196, 168, 84),
                             (gx + H * dx - 9, gy2 - H * 0.705, 18, 5))
        # two staff officers, further back and smaller
        for sx3, hh2 in ((980, 268), (1088, 250)):
            cm_figure(sc, sx3, 700, hh2, (14, 18, 23), 0.1,
                      0.5 + math.sin(t * 0.7 + sx3) * 0.12)
        self._say(sc, t, QY_BRIEF)

    # ---- act three: whatever is actually out there ----------------------
    def _roar(self, sc, a):
        t = self.t
        f = clamp((t - QY_ROAR_AT) / 1.5, 0, 1)
        base = int(8 + 30 * f)
        sc.fill((int(base * a), int(base * 0.44 * a), int(base * 0.40 * a)))
        S = 210 + 250 * f
        cx2 = WIN_W // 2 + int(math.sin(t * 47) * 7 * f)
        cy2 = WIN_H // 2 + 30 + int(math.cos(t * 39) * 6 * f)
        DK = (int(9 * a), int(8 * a), int(10 * a))
        SKIN = (int(48 * a), int(36 * a), int(38 * a))
        SKIN2 = (int(66 * a), int(50 * a), int(50 * a))
        MAW = (int(126 * a), int(20 * a), int(26 * a))
        GUM = (int(74 * a), int(14 * a), int(20 * a))
        TOOTH = (int(224 * a), int(212 * a), int(192 * a))
        # something enormous, behind it, lit from inside
        gl = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
        pygame.draw.ellipse(gl, (int(150 * a), int(30 * a), int(24 * a), 60),
                            (cx2 - S * 1.5, cy2 - S * 1.4, S * 3.0, S * 2.8))
        sc.blit(gl, (0, 0))
        # ---- the skull, ragged rather than geometric -----------------
        rnd = random.Random(88)
        head = []
        for k in range(22):
            ang = -math.pi + k * (2 * math.pi / 22.0)
            rr = (0.98 if abs(math.cos(ang)) > 0.6 else 0.86)
            rr *= 1.0 + rnd.uniform(-0.09, 0.09)
            head.append((cx2 + math.cos(ang) * S * rr * 0.90,
                         cy2 + math.sin(ang) * S * rr * 1.06))
        pygame.draw.polygon(sc, SKIN, head)
        pygame.draw.polygon(sc, DK, head, 7)
        # brow ridge and the plates over it
        pygame.draw.polygon(sc, SKIN2, [
            (cx2 - S * 0.86, cy2 - S * 0.42), (cx2, cy2 - S * 0.80),
            (cx2 + S * 0.86, cy2 - S * 0.42), (cx2 + S * 0.70, cy2 - S * 0.20),
            (cx2 - S * 0.70, cy2 - S * 0.20)])
        for k in range(-2, 3):
            pygame.draw.line(sc, DK, (cx2 + k * S * 0.24, cy2 - S * 0.74),
                             (cx2 + k * S * 0.30, cy2 - S * 0.24), 3)
        # horns, sweeping back off the crown
        for sgn in (-1, 1):
            for k, (bx, by, tx, ty, w) in enumerate((
                    (0.44, 0.82, 1.06, 1.86, 0.20),
                    (0.68, 0.66, 1.34, 1.30, 0.15))):
                horn = [(cx2 + sgn * S * bx, cy2 - S * by),
                        (cx2 + sgn * S * (bx + w), cy2 - S * (by - 0.06)),
                        (cx2 + sgn * S * (tx + 0.02), cy2 - S * ty),
                        (cx2 + sgn * S * (bx + w * 0.5), cy2 - S * (by + 0.10))]
                pygame.draw.polygon(sc, SKIN2, horn)
                pygame.draw.polygon(sc, DK, horn, 4)
        # ---- the jaws, wide open and screaming -----------------------
        open_ = 0.30 + 0.70 * f + 0.04 * math.sin(t * 9)
        jy = cy2 + S * (0.16 + 0.62 * open_)
        jaw = [(cx2 - S * 0.66, cy2 + S * 0.02), (cx2 + S * 0.66, cy2 + S * 0.02),
               (cx2 + S * 0.54, jy + S * 0.12), (cx2, jy + S * 0.20),
               (cx2 - S * 0.54, jy + S * 0.12)]
        pygame.draw.polygon(sc, SKIN, jaw)
        pygame.draw.polygon(sc, DK, jaw, 6)
        maw = [(cx2 - S * 0.62, cy2 - S * 0.02), (cx2 + S * 0.62, cy2 - S * 0.02),
               (cx2 + S * 0.44, jy), (cx2 - S * 0.44, jy)]
        pygame.draw.polygon(sc, MAW, maw)
        pygame.draw.polygon(sc, DK, maw, 5)
        # a throat, so the mouth has depth rather than being a flat panel
        pygame.draw.polygon(sc, (int(46 * a), int(6 * a), int(12 * a)), [
            (cx2 - S * 0.30, cy2 + S * 0.14), (cx2 + S * 0.30, cy2 + S * 0.14),
            (cx2 + S * 0.20, jy - S * 0.10), (cx2 - S * 0.20, jy - S * 0.10)])
        pygame.draw.rect(sc, GUM, (cx2 - S * 0.62, cy2 - S * 0.06,
                                   S * 1.24, S * 0.09))
        rnd2 = random.Random(313)
        for k in range(11):                             # upper teeth
            tx = cx2 - S * 0.58 + k * S * 0.108
            ln = S * (0.13 + rnd2.uniform(-0.04, 0.05))
            pygame.draw.polygon(sc, TOOTH, [
                (tx, cy2 - S * 0.03), (tx + S * 0.062, cy2 - S * 0.03),
                (tx + S * 0.028 + rnd2.uniform(-0.01, 0.01) * S, cy2 + ln)])
        for k in range(10):                             # lower teeth
            tx = cx2 - S * 0.40 + k * S * 0.088
            ln = S * (0.12 + rnd2.uniform(-0.04, 0.05))
            pygame.draw.polygon(sc, TOOTH, [
                (tx, jy), (tx + S * 0.058, jy), (tx + S * 0.028, jy - ln)])
        # ---- eyes, far too many of them ------------------------------
        for k, (ex, ey, er) in enumerate(((-0.60, -0.44, 0.085),
                                          (-0.28, -0.62, 0.10),
                                          (0.28, -0.62, 0.10),
                                          (0.60, -0.44, 0.085),
                                          (-0.42, -0.20, 0.062),
                                          (0.42, -0.20, 0.062))):
            px2, py2 = int(cx2 + ex * S), int(cy2 + ey * S)
            r = int(er * S)
            burn = pygame.Surface((r * 4, r * 4), pygame.SRCALPHA)
            pygame.draw.circle(burn, (int(236 * a), int(150 * a), int(40 * a),
                                      44), (r * 2, r * 2), int(r * 1.5))
            sc.blit(burn, (px2 - r * 2, py2 - r * 2))
            pygame.draw.circle(sc, (int(240 * a), int(198 * a), int(78 * a)),
                               (px2, py2), r)
            pygame.draw.circle(sc, DK, (px2, py2), r, 3)
            pygame.draw.ellipse(sc, DK, (px2 - r * 0.22, py2 - r * 0.86,
                                         r * 0.44, r * 1.72))
        if f > 0.45:
            # on its own band at the foot of the frame: over the crown it was
            # read through the horns, and inside the mouth through the teeth
            sh = int(math.sin(t * 53) * 3)
            band = pygame.Surface((WIN_W, 56), pygame.SRCALPHA)
            band.fill((0, 0, 0, int(190 * a)))
            sc.blit(band, (0, WIN_H - 56))
            FONTS.draw(sc, "-- CONTACT --", (WIN_W // 2 + sh, WIN_H - 42), 26,
                       (int(232 * a), int(84 * a), int(72 * a)), "center")

    # ---- the words -------------------------------------------------------
    def _say(self, sc, t, lines):
        for a, b, txt in lines:
            if not (a <= t < b):
                continue
            f = clamp((t - a) / 0.5, 0, 1) * clamp((b - t) / 0.5, 0, 1)
            col = (int(228 * f), int(226 * f), int(206 * f))
            box = pygame.Surface((WIN_W, 62), pygame.SRCALPHA)
            box.fill((0, 0, 0, int(150 * f)))
            sc.blit(box, (0, WIN_H - 118))
            FONTS.draw(sc, txt, (WIN_W // 2, WIN_H - 100), 22, col, "center")
            break


# ----------------------------------------------------------------------------
# THE LAST SIEGE. The delta is cleared and the Sea King is off the board, and
# the general has one more map to put in front of you - the one he has been
# holding back. Then the three of them open their eyes.
# ----------------------------------------------------------------------------
LS_LINES = (
    (1.0, 6.2, "Sit down. This is the last map I am going to show you."),
    (6.8, 12.0, "Every flag we have fought is on it. All three, in one place."),
    (12.6, 18.0, "They stopped fighting each other about an hour ago."),
    (18.6, 24.2, "The Pact is a third of what it was. The Syndicate carried "
                 "them."),
    (24.8, 30.6, "And the Coalition has been waiting for both of them to "
                 "finish."),
    (31.2, 36.8, "We have taken every sector they held. This is the last "
                 "one."),
    (37.4, 43.0, "One siege. Everything they have left is standing in it."),
    (43.6, 49.4, "Be ready. There is nothing after this."),
)
LS_EYES_AT = 50.4          # and the three of them look up
LS_BLACK_AT = 61.0
LS_END = 63.4


# ---------------------------------------------------------------------------
# THE LAST WAVE.
#
# The tour does not end with a boss walking up the road. It stops, and this
# happens, and what you come back to is not the same sector. Named for what
# it is rather than for a wave number - the number has already moved once.
# ---------------------------------------------------------------------------
FS_LINES = (
    (0.8, 5.6, "COMMANDER: It's over. Every sector. Every flag.",
     (226, 230, 236)),
    (6.2, 11.4, "COMMANDER: Three wars. You started all of them.",
     (226, 230, 236)),
    (12.0, 16.4, "Get up.", (226, 230, 236)),
    (17.2, 23.8, "BLUE LEADER: You fool. You have no idea what's coming.",
     (150, 198, 246)),
)
FS_SMILE_AT = 24.6         # and he smiles, which is worse than the line
FS_SHADOW_AT = 27.0        # the light goes
FS_FINGER_AT = 28.6        # one finger, and you never see the rest of it
FS_CRUSH_AT = 31.4
FS_OUT_AT = 34.0           # outside: the general, pulled clear
FS_EVAC_AT = 41.0          # the prototype ships, and everyone running for them
FS_LIFT_AT = 50.0
FS_SPACE_AT = 56.0         # and the sector, going up with them
FS_BLACK_AT = 66.0
FS_END = 68.4


class FinalSiegeCutscene:
    """The commander, the blue leader, and the hand. Skippable; it plays
    once, on the last wave of the last tour, and the board you come back to
    is in orbit."""

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()
        rnd = random.Random(300)
        self.stars = [(rnd.uniform(0, WIN_W), rnd.uniform(0, WIN_H),
                       rnd.uniform(0.6, 2.2), rnd.uniform(0, 6.28))
                      for _ in range(220)]
        self.running = [(rnd.uniform(-200, WIN_W), rnd.uniform(0.8, 1.3),
                         rnd.uniform(0, 6.28)) for _ in range(14)]
        self.dust = [[rnd.uniform(0, WIN_W), rnd.uniform(300, 620),
                      rnd.uniform(4, 16), rnd.uniform(0.8, 2.4)]
                     for _ in range(50)]

    def skip(self):
        """One press jumps to the evacuation; a second ends it."""
        if self.t < FS_EVAC_AT - 0.4:
            self.t = FS_EVAC_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for at, snd in ((FS_SMILE_AT, "deny"), (FS_CRUSH_AT, "boom"),
                        (FS_EVAC_AT, "wave"), (FS_LIFT_AT, "boom")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= FS_END:
            self.done = True

    # -- pieces ----------------------------------------------------------
    def _room(self, sc, t):
        """A command room with one wall left, lit from a hole in it."""
        for i in range(0, WIN_H, 4):
            f = i / float(WIN_H)
            sc.fill((int(lerp(30, 16, f)), int(lerp(32, 18, f)),
                     int(lerp(40, 22, f))), (0, i, WIN_W, 4))
        gy = 596
        pygame.draw.rect(sc, (26, 27, 34), (0, gy, WIN_W, WIN_H - gy))
        pygame.draw.line(sc, (52, 55, 68), (0, gy), (WIN_W, gy), 3)
        # A WALL, with a hole torn in it. Drawn as a wall first - a lit
        # shape floating in the dark just read as a monolith standing in
        # the room, which is not what it is.
        pygame.draw.rect(sc, (38, 40, 50), (0, 168, WIN_W, gy - 168))
        pygame.draw.line(sc, (54, 57, 70), (0, 168), (WIN_W, 168), 4)
        for gx in range(0, WIN_W, 160):        # panel joins along it
            pygame.draw.line(sc, (32, 34, 42), (gx, 168), (gx, gy), 3)
        breach = [(742, gy), (1058, gy), (1030, 322), (986, 236),
                  (908, 300), (862, 214), (806, 296), (764, 244)]
        pygame.draw.polygon(sc, (96, 108, 130), breach)
        pygame.draw.polygon(sc, (24, 26, 32), breach, 4)
        # and the light coming through it, thrown across the deck
        shaft = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
        pygame.draw.polygon(shaft, (150, 172, 210, 46),
                            [(770, 250), (1030, 250), (1300, gy + 120),
                             (420, gy + 120)])
        sc.blit(shaft, (0, 0))
        for i in range(14):                       # rubble on the deck
            pygame.draw.circle(sc, (46, 48, 58),
                               (int(120 + i * 91), gy + 10 + (i * 37) % 26),
                               4 + (i % 4))

    def _figures(self, sc, t):
        """The commander standing, the blue leader on the floor."""
        gy = 596
        # the leader, down, propped on one arm
        bl = (86, 132, 190)
        pygame.draw.line(sc, bl, (470, gy - 8), (560, gy - 62), 15)
        pygame.draw.circle(sc, bl, (576, gy - 74), 17)
        pygame.draw.line(sc, bl, (492, gy - 22), (486, gy), 11)
        if t >= FS_SMILE_AT:
            # the smile. It is two pixels of line and it is the whole scene.
            pygame.draw.arc(sc, (232, 240, 250),
                            (566, gy - 76, 22, 16), 3.4, 6.0, 3)
        # the commander, sidearm raised
        cm = (58, 64, 58)
        pygame.draw.circle(sc, cm, (330, gy - 132), 19)
        pygame.draw.line(sc, cm, (330, gy - 116), (330, gy - 54), 20)
        for sgn in (-1, 1):
            pygame.draw.line(sc, cm, (330, gy - 54),
                             (330 + sgn * 20, gy), 13)
        pygame.draw.line(sc, cm, (330, gy - 104), (404, gy - 92), 11)
        pygame.draw.rect(sc, (34, 36, 34), (404, gy - 98, 28, 12))

    def _hand(self, sc, t):
        """One finger. You never see the rest of it, and that is the point:
        whatever it belongs to does not fit in the frame."""
        # it enters the top of the frame straight away and accelerates -
        # starting it a screen and a half up meant the shot that was
        # supposed to be "something is coming down" was an empty dark room
        f = clamp((t - FS_FINGER_AT) / (FS_CRUSH_AT - FS_FINGER_AT), 0, 1)
        f = f * f
        drop = -300 + f * 840
        PLATE = (150, 156, 168)
        DARKI = (22, 24, 30)
        pts = [(240, drop - 460), (700, drop - 460), (690, drop + 40),
               (560, drop + 130), (330, drop + 96), (250, drop - 40)]
        pygame.draw.polygon(sc, PLATE, pts)
        pygame.draw.polygon(sc, DARKI, pts, 5)
        for j in range(3):                        # the knuckle joints
            jy = drop - 300 + j * 120
            if jy > 0:
                pygame.draw.line(sc, shade(PLATE, 0.66), (256, jy),
                                 (694, jy), 6)
        # the pad of it, so the near end reads as a fingertip
        pygame.draw.arc(sc, shade(PLATE, 0.60),
                        (280, drop - 80, 380, 220), 3.34, 6.08, 7)
        # THE SAME TRIAD as the machine on the board, the pad you build
        # and the recognition plate. It is a fourth copy of one fact and
        # it was written as bare literals, so it kept the old rose pink
        # when the other three went red - the hand coming down in this
        # scene belonged to a different machine from the one you fight.
        for j, col in enumerate(((58, 122, 224), (248, 206, 58),
                                 (220, 46, 44))):
            pygame.draw.polygon(sc, shade(col, 0.9),
                                [(330 + j * 60, drop - 400),
                                 (370 + j * 60, drop - 400),
                                 (350 + j * 60, drop - 350)])
        if t >= FS_CRUSH_AT:
            g = clamp((t - FS_CRUSH_AT) / 0.7, 0, 1)
            for i in range(26):
                a = i * 0.2417
                r = 40 + g * 460
                pygame.draw.circle(sc, (74, 78, 92),
                                   (int(470 + math.cos(a) * r),
                                    int(596 + math.sin(a) * r * 0.4)),
                                   max(1, int(7 * (1 - g))))

    def _outside(self, sc, t):
        """The general, pulled into a vehicle that does not stop for him."""
        for i in range(0, WIN_H, 4):
            f = i / float(WIN_H)
            sc.fill((int(lerp(58, 104, f)), int(lerp(52, 84, f)),
                     int(lerp(58, 74, f))), (0, i, WIN_W, 4))
        gy = 606
        pygame.draw.rect(sc, (54, 50, 46), (0, gy, WIN_W, WIN_H - gy))
        for d in self.dust:
            d[0] -= d[3] * 60 * (1 / 60.0) * 8
            if d[0] < -40:
                d[0] = WIN_W + 40
            pygame.draw.circle(sc, (86, 80, 72), (int(d[0]), int(d[1])),
                               int(d[2] * 0.5))
        f = clamp((t - FS_OUT_AT) / 4.2, 0, 1)
        vx = 1180 - f * 900
        pygame.draw.rect(sc, (62, 70, 58), (vx - 130, gy - 84, 260, 62),
                         border_radius=10)
        pygame.draw.rect(sc, (44, 50, 42), (vx - 130, gy - 84, 260, 62),
                         3, border_radius=10)
        for wx in (vx - 84, vx + 6, vx + 84):
            pygame.draw.circle(sc, (30, 30, 28), (int(wx), gy - 18), 20)
            pygame.draw.circle(sc, (64, 64, 60), (int(wx), gy - 18), 9)
        # an arm out of the hatch, and the general on the end of it
        pygame.draw.line(sc, (58, 64, 58), (vx - 110, gy - 70),
                         (vx - 186, gy - 40), 12)
        cs_soldier(sc, vx - 200, gy, 78, (36, 40, 36), 2, t)

    def _evac(self, sc, t):
        """Prototype ships, and every soldier left running for one."""
        for i in range(0, WIN_H, 4):
            f = i / float(WIN_H)
            sc.fill((int(lerp(26, 74, f)), int(lerp(30, 66, f)),
                     int(lerp(48, 62, f))), (0, i, WIN_W, 4))
        gy = 616
        pygame.draw.rect(sc, (48, 46, 44), (0, gy, WIN_W, WIN_H - gy))
        lift = clamp((t - FS_LIFT_AT) / 6.0, 0, 1)
        for i, sx in enumerate((250, 660, 1070)):
            up = lift * lift * (420 + i * 90)
            sy = gy - 30 - up
            HULL = (128, 148, 176)
            pygame.draw.polygon(sc, HULL,
                                [(sx, sy - 210), (sx + 62, sy - 60),
                                 (sx + 44, sy), (sx - 44, sy),
                                 (sx - 62, sy - 60)])
            pygame.draw.polygon(sc, (40, 46, 58),
                                [(sx, sy - 210), (sx + 62, sy - 60),
                                 (sx + 44, sy), (sx - 44, sy),
                                 (sx - 62, sy - 60)], 4)
            pygame.draw.circle(sc, (150, 210, 255), (sx, sy - 130), 17)
            # green team built these, and they are the only new thing here
            pygame.draw.polygon(sc, (108, 208, 132),
                                [(sx - 10, sy - 96), (sx + 10, sy - 96),
                                 (sx, sy - 74)])
            if lift > 0:
                for j in range(3):
                    fl = 40 + lift * 150 + j * 26
                    pygame.draw.polygon(
                        sc, (255, int(190 - j * 40), 90),
                        [(sx - 26 + j * 26, sy), (sx - 10 + j * 26, sy),
                         (sx - 18 + j * 26, sy + fl)])
        for (rx, rs, ph) in self.running:
            f = clamp((t - FS_EVAC_AT) / 8.0, 0, 1)
            x = rx + f * 700
            if -60 < x < WIN_W + 60 and lift < 0.4:
                cs_soldier(sc, x, gy, 62 * rs, (30, 32, 32), 1, t + ph)

    def _space(self, sc, t):
        """The sector, seen from above it, going up."""
        sc.fill((10, 11, 20))
        for (sx, sy, sr, ph) in self.stars:
            tw = 0.6 + 0.4 * math.sin(t * 2.0 + ph)
            pygame.draw.circle(sc, (int(190 * tw + 50), int(200 * tw + 50),
                                    int(230 * tw + 25)),
                               (int(sx), int(sy)), max(1, int(sr)))
        f = clamp((t - FS_SPACE_AT) / 8.0, 0, 1)
        # the world below, falling away
        pygame.draw.circle(sc, (44, 70, 96),
                           (int(WIN_W * 0.5), int(WIN_H + 520 - f * 200)),
                           int(700 - f * 120))
        pygame.draw.circle(sc, (70, 108, 138),
                           (int(WIN_W * 0.5), int(WIN_H + 520 - f * 200)),
                           int(700 - f * 120), 6)
        # and the platform, with the guns still on it
        py = WIN_H * 0.60 - f * 120
        pygame.draw.polygon(sc, (58, 62, 76),
                            [(WIN_W * 0.5 - 300, py),
                             (WIN_W * 0.5 + 300, py),
                             (WIN_W * 0.5 + 220, py + 90),
                             (WIN_W * 0.5 - 220, py + 90)])
        pygame.draw.polygon(sc, (34, 36, 46),
                            [(WIN_W * 0.5 - 300, py),
                             (WIN_W * 0.5 + 300, py),
                             (WIN_W * 0.5 + 220, py + 90),
                             (WIN_W * 0.5 - 220, py + 90)], 4)
        for i in range(7):
            gx = WIN_W * 0.5 - 240 + i * 80
            pygame.draw.rect(sc, (86, 92, 110), (gx - 12, py - 26, 24, 26))
            pygame.draw.line(sc, (120, 128, 148), (gx, py - 26),
                             (gx + 22, py - 40), 4)
        for i, sx in enumerate((-420, 0, 420)):
            sy = py - 180 - i * 40 - f * 90
            pygame.draw.polygon(sc, (110, 128, 156),
                                [(WIN_W * 0.5 + sx, sy - 46),
                                 (WIN_W * 0.5 + sx + 20, sy),
                                 (WIN_W * 0.5 + sx - 20, sy)])

    # -- drawing ---------------------------------------------------------
    def draw(self, sc):
        t = self.t
        if t < FS_OUT_AT:
            self._room(sc, t)
            self._figures(sc, t)
            if t >= FS_SHADOW_AT:      # the light goes before anything lands
                k = clamp((t - FS_SHADOW_AT) / 1.4, 0, 1)
                sh = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
                sh.fill((0, 0, 0, int(150 * k)))
                sc.blit(sh, (0, 0))
            if t >= FS_FINGER_AT:
                self._hand(sc, t)
        elif t < FS_EVAC_AT:
            self._outside(sc, t)
        elif t < FS_SPACE_AT:
            self._evac(sc, t)
        else:
            self._space(sc, t)

        for (a, b, line, col) in FS_LINES:
            if a <= t < b:
                fade = min(1.0, (t - a) / 0.4, (b - t) / 0.4)
                bar = pygame.Surface((WIN_W, 78), pygame.SRCALPHA)
                bar.fill((0, 0, 0, int(160 * fade)))
                sc.blit(bar, (0, WIN_H - 132))
                FONTS.draw(sc, line, (WIN_W // 2, WIN_H - 108), 20,
                           shade(col, 0.4 + 0.6 * fade), "center")
        if t >= FS_BLACK_AT:
            k = clamp((t - FS_BLACK_AT) / 2.0, 0, 1)
            sh = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
            sh.fill((0, 0, 0, int(255 * k)))
            sc.blit(sh, (0, 0))
        FONTS.draw(sc, "SPACE / ESC  skip", (WIN_W - 24, WIN_H - 30), 13,
                   (120, 124, 132), "right")



# ---------------------------------------------------------------------------
# AFTER.
#
# The last thing in the game. A time skip, a world that got to stop, and a
# cat with one more thing to say.
# ---------------------------------------------------------------------------
PC_LINES = (
    (3.2, 9.0, "The Triarch fell over the sector it was reaching into."),
    (9.6, 15.4, "Nothing came after it. There was nothing left to come."),
    (16.0, 22.0, "The three flags signed inside a year. Not out of "
                 "friendship - out of arithmetic."),
    (22.6, 28.6, "Green Team stopped building ships to leave with, and "
                 "started building things to stay for."),
    (29.2, 35.0, "The last field is a park. The road you defended is a "
                 "path through it."),
    (35.6, 41.4, "Nobody has fired a shot in eleven years."),
)
PC_SKIP_AT = 1.0           # SEVEN YEARS... then ELEVEN
PC_PARK_AT = 14.0          # the sector, green again
PC_CAT_AT = 43.0           # and one last visitor
PC_CAT_LINES = (
    (45.0, 51.0, "You might want to check the earlier chapters."),
    (51.6, 56.4, "There are things back there nobody found."),
)
PC_BLACK_AT = 58.0
PC_END = 61.0


class PeaceCutscene:
    """The ending. Skippable, plays once, and then the cat says its piece."""

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()
        rnd = random.Random(7000)
        self.trees = [(rnd.uniform(40, WIN_W - 40), rnd.uniform(400, 610),
                       rnd.uniform(0.7, 1.5), rnd.choice((0, 1)))
                      for _ in range(26)]
        self.trees.sort(key=lambda q: q[1])
        self.folk = [(rnd.uniform(60, WIN_W - 60), rnd.uniform(520, 640),
                      rnd.uniform(0.7, 1.0), rnd.uniform(0, 6.28))
                     for _ in range(9)]
        self.birds = [[rnd.uniform(0, WIN_W), rnd.uniform(90, 300),
                       rnd.uniform(14, 34), rnd.uniform(0, 6.28)]
                      for _ in range(7)]

    def skip(self):
        """One press jumps to the cat; a second ends it."""
        if self.t < PC_CAT_AT - 0.4:
            self.t = PC_CAT_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for at, snd in ((PC_PARK_AT, "build"), (PC_CAT_AT, "leak")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        for b in self.birds:
            b[0] += b[2] * dt
            if b[0] > WIN_W + 30:
                b[0] = -30
        if self.t >= PC_END:
            self.done = True

    # -- pieces ----------------------------------------------------------
    def _sky(self, sc, t):
        for i in range(0, WIN_H, 4):
            f = i / float(WIN_H)
            sc.fill((int(lerp(126, 214, f)), int(lerp(168, 210, f)),
                     int(lerp(206, 186, f))), (0, i, WIN_W, 4))
        pygame.draw.circle(sc, (255, 242, 206), (int(WIN_W * 0.78), 148), 62)
        for (bx, by, _sp, ph) in self.birds:
            w = math.sin(t * 6.0 + ph) * 7
            pygame.draw.lines(sc, (86, 96, 110), False,
                              [(bx - 9, by + w), (bx, by - 3),
                               (bx + 9, by + w)], 2)

    def _park(self, sc, t):
        gy = 470
        pygame.draw.rect(sc, (104, 146, 92), (0, gy, WIN_W, WIN_H - gy))
        # the road you spent three hundred waves holding, now a footpath
        pts = [(-40, WIN_H), (300, 690), (500, 600), (760, 556),
               (1040, 512), (WIN_W + 40, 486)]
        for w, col in ((54, (176, 168, 142)), (44, (206, 198, 172))):
            pygame.draw.lines(sc, col, False, pts, w)
        for (tx, ty, ts, kind) in self.trees:
            sway = math.sin(t * 0.8 + tx * 0.02) * 3
            pygame.draw.line(sc, (96, 76, 56), (tx, ty),
                             (tx + sway, ty - 54 * ts), int(7 * ts))
            for j, r in ((0, 34), (1, 26), (2, 18)):
                pygame.draw.circle(
                    sc, (70 + j * 16, 132 + j * 18, 74 + j * 12),
                    (int(tx + sway - 8 + j * 8),
                     int(ty - 54 * ts - 18 * ts + j * 6 * ts)),
                    int(r * ts))
        # Green Team's work: the things they built once they stopped
        # needing to leave. Same triangle that was on the evacuation ships.
        for (mx, my, ms) in ((190, 452, 1.0), (940, 430, 1.3), (620, 418, 0.8)):
            pygame.draw.polygon(sc, (206, 214, 220),
                                [(mx, my - 150 * ms), (mx + 40 * ms, my),
                                 (mx - 40 * ms, my)])
            pygame.draw.polygon(sc, (150, 160, 172),
                                [(mx, my - 150 * ms), (mx + 40 * ms, my),
                                 (mx - 40 * ms, my)], 3)
            pygame.draw.polygon(sc, (108, 208, 132),
                                [(mx, my - 96 * ms), (mx + 16 * ms, my - 62 * ms),
                                 (mx - 16 * ms, my - 62 * ms)])
            # and the arc of them turning, quietly, forever
            for j in range(3):
                a2 = t * 0.9 + j * 2.094
                pygame.draw.line(sc, (188, 198, 208),
                                 (mx, my - 150 * ms),
                                 (mx + math.cos(a2) * 46 * ms,
                                  my - 150 * ms + math.sin(a2) * 46 * ms), 4)
        for (fx, fy, fs, ph) in self.folk:
            cs_soldier(sc, fx, fy, 54 * fs, (58, 62, 70), 2, t + ph)

    def _cat(self, sc, t):
        """It sits on the path and waits for you to notice it."""
        f = clamp((t - PC_CAT_AT) / 1.6, 0, 1)
        gy = 660
        sc_ = 1.5 + 0.9 * f
        draw_calico(sc, WIN_W * 0.5, gy, sc_, t)

    # -- drawing ---------------------------------------------------------
    def draw(self, sc):
        t = self.t
        self._sky(sc, t)
        self._park(sc, t)
        if t >= PC_CAT_AT:
            self._cat(sc, t)

        if PC_SKIP_AT <= t < PC_PARK_AT:
            k = min(1.0, (t - PC_SKIP_AT) / 0.8,
                    (PC_PARK_AT - t) / 1.2)
            FONTS.draw(sc, "ELEVEN YEARS LATER", (WIN_W // 2, 150), 44,
                       shade((250, 250, 244), 0.3 + 0.7 * k), "center")

        lines = PC_LINES + PC_CAT_LINES
        for (a, b, line) in lines:
            if a <= t < b:
                fade = min(1.0, (t - a) / 0.4, (b - t) / 0.4)
                cat = (a, b, line) in PC_CAT_LINES
                bar = pygame.Surface((WIN_W, 74), pygame.SRCALPHA)
                bar.fill((0, 0, 0, int(150 * fade)))
                sc.blit(bar, (0, WIN_H - 126))
                col = (238, 196, 126) if cat else (238, 242, 246)
                FONTS.draw(sc, line, (WIN_W // 2, WIN_H - 104), 20,
                           shade(col, 0.4 + 0.6 * fade), "center")
        if t >= PC_BLACK_AT:
            k = clamp((t - PC_BLACK_AT) / 2.2, 0, 1)
            sh = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
            sh.fill((0, 0, 0, int(255 * k)))
            sc.blit(sh, (0, 0))
        FONTS.draw(sc, "SPACE / ESC  skip", (WIN_W - 24, WIN_H - 30), 13,
                   (90, 100, 96), "right")


class LastSiegeCutscene:
    """The general's last briefing, and what is waiting at the end of it.
    Skippable, plays once."""

    def __init__(self, sounds, music=None):
        self.t = 0.0
        self.sounds = sounds
        self.music = music
        self.done = False
        self.rang = set()
        rnd = random.Random(613)
        # the map on the table: three flags' worth of ground, all of it his
        self.holds = [[rnd.uniform(150, 1130), rnd.uniform(430, 640),
                       rnd.choice([0, 1, 2]), rnd.uniform(0, 6.28)]
                      for _ in range(22)]
        self.dust = [[rnd.uniform(0, WIN_W), rnd.uniform(60, 380),
                      rnd.uniform(5, 18), rnd.uniform(0.9, 2.2)]
                     for _ in range(44)]
        self.staff = [(986, 268), (1092, 250)]

    def skip(self):
        if self.t < LS_EYES_AT - 0.4:
            self.t = LS_EYES_AT - 0.4
        else:
            self.done = True

    def update(self, dt):
        self.t += dt
        for at, snd in ((1.0, "build"), (18.6, "deny"), (31.2, "upgrade"),
                        (43.6, "wave"), (LS_EYES_AT, "leak"),
                        (LS_EYES_AT + 4.2, "zap"),
                        (LS_EYES_AT + 7.6, "boom"),
                        (LS_BLACK_AT, "leak")):
            if self.t >= at and at not in self.rang:
                self.rang.add(at)
                if self.sounds:
                    self.sounds.play(snd)
        if self.t >= LS_END:
            self.done = True

    def draw(self, sc):
        t = self.t
        if t >= LS_BLACK_AT:
            sc.fill((0, 0, 0))
            f = clamp((t - LS_BLACK_AT) / 1.4, 0, 1)
            if f < 1.0:
                self._eyes(sc, 1.0 - f)
            return
        if t >= LS_EYES_AT:
            self._eyes(sc, 1.0)
            return
        self._brief(sc, t)
        FONTS.draw(sc, "SPACE to skip", (WIN_W - 18, WIN_H - 26), 12,
                   (150, 140, 130), "right")

    # ---- the briefing ---------------------------------------------------
    def _brief(self, sc, t):
        sc.fill((16, 19, 24))
        pygame.draw.rect(sc, (24, 29, 35), (0, 0, WIN_W, 400))
        for k in range(0, WIN_W, 148):                 # ribs down the walls
            pygame.draw.rect(sc, (19, 23, 28), (k, 0, 6, 400))
        pygame.draw.rect(sc, (11, 14, 18), (0, 400, WIN_W, WIN_H - 400))
        # the lamp over the table
        pygame.draw.line(sc, (40, 48, 56), (WIN_W // 2, 0),
                         (WIN_W // 2, 104), 4)
        pygame.draw.polygon(sc, (46, 56, 64),
                            [(WIN_W // 2 - 78, 148), (WIN_W // 2 - 28, 102),
                             (WIN_W // 2 + 28, 102), (WIN_W // 2 + 78, 148)])
        pygame.draw.ellipse(sc, (252, 240, 202),
                            (WIN_W // 2 - 78, 138, 156, 20))
        cone = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
        pygame.draw.polygon(cone, (252, 240, 202, 20),
                            [(WIN_W // 2 - 70, 150), (WIN_W // 2 + 70, 150),
                             (WIN_W - 30, 704), (30, 704)])
        sc.blit(cone, (0, 0))
        for d in self.dust:                            # the air in the room
            a2 = clamp(1.0 - abs(d[0] - WIN_W / 2) / (WIN_W / 2), 0, 1)
            if a2 <= 0.05:
                continue
            v = int(70 * a2)
            pygame.draw.circle(sc, (v + 40, v + 40, v + 34),
                               (int(d[0]), int(d[1] + math.sin(t * d[3]) * 6)),
                               max(1, int(d[2] * 0.12)))
        # the table, and the last map on it
        pygame.draw.rect(sc, (34, 44, 50), (110, 400, WIN_W - 220, 288),
                         border_radius=8)
        pygame.draw.rect(sc, (64, 84, 94), (110, 400, WIN_W - 220, 288), 3,
                         border_radius=8)
        glow = pygame.Surface((WIN_W - 220, 288), pygame.SRCALPHA)
        pygame.draw.ellipse(glow, (150, 190, 210, 38),
                            (0, 0, WIN_W - 220, 288))
        sc.blit(glow, (110, 400))
        clip = sc.get_clip()
        sc.set_clip(pygame.Rect(114, 404, WIN_W - 228, 280))
        # three flags' holdings, and the ring closing on all of them
        FLAG = ((196, 58, 46), (232, 182, 38), (64, 118, 206))
        show = clamp((t - 6.0) / 22.0, 0, 1)
        for i2, (hx, hy, side, ph) in enumerate(self.holds):
            if i2 / float(len(self.holds)) > show:
                continue
            col = FLAG[side]
            if side == 0:                    # the Pact, a third of what it was
                col = shade(col, 0.55)
            pygame.draw.circle(sc, col, (int(hx), int(hy)), 9, 2)
            pygame.draw.circle(sc, col, (int(hx), int(hy)), 3)
        if t > 30.0:                         # the ring, drawn last
            r2 = int(150 + 250 * clamp((t - 30.0) / 9.0, 0, 1))
            ring = pygame.Surface((r2 * 2 + 8, r2 * 2 + 8), pygame.SRCALPHA)
            pygame.draw.circle(ring, (232, 96, 84, 150), (r2 + 4, r2 + 4),
                               r2, 4)
            sc.blit(ring, (WIN_W // 2 - r2 - 4, 540 - r2 - 4))
        sc.set_clip(clip)
        FONTS.draw(sc, "THE LAST SECTOR", (WIN_W // 2, 414), 15,
                   (160, 196, 214), "center")
        # the general, and two of his staff behind him
        gx, gy2, H = 190, 700, 378
        arm = -0.58 + math.sin(t * 0.85) * 0.28
        cm_figure(sc, gx + 5, gy2, H, (54, 64, 74), 0.4, arm)      # rim
        cm_figure(sc, gx, gy2, H, (10, 13, 17), 0.4, arm)
        cap_y = gy2 - H * 0.90
        pygame.draw.rect(sc, (10, 13, 17),
                         (gx - H * 0.135, cap_y - H * 0.075,
                          H * 0.27, H * 0.075), border_radius=3)
        pygame.draw.rect(sc, (9, 11, 15),
                         (gx + H * 0.02, cap_y - H * 0.012, H * 0.19,
                          H * 0.02))
        pygame.draw.rect(sc, (196, 168, 84),
                         (gx - H * 0.135, cap_y - H * 0.024, H * 0.27, 4))
        for dy2 in (0.60, 0.565):
            pygame.draw.rect(sc, (196, 168, 84),
                             (gx - H * 0.10, gy2 - H * dy2, H * 0.09, 5))
        for dx in (-0.115, 0.115):
            pygame.draw.rect(sc, (196, 168, 84),
                             (gx + H * dx - 9, gy2 - H * 0.705, 18, 5))
        for sx3, hh2 in self.staff:
            cm_figure(sc, sx3, 700, hh2, (14, 18, 23), 0.1,
                      0.5 + math.sin(t * 0.7 + sx3) * 0.12)
        for a, b, txt in LS_LINES:
            if not (a <= t < b):
                continue
            f = clamp((t - a) / 0.5, 0, 1) * clamp((b - t) / 0.5, 0, 1)
            box = pygame.Surface((WIN_W, 62), pygame.SRCALPHA)
            box.fill((0, 0, 0, int(155 * f)))
            sc.blit(box, (0, WIN_H - 118))
            FONTS.draw(sc, txt, (WIN_W // 2, WIN_H - 100), 21,
                       (int(230 * f), int(228 * f), int(208 * f)), "center")
            break

    # ---- and the three of them ------------------------------------------
    def _eyes(self, sc, a):
        t = self.t
        q = clamp((t - LS_EYES_AT) / 9.0, 0.0, 1.0)
        sc.fill((int(6 * a), int(6 * a), int(8 * a)))
        # They do not open together. Blue first and brightest - it has been
        # waiting longest - then yellow, then the red, which is the dimmest
        # of the three because there is the least of it left.
        EYES = (
            # x, y, colour, when it opens, how bright it burns
            (WIN_W * 0.50, WIN_H * 0.40, (96, 176, 255), 0.00, 1.00),
            (WIN_W * 0.76, WIN_H * 0.55, (238, 194, 52), 0.34, 0.74),
            (WIN_W * 0.24, WIN_H * 0.57, (206, 62, 50), 0.62, 0.46),
        )
        for ex, ey, col, at, bright in EYES:
            f = clamp((q - at) / 0.30, 0.0, 1.0)
            if f <= 0.0:
                continue
            flick = 0.90 + 0.10 * math.sin(t * (3.1 + bright * 2.0) + ex)
            k = a * f * bright * flick
            # the glow it throws, first
            gr = int(210 * f * (0.7 + 0.3 * bright))
            gl = pygame.Surface((gr * 2, gr * 2), pygame.SRCALPHA)
            for i2, rr in enumerate((1.0, 0.66, 0.38)):
                pygame.draw.circle(
                    gl, (int(col[0] * k), int(col[1] * k), int(col[2] * k),
                         int(26 + i2 * 22)),
                    (gr, gr), int(gr * rr))
            sc.blit(gl, (ex - gr, ey - gr))
            # the eye itself: a long slit, wider as it opens
            w2 = 108 * f * (0.8 + 0.3 * bright)
            h2 = 46 * f * (0.8 + 0.3 * bright)
            pygame.draw.ellipse(
                sc, (int(col[0] * k * 0.5), int(col[1] * k * 0.5),
                     int(col[2] * k * 0.5)),
                (ex - w2, ey - h2, w2 * 2, h2 * 2))
            pygame.draw.ellipse(
                sc, (int(col[0] * k), int(col[1] * k), int(col[2] * k)),
                (ex - w2 * 0.82, ey - h2 * 0.78, w2 * 1.64, h2 * 1.56))
            # the pupil, a vertical slit
            pygame.draw.ellipse(sc, (int(8 * a), int(8 * a), int(10 * a)),
                                (ex - w2 * 0.11, ey - h2 * 0.90,
                                 w2 * 0.22, h2 * 1.80))
            # and the shine on it
            sh = min(255, int(255 * k))
            pygame.draw.circle(sc, (sh, sh, sh),
                               (int(ex - w2 * 0.36), int(ey - h2 * 0.38)),
                               max(1, int(7 * f * bright)))
        if q > 0.86:
            fl = clamp((q - 0.86) / 0.14, 0, 1)
            FONTS.draw(sc, "ALL THREE", (WIN_W // 2, WIN_H - 74), 30,
                       (int(226 * a * fl), int(96 * a * fl),
                        int(84 * a * fl)), "center")


REEL = (("THE CORRIDOR", "intro", "seen_intro", "START THE GAME"),
        ("THE SIEGE ENDS", "ending", "seen_ending", "WIN BLOOD RED SIEGE"),
        ("THE FORGE", "forge", "seen_forge", "ENTER CHAPTER THREE"),
        ("VENGEANCE", "vengeance", "seen_vengeance", "WIN BLOOD RED REVENGE"),
        ("THE FOLDER", "command", "seen_command", "ENTER CHAPTER FOUR"),
        ("SECOND SUN", "second", "seen_second", "WIN THE LONG DUSK"),
        ("BLUE SUN", "blue", "seen_blue", "WIN AMBER HORIZON"),
        ("THE QUIET YEARS", "quiet", "seen_quiet", "WIN THE SKY VOYAGE"),
        ("THE LAST SIEGE", "lastsiege", "seen_lastsiege",
         "WIN THE SEA KING"),
        ("THE LAST WAVE", "final", "seen_final",
         "REACH THE LAST WAVE"),
        ("AFTER", "peace", "seen_peace", "WIN THE LAST FIELD"),
        ("THE LIGHTHOUSE", "lighthouse", "seen_lighthouse",
         "FIND THE PRODIGY"),
        ("THE LAUNCH", "launch", "seen_launch",
         "ENTER SECRETS OF THE COSMOS"),
        ("THE ESCAPE", "escape", "seen_escape",
         "WIN SECRETS OF THE COSMOS"))



def hostile_lore(key):
    """What this machine does, read off what it actually has. Derived rather
    than written, so it cannot drift out of step with the thing it
    describes - and every line of it is checkable on the board."""
    d = ENEMY_TYPES[key]
    out = []
    if d.get("loom"):
        out.append("Does not use the road. It stands beyond the sector and "
                   "reaches into it.")
    if d.get("boss"):
        out.append("A finale. One of these ends a tour.")
    # A LOOMING boss has no lane at all, and the delta's boats carry no
    # route marker - on that map the ground route IS the river. So the
    # fallback says "the lane" rather than claiming a road that may be water.
    if not d.get("loom"):
        out.append(("Flies the air corridor." if d.get("air")
                    else "Runs the water lane." if d.get("route") == "water"
                    else "Comes in on the beast track."
                    if d.get("route") == "beast"
                    else "Comes up the lane with the column."))
    if d.get("breaker"):
        b = d["breaker"]
        out.append(f"BREAKER: shoots your emplacements for {b['dmg']:,} "
                   f"every {b['cd']:.1f}s at {b['rng']}px"
                   + (" and rattles the ones beside them."
                      if b.get("shock") else "."))
    if d.get("camo"):
        out.append("Camouflaged. Nothing can shoot it until something "
                   "marks it.")
    if d.get("regen"):
        out.append(f"Heals {d['regen']:,.0f} a second. Chip damage will "
                   f"not do it.")
    if d.get("summons"):
        sm = d["summons"]
        kinds = ", ".join(ENEMY_TYPES[k]["name"] for k, _n in sm["kinds"])
        out.append(f"Brings its own: {kinds}.")
    if d.get("drops"):
        out.append("Something walks out of the wreck.")
    if d.get("splits"):
        out.append("Killing it makes more of them.")
    if d.get("stunner") or d.get("icbm"):
        out.append("Puts your emplacements to sleep.")
    if d.get("steal"):
        out.append("Takes supply out of your account.")
    if d.get("dive"):
        out.append("Dives. It does not pull up.")
    if d.get("dodge"):
        out.append(f"Steps out of the way of {int(d['dodge'] * 100)}% of "
                   f"what is aimed at it.")
    if d.get("shield"):
        out.append("Carries a shield that has to come down first.")
    if d.get("turns_at"):
        out.append(f"Turns over at {int(d['turns_at'] * 100)}% and fights "
                   f"the second half differently.")
    if d.get("vuln"):
        out.append("Only takes damage in the moments after it attacks.")
    if d.get("blocks_air"):
        out.append("Nothing flies over it.")
    if d.get("detect"):
        out.append("Sees what is hidden.")
    if not d.get("air") and d.get("leak", 0) >= 8:
        out.append("Getting past you costs a great deal of integrity.")
    return out


def hostile_tours(key):
    """Which sectors field it - derived from the plans, not a list."""
    out = []
    for t in DIFFICULTIES:
        if t.get("boss") == key or key in (t.get("milestones") or {}).values():
            out.append(t["name"])
    return out


def draw_calico(surf, cx, gy, s, t=0.0, blink=True, main=None, patch=None,
                cream=None, eye=None, crown=None, bow=False, scythe=False):
    """A calico sitting up, seen from the front. Green eyes, because that is
    the part anyone remembers.

    The colours are arguments so the court can come off the same drawing:
    the shape of a cat sitting up is the shape of a cat sitting up, and
    five more copies of it with the numbers changed would be five more
    places to fix the next time the ears move."""
    GING = main or (238, 168, 92)
    DARK = patch or (54, 44, 42)
    CREAM = cream or (248, 244, 236)
    PINK = (232, 150, 168)
    EYE = eye or (126, 214, 118)

    def C(x, y, r, col):
        pygame.draw.circle(surf, col, (int(cx + x * s), int(gy + y * s)),
                           max(1, int(r * s)))

    def P(pts, col):
        pygame.draw.polygon(surf, col, [(cx + a * s, gy + b * s)
                                        for a, b in pts])

    sway = math.sin(t * 1.6) * 2.0
    # the tail, curled round the feet
    pygame.draw.lines(surf, GING, False,
                      [(cx + (16 + i * 5) * s,
                        gy + (-2 - math.sin(t * 1.4 + i * 0.5) * 3
                              - i * i * 0.5) * s) for i in range(7)],
                      max(2, int(3.4 * s)))
    P([(-15, -2), (15, -2), (12, -34), (-12, -34)], GING)     # body
    C(-7, -3, 5, CREAM)                                       # front paws
    C(7, -3, 5, CREAM)
    C(-6, -26, 7, DARK)                                       # coat patches
    C(8, -20, 6, CREAM)
    C(0, -47, 13, GING)                                       # head
    C(6, -50, 6, DARK)
    for sgn in (-1, 1):                                       # ears
        P([(sgn * 4, -56), (sgn * 15, -70), (sgn * 16, -52)], GING)
        P([(sgn * 6, -56), (sgn * 12, -65), (sgn * 13, -55)], PINK)
    shut = blink and (math.sin(t * 0.9) > 0.985)
    for sgn in (-1, 1):                                       # the eyes
        if shut:
            pygame.draw.line(surf, DARK,
                             (cx + (sgn * 5 - 3) * s, gy - 48 * s),
                             (cx + (sgn * 5 + 3) * s, gy - 48 * s),
                             max(1, int(1.6 * s)))
            continue
        C(sgn * 5, -48, 3.6, EYE)
        pygame.draw.ellipse(surf, (22, 40, 24),
                            (cx + (sgn * 5 - 0.9) * s, gy - 51.4 * s,
                             1.8 * s, 6.8 * s))
    C(0, -42, 2.2, PINK)                                      # nose
    for sgn in (-1, 1):                                       # whiskers
        for j in range(3):
            pygame.draw.line(surf, CREAM,
                             (cx + sgn * 3 * s, gy - 42 * s),
                             (cx + sgn * (22 + sway) * s,
                              gy + (-47 + j * 5) * s), max(1, int(s)))
    if bow:                                                   # tied at the neck
        for sgn in (-1, 1):
            P([(0, -33), (sgn * 15, -40), (sgn * 16, -26)], (246, 108, 178))
        C(0, -33, 4, (250, 140, 196))
    if scythe:                                                # over one shoulder
        pygame.draw.line(surf, (74, 62, 58),
                         (cx - 20 * s, gy - 2 * s), (cx + 22 * s, gy - 66 * s),
                         max(2, int(2.6 * s)))
        P([(22, -66), (40, -78), (44, -58), (26, -56)], (216, 226, 238))
    if crown:
        draw_crown(surf, cx, gy - 58 * s, 15 * s, crown,
                   shade(crown, 0.55), blades=5)


def menu_items(profile):
    """The visible menu. EXTRAS stays hidden until the siege has been won -
    it is the reward for finishing the hardest tour in the game."""
    return [it for it in MENU_ITEMS
            if (it[1] != "extras" or "siege" in profile.cleared)
            # the checkpoint row is meaningless until one has been reached
            and (it[1] != "skip" or profile.can_skip())]


# The sector readout on the title screen owns a fixed band along the
# bottom edge, and the list of menu rows is solved against it. It used to
# be the other way round - the readout hung off the end of the list - and
# the list won, walking the readout off the screen. See `draw_title`.
READOUT_PITCH = 19
READOUT_NOTE_LINES = 3
READOUT_W = WIN_W - 180
READOUT_TOP = WIN_H - 32 - (READOUT_NOTE_LINES + 3) * READOUT_PITCH
FLASH_Y = READOUT_TOP - 24          # a reserved row, not a free-floating one
LIST_FLOOR = FLASH_Y - 2


class Menu:
    """Title screen. The background is a real battle the AI plays against
    itself - the same simulation, just with the HUD stripped off."""

    def __init__(self, screen, sounds, profile):
        self.screen = screen
        self.sounds = sounds
        self.profile = profile
        self.index = 0
        self.briefing = False
        self.armoury = False
        self.base_switch = None    # COMMAND's master switch, when drawn
        self.post_switch = None    # ...and which POST is fielded
        self.extras = False
        self.settings = False       # what the game may spend on looking good
        self.set_i = 0
        self.set_rects = []
        self.code_buf = ""          # what is being typed into the code box
        self.code_msg = ""          # ...and what came back from the last one
        self.code_ok = False
        self.dossier = False        # the hostile index
        self.dossier_i = 0
        self.endpick = False        # choose a chapter to hold for ever
        self.end_rects = []
        self.chapters = False
        self.chap_i = 0
        self.extra_i = 0
        self.seal = False           # the Red Capital's unlock, itemised
        self.seal_rect = None       # ...and the line on EXTRAS that opens it
        self.seal_go = None         # ...and its DEPLOY button, once open
        # THE SANDBOX's setup page, reached from EXTRAS. What is picked
        # here is the only thing the workshop is told before it opens.
        self.sandbox = False
        self.sand_row = 0
        self.sand_map = 0
        self.sand_side = 0
        self.sand_post = 0
        self.sand_rects = []
        self.arm_tab = "units"          # "units" | "special"
        self.arm_page = 0               # which page of emplacements is up
        self.arm_pages = 1              # ...set for real once it is drawn
        self.arm_arrows = []
        self.base_page = 0              # which COMMAND section is up
        self.base_arrows = []           # ...and the two buttons that turn it
        self.tab_rects = []
        self.t = 0.0
        self.item_rects = []
        self.card_rects = []
        # what the right button last asked about, as (tab, key)
        self.info_key = None
        self.back_rect = None
        self.flash = ""
        self.flash_t = 0.0
        self.demo = None
        self.new_demo()
        self.scrim = self._make_scrim()
        self.theme_scrim = self._make_theme_scrim()

    def items(self):
        return menu_items(self.profile)

    def tour_theme(self):
        """The dressing for the tour that is selected, or None. Says nothing
        about whether the title screen is the thing on screen."""
        return TITLE_THEMES.get(self.profile.difficulty()["key"])

    def theme(self):
        """...and the same, but only when the title screen is what is being
        looked at. Every other page of the menu is a list to read, and a
        sunset behind it is just something in the way."""
        if (self.armoury or self.chapters or self.endpick or self.dossier
                or self.extras or self.briefing or self.settings
                or self.sandbox or self.seal):
            return None
        return self.tour_theme()

    # -- attract mode ------------------------------------------------------
    def new_demo(self):
        g = Game(self.screen, MUTE)
        rnd = random.Random(11)
        cells = [(c, r) for c in range(COLS) for r in range(ROWS)]
        rnd.shuffle(cells)
        n = 0
        for (c, r) in cells:
            kind = TOWER_ORDER[n % len(TOWER_ORDER)]
            # check the berth the emplacement actually needs: a 2x2 silo does
            # not fit everywhere a 1x1 gun does, and a failed build must not
            # advance the roster or re-upgrade the previous tower
            if not g.can_build(c, r, tower_span(kind), is_naval(kind),
                               is_road_tower(kind)):
                continue
            g.cash = 10 ** 9
            g.build_kind = kind
            before = len(g.towers)
            g.try_build(c, r)
            if len(g.towers) == before:
                continue
            if n % 3 == 0:
                g.selected = g.towers[-1]
                g.do_upgrade()
            n += 1
            if n >= 18:
                break
        g.build_kind = None
        g.selected = None
        g.wave = 7
        g.between = 0.5
        self.demo = g

    def _make_theme_scrim(self):
        """What goes over a themed sky. The ordinary scrim is built to bury
        a board that is mid-firefight; laid over a sunset it buries the
        sunset too. This one only darkens the two bands the lettering and
        the menu actually sit in, and leaves the middle alone."""
        s = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
        for i in range(300):                  # a wash under the lettering
            a = int(168 * ((300 - i) / 300.0) ** 1.5)
            pygame.draw.line(s, (6, 8, 12, a), (0, i), (WIN_W, i))
        # ...and a soft column down the middle. This is the one that
        # matters: several of the six stand a machine dead centre, and the
        # menu list is read straight down on top of it.
        # Built small and scaled up: a hard-edged rectangle of shade was
        # plainly visible as a box over the brighter skies, and feathering
        # it by hand is a per-pixel loop over a megapixel every launch.
        mid, top = int(WIN_W * THEME_MID), 236
        cell = 56
        small = pygame.Surface((cell, cell), pygame.SRCALPHA)
        for yy in range(cell):
            fy = min(1.0, yy / (cell * 0.30))
            for xx in range(cell):
                fx = 1.0 - abs(xx - (cell - 1) / 2.0) / ((cell - 1) / 2.0)
                small.set_at((xx, yy),
                             (5, 7, 11, int(186 * fy * fx ** 0.75)))
        s.blit(pygame.transform.smoothscale(small, (mid * 2, WIN_H - top)),
               (WIN_W // 2 - mid, top))
        for i in range(70):                   # and the faintest of frames
            a = int(52 * ((70 - i) / 70.0) ** 2)
            pygame.draw.rect(s, (4, 6, 8, a),
                             (i, i, WIN_W - 2 * i, WIN_H - 2 * i), 1)
        return s

    def _make_scrim(self):
        s = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
        s.fill((10, 14, 10, 170))
        for i in range(110):          # vignette: darker toward the edges
            a = 170 + int(72 * ((110 - i) / 110.0) ** 2)
            pygame.draw.rect(s, (6, 9, 6, a),
                             (i, i, WIN_W - 2 * i, WIN_H - 2 * i), 1)
        return s

    def update(self, dt):
        self.t += dt
        use_map(self.demo.map_key)
        self.flash_t = max(0.0, self.flash_t - dt)
        d = self.demo
        d.cash = 10 ** 9              # the demo never loses and never stalls
        d.integrity = 10 ** 9
        d.step(dt)
        if d.wave > 15:
            self.new_demo()

    def notify(self, msg):
        self.flash = msg
        self.flash_t = 2.2

    # -- render ------------------------------------------------------------
    def draw(self):
        sc = self.screen
        theme = self.theme()
        if theme:
            # The board is still being played behind this - `update` never
            # stopped stepping the demo - it is simply not what you are
            # looking at while one of the six is selected.
            theme["paint"](sc, self.t)
            sc.blit(self.theme_scrim, (0, 0))
            self.draw_title()
            if self.flash_t > 0:
                FONTS.draw(sc, self.flash, (WIN_W // 2, FLASH_Y), 16,
                           C_BAD if self.flash.startswith("!") else C_GOOD,
                           "center")
            return
        use_map(self.demo.map_key)
        world = self.demo._world
        world.blit(self.demo.terrain, (0, 0))
        self.demo.draw_world(world)
        world = world.subsurface(pygame.Rect(
            int((WORLD_W - MAP_W) // 2), int((WORLD_H - MAP_H) // 2),
            MAP_W, MAP_H))
        scale = max(WIN_W / MAP_W, WIN_H / MAP_H)
        bw, bh = int(MAP_W * scale), int(MAP_H * scale)
        sc.blit(pygame.transform.scale(world, (bw, bh)),
                ((WIN_W - bw) // 2, (WIN_H - bh) // 2))
        sc.blit(self.scrim, (0, 0))
        if self.armoury:
            self.draw_armoury()
            self.draw_info_card()
        elif self.chapters:
            self.draw_chapters()
        elif self.endpick:
            self.draw_endless()
        elif self.dossier:
            self.draw_index()
        elif self.settings:
            self.draw_settings()
        elif self.sandbox:
            self.draw_sandbox()
        elif self.seal:
            self.draw_seal()
        elif self.extras:
            self.draw_extras()
        elif self.briefing:
            self.draw_briefing()
        else:
            self.draw_title()
        if self.flash_t > 0:
            FONTS.draw(sc, self.flash, (WIN_W // 2, FLASH_Y), 16,
                       C_BAD if self.flash.startswith("!") else C_GOOD,
                       "center")
        if self.profile.blood():
            blood_tint(sc)

    def draw_chapters(self):
        sc = self.screen
        cx = WIN_W // 2
        p = self.profile
        FONTS.draw(sc, "CHAPTER SELECT", (cx, 34), 34, C_ACCENT, "center")
        WORDS = ("one", "two", "three", "four", "five", "six", "seven")
        n = len(CHAPTERS)
        FONTS.draw(sc, f"the campaign, in "
                       f"{WORDS[n - 1] if n <= len(WORDS) else n} parts",
                   (cx, 72), 14, C_TEXT_DIM, "center")
        mx, my = pygame.mouse.get_pos()
        self.chap_rects = []
        # The card height is solved for how many chapters there are. It used
        # to be a fixed 168, which put a fourth chapter under the BACK button.
        top, bottom = 116, WIN_H - 96
        # The gap closes before the card does, and NEITHER floor may beat
        # the fit: a sixth chapter at a floor of 84 ran under BACK.
        gap = 14 if n <= 5 else 8
        ch = min(168, (bottom - top - gap * (n - 1)) // n)
        for i, c in enumerate(CHAPTERS):
            r = pygame.Rect(150, top + i * (ch + gap), WIN_W - 300, ch)
            self.chap_rects.append((r, c["key"]))
            open_ = p.chapter_unlocked(c["key"])
            here = p.chapter == c["key"]
            sel = i == self.chap_i
            bg = (34, 40, 30) if open_ else (38, 30, 28)
            if here:
                bg = (48, 58, 38)
            if sel or r.collidepoint(mx, my):
                bg = shade(bg, 1.3)
            pygame.draw.rect(sc, bg, r, border_radius=8)
            edge = C_ACCENT if here else (C_PANEL_LINE if open_ else (96, 58, 50))
            pygame.draw.rect(sc, edge, r, 3 if (here or sel) else 1,
                             border_radius=8)
            # roman numeral block on the left
            pygame.draw.rect(sc, (26, 30, 24), (r.x + 14, r.y + 14, 96, ch - 28),
                             border_radius=6)
            FONTS.draw(sc, roman(c["n"]), (r.x + 62, r.y + ch // 2 - 26),
                       46, C_ACCENT if open_ else (110, 78, 72), "center")
            name_col = C_TEXT if open_ else (150, 120, 112)
            FONTS.draw(sc, c["name"], (r.x + 130, r.y + 16), 26, name_col)
            FONTS.draw(sc, c["sub"], (r.x + 132, r.y + 50), 14,
                       C_TEXT_DIM if open_ else (120, 96, 90))
            tours = chapter_tours(c["key"])
            done = sum(1 for t in tours if t["key"] in p.cleared)
            # Everything below the sub is measured off the BOTTOM of the
            # card, and the tour list is dropped entirely when the card is
            # too short to hold it - at five chapters the cards come down to
            # 100px and a fixed layout put the tally through the subtitle.
            roomy = ch >= 132
            if open_:
                if roomy:
                    FONTS.draw(sc, "  ".join(t["name"] for t in tours),
                               (r.x + 132, r.y + 78), 13, (168, 178, 150))
                bw = 320
                pygame.draw.rect(sc, (24, 26, 22),
                                 (r.x + 132, r.bottom - 24, bw, 8))
                pygame.draw.rect(sc, C_GOOD if done == len(tours) else C_ACCENT,
                                 (r.x + 133, r.bottom - 23,
                                  (bw - 2) * done / max(1, len(tours)), 6))
                FONTS.draw(sc, f"{len(tours)} tours    {done} cleared",
                           (r.x + 132 + bw + 18, r.bottom - 30), 14, C_ACCENT)
            else:
                need = DIFF_BY_KEY[c["opens"]]
                FONTS.draw(sc, "LOCKED", (r.right - 20, r.y + 16), 18, C_BAD,
                           "right")
                FONTS.draw(sc, f"clear {need['name']} to open this chapter",
                           (r.x + 132, r.bottom - 30), 14, (168, 128, 118))
            if here:
                FONTS.draw(sc, "CURRENT", (r.right - 20, r.y + 22), 16,
                           C_ACCENT, "right")
        FONTS.draw(sc, "UP / DOWN choose      ENTER select      ESC back",
                   (cx, WIN_H - 96), 13, C_TEXT_DIM, "center")
        self.back_rect = self._back_button()

    def play_reel(self, i):
        """Ask for a cutscene by index. Returns the action for the app, or
        None and a reason if it has not been earned yet."""
        if not 0 <= i < len(REEL):
            return None
        _title, key, flag, need = REEL[i]
        if not getattr(self.profile, flag, False):
            self.flash = f"! {need} FIRST"
            self.flash_t = 2.0
            self.sounds.play("deny")
            return None
        self.sounds.play("build")
        return "reel:" + key


    def draw_index(self):
        """One hostile to a page: the machine as it appears on the road, what
        it is made of, and what it does. The briefing used to try to fit all
        eighty-seven of these in one column at a five-pixel row pitch."""
        sc = self.screen
        cx = WIN_W // 2
        keys = list(ENEMY_TYPES)
        self.dossier_i %= len(keys)
        k = keys[self.dossier_i]
        d = ENEMY_TYPES[k]

        FONTS.draw(sc, "HOSTILE INDEX", (cx, 44), 30, C_ACCENT, "center")
        FONTS.draw(sc, f"{self.dossier_i + 1} / {len(keys)}", (cx, 80), 14,
                   C_TEXT_DIM, "center")

        plate = pygame.Rect(96, 108, 330, 330)
        pygame.draw.rect(sc, (18, 22, 20), plate)
        pygame.draw.rect(sc, C_PANEL_LINE, plate, 1)
        for i, (dx, dy) in enumerate(((0, 0), (1, 0), (0, 1), (1, 1))):
            px = plate.x + dx * (plate.w - 22) + 2
            py = plate.y + dy * (plate.h - 22) + 2
            pygame.draw.lines(sc, C_ACCENT, False,
                              [(px, py + (18 if not dy else 0)),
                               (px, py) if not dy else (px, py + 18),
                               (px + 18, py) if not dy else
                               (px + 18, py + 18)], 2)

        # the unit itself, top-down, exactly as it is drawn on the board
        try:
            e = Enemy(k, 40, DIFF_BY_KEY.get("hard", DIFFICULTIES[0]),
                      tour_factions(DIFF_BY_KEY.get("hard",
                                                    DIFFICULTIES[0]))[0])
            e.alt = 0
            e.ang = 0.0
            e.spin = self.t * 0.8
            e.loom_t = self.t
            e.hp = e.max_hp
            e.revealed = True
            e.show_edge = False        # no deck to stand at the edge of
            e.size = clamp(e.size, 44.0, 128.0)
            e.x, e.y = plate.centerx, plate.centery
            e.draw(sc)
            shown = e.size
        except Exception:
            shown = d.get("size", 0)
            FONTS.draw(sc, "NO PLATE", (plate.centerx, plate.centery), 15,
                       C_TEXT_DIM, "center")

        x = 470
        col = (C_BAD if d.get("boss") else
               (C_AIR if d.get("air") else C_TEXT))
        FONTS.draw(sc, d.get("full") or d["name"], (x, 112), 26, col)
        lane = ("AIR" if d.get("air") else
                "WATER" if d.get("route") == "water" else
                "BEAST" if d.get("route") == "beast" else "GROUND")
        tag = "  ".join([lane] + (["FINALE"] if d.get("boss") else [])
                        + (["BREAKER"] if d.get("breaker") else [])
                        + (["CAMO"] if d.get("camo") else []))
        FONTS.draw(sc, tag, (x, 144), 13, C_ACCENT)

        rows = [("HP", f"{d['hp']:,}"),
                ("ARMOUR", f"{d['armor']}"),
                ("SPEED", f"{d['spd']}"),
                ("ATTACK", f"{d['atk']:,}"),
                ("BOUNTY", f"${d['bounty']:,}"),
                ("INTEGRITY IF IT PASSES", f"{d.get('leak', 0)}")]
        for i, (a, b) in enumerate(rows):
            ry = 176 + i * 21
            FONTS.draw(sc, a, (x, ry), 13, C_TEXT_DIM)
            FONTS.draw(sc, b, (WIN_W - 110, ry), 14, C_TEXT, "right")

        FONTS.draw(sc, "DOSSIER", (x, 316), 15, C_ACCENT)
        yy = 340
        for line in hostile_lore(k)[:7]:
            yy = self.wrap_at(sc, line, x, yy, WIN_W - 110 - x, 12,
                              C_TEXT_DIM) + 4
        tours = hostile_tours(k)
        if tours:
            FONTS.draw(sc, "ENDS", (x, min(yy + 8, WIN_H - 190)), 15,
                       C_ACCENT)
            self.wrap_at(sc, ", ".join(tours), x,
                         min(yy + 30, WIN_H - 168), WIN_W - 110 - x, 12,
                         C_TEXT)

        FONTS.draw(sc, "<", (60, 268), 34, C_ACCENT)
        FONTS.draw(sc, ">", (WIN_W - 60, 268), 34, C_ACCENT, "right")
        FONTS.draw(sc, "LEFT / RIGHT browse      ESC back",
                   (cx, WIN_H - 96), 13, C_TEXT_DIM, "center")
        self.back_rect = self._back_button()

    def wrap_at(self, sc, txt, x, y, w, size, col):
        """Draw wrapped text and report the y it ended on."""
        f = FONTS.font(size, True)
        line, out = "", []
        for word in txt.split():
            trial = (line + " " + word).strip()
            if f.size(trial)[0] > w and line:
                out.append(line)
                line = word
            else:
                line = trial
        if line:
            out.append(line)
        for i, ln in enumerate(out):
            FONTS.draw(sc, ln, (x, y + i * (size + 4)), size, col)
        return y + len(out) * (size + 4)


    def endless_pool(self):
        """The chapter endless runs, in chapter order, that are open."""
        out = []
        for c in CHAPTERS:
            d = DIFF_BY_KEY.get("endless_" + c["key"])
            if d:
                out.append((c, d))
        return out

    def draw_seal(self):
        """What the Red Capital wants before it opens, tour by tour.

        The four are the LAST ladder sector of chapters one, two, three
        and six - not any tour in them - so the page names each one and
        says so underneath, because that is the part a player cannot work
        out from a count."""
        sc = self.screen
        cx = WIN_W // 2
        p = self.profile
        red = (196, 60, 62)
        FONTS.draw(sc, "THE SEAL", (cx, 34), 38, red, "center")
        FONTS.draw(sc, "WHAT THE RED CAPITAL WANTS BEFORE IT OPENS",
                   (cx, 78), 15, C_TEXT_DIM, "center")
        pygame.draw.line(sc, C_PANEL_LINE, (140, 100), (WIN_W - 140, 100), 1)

        top, h, gap = 124, 84, 12
        for i, (_k, name, ch, have, need) in enumerate(p.capital_progress()):
            r = pygame.Rect(cx - 430, top + i * (h + gap), 860, h)
            done = have >= need
            pygame.draw.rect(sc, (30, 22, 24) if done else (22, 20, 22), r,
                             border_radius=6)
            pygame.draw.rect(sc, red if done else C_PANEL_LINE, r, 1,
                             border_radius=6)
            FONTS.draw(sc, str(ch["n"]) if ch else "-",
                       (r.x + 18, r.centery - 13), 24,
                       red if done else (108, 96, 88))
            FONTS.draw(sc, ch["name"] if ch else "", (r.x + 56, r.y + 12), 20,
                       C_TEXT if done else C_TEXT_DIM)
            FONTS.draw(sc, f"take {name} to the end", (r.x + 56, r.y + 42),
                       13, C_TEXT_DIM)
            FONTS.draw(sc, f"{min(have, need)} / {need}",
                       (r.right - 20, r.y + 10), 22,
                       C_GOOD if done else C_TEXT, "right")
            # five pips, because "3 / 5" is a number and this is a picture
            for j in range(need):
                pr = pygame.Rect(r.right - 20 - (need - j) * 30, r.y + 48,
                                 24, 16)
                if j < have:
                    pygame.draw.rect(sc, C_GOOD if done else C_ACCENT, pr,
                                     border_radius=3)
                else:
                    pygame.draw.rect(sc, (40, 44, 38), pr, border_radius=3)
                    pygame.draw.rect(sc, C_PANEL_LINE, pr, 1, border_radius=3)
            if done:
                FONTS.draw(sc, "TAKEN", (r.x + 470, r.y + 42), 14, C_GOOD)
            else:
                _n = need - have
                FONTS.draw(sc, f"{_n} more clear" + ("" if _n == 1 else "s"),
                           (r.x + 470, r.y + 42), 14, (176, 132, 96))

        _y = top + 4 * (h + gap) + 14
        if p.capital_open():
            FONTS.draw(sc, "THE RED CAPITAL IS OPEN", (cx, _y), 24, red,
                       "center")
            FONTS.draw(sc, "VERMILION BLOOD - 200 waves, and nothing it "
                           "fields dies the first time.",
                       (cx, _y + 34), 14, C_TEXT_DIM, "center")
        else:
            FONTS.draw(sc, f"{p.capital_have()} OF 4 TAKEN"
                           f"      -      {p.capital_left()} CLEARS TO GO",
                       (cx, _y), 24, C_ACCENT, "center")
            FONTS.draw(sc, "Only each chapter's LAST ladder sector counts - "
                           "clearing an earlier tour in the same chapter "
                           "moves nothing here.",
                       (cx, _y + 34), 14, C_TEXT_DIM, "center")
        self.seal_go = None
        if p.capital_open():
            mx, my = pygame.mouse.get_pos()
            r = pygame.Rect(cx - 150, WIN_H - 172, 300, 42)
            hov = r.collidepoint(mx, my)
            pygame.draw.rect(sc, (70, 26, 30) if hov else (48, 20, 24), r,
                             border_radius=4)
            pygame.draw.rect(sc, red, r, 2, border_radius=4)
            FONTS.draw(sc, "DEPLOY", (cx, r.y + 10), 22,
                       (255, 210, 200) if hov else red, "center")
            self.seal_go = r
        FONTS.draw(sc, ("ENTER or [V] deploys      ESC back"
                        if p.capital_open() else "ESC back"),
                   (cx, WIN_H - 122), 13, C_TEXT_DIM, "center")
        self.back_rect = self._back_button()

    def draw_endless(self):
        """One endless run per chapter. Each is that chapter's sector, that
        chapter's army and that chapter's finales, with no finish line - and
        none of them can be cleared, so nothing here unlocks anything."""
        sc = self.screen
        cx = WIN_W // 2
        FONTS.draw(sc, "ENDLESS", (cx, 34), 38, C_ACCENT, "center")
        FONTS.draw(sc, "HOLD UNTIL OVERRUN - PICK YOUR WAR",
                   (cx, 78), 15, C_TEXT_DIM, "center")
        pygame.draw.line(sc, C_PANEL_LINE, (140, 100), (WIN_W - 140, 100), 1)

        mx, my = pygame.mouse.get_pos()
        self.end_rects = []
        pool = self.endless_pool()
        top, gap = 122, 8
        h = min(66, (WIN_H - 210 - top) // max(1, len(pool)) - gap)
        for i, (c, d) in enumerate(pool):
            r = pygame.Rect(cx - 430, top + i * (h + gap), 860, h)
            open_now = self.profile.chapter_unlocked(c["key"])
            hov = r.collidepoint(mx, my) and open_now
            bg = (34, 40, 30) if open_now else (30, 28, 28)
            if hov:
                bg = shade(bg, 1.3)
            pygame.draw.rect(sc, bg, r, border_radius=6)
            pygame.draw.rect(sc, C_ACCENT if open_now else C_PANEL_LINE, r,
                             2 if hov else 1, border_radius=6)
            self.end_rects.append((r, d["key"], open_now))
            FONTS.draw(sc, f"{c['n']}", (r.x + 18, r.centery - 11), 22,
                       C_ACCENT if open_now else (108, 96, 88))
            FONTS.draw(sc, c["name"], (r.x + 54, r.y + 9), 20,
                       C_TEXT if open_now else (120, 104, 98))
            if open_now:
                bosses = endless_bosses(c["key"])
                lead = ", ".join(ENEMY_TYPES[b]["name"] for b in bosses[:3])
                FONTS.draw(sc, f"a boss every {ENDLESS_BOSS_EVERY} waves: "
                               f"{lead}...", (r.x + 54, r.y + 36), 12,
                           C_TEXT_DIM)
                best = self.profile.best.get(d["key"], 0)
                FONTS.draw(sc, (f"BEST  wave {best}" if best else "NEVER HELD"),
                           (r.right - 20, r.centery - 9), 15,
                           C_GOOD if best else C_TEXT_DIM, "right")
            else:
                need = CHAPTER_BY_KEY[c["key"]]["opens"]
                FONTS.draw(sc, f"clear {DIFF_BY_KEY[need]['name']} to open",
                           (r.x + 54, r.y + 36), 12, (150, 116, 108))
                FONTS.draw(sc, "SEALED", (r.right - 20, r.centery - 9), 15,
                           C_BAD, "right")

        FONTS.draw(sc, "Nothing here can be cleared, and nothing here unlocks "
                       "anything - it is the wave count and nothing else.",
                   (cx, WIN_H - 150), 13, C_TEXT_DIM, "center")
        FONTS.draw(sc, "click a war to deploy      ESC back",
                   (cx, WIN_H - 122), 13, C_TEXT_DIM, "center")
        self.back_rect = self._back_button()

    def draw_settings(self):
        """What the game is allowed to spend on looking good.

        The costs on this page are measured rather than guessed, and they
        are printed, because a settings screen that will not say what a
        switch buys is asking the player to test it themselves."""
        sc = self.screen
        cx = WIN_W // 2
        p = self.profile
        FONTS.draw(sc, "SETTINGS", (cx, 34), 38, C_ACCENT, "center")
        FONTS.draw(sc, "the later chapters put a great deal on the board at "
                       "once - this is what to give up first",
                   (cx, 80), 14, C_TEXT_DIM, "center")
        pygame.draw.line(sc, C_PANEL_LINE, (140, 102), (WIN_W - 140, 102), 1)

        self.set_rects = []
        # Solved for however many settings there are. At a fixed 96 the
        # seventh row put SCREEN SHAKE under the code box, and a settings
        # page you cannot read the settings on is a poor settings page.
        _top, _floor = 140, WIN_H - 210
        _step = min(96, max(58, (_floor - _top) // max(1, len(GFX_ROWS))))
        _bh = _step - 10
        _room = _bh >= 76          # is there space for the third line
        y = _top
        for i, (field, label, why) in enumerate(GFX_ROWS):
            sel = (i == self.set_i)
            val = {"detail": p.gfx_detail, "spawns": p.gfx_spawns,
                   "hostiles": p.gfx_hostiles, "crowd": p.gfx_crowd,
                   "shots": p.gfx_shots, "particles": p.gfx_particles,
                   "effects": "ON" if p.gfx_effects else "OFF",
                   "shake": "ON" if p.gfx_shake else "OFF"}[field]
            box = pygame.Rect(220, y, WIN_W - 440, _bh)
            pygame.draw.rect(sc, (18, 22, 20) if sel else (13, 16, 15), box,
                             border_radius=6)
            pygame.draw.rect(sc, C_ACCENT if sel else C_PANEL_LINE, box, 2,
                             border_radius=6)
            FONTS.draw(sc, label, (box.x + 20, box.y + (12 if _room
                                                      else 6)), 20,
                       C_ACCENT if sel else C_TEXT)
            FONTS.draw(sc, why, (box.x + 20, box.y + (40 if _room
                                                    else 29)),
                       13, C_TEXT_DIM)
            if _room:
                FONTS.draw(sc, GFX_NOTE.get(val, ""),
                           (box.x + 20, box.y + 60), 13, C_TEXT_DIM)
            FONTS.draw(sc, f"<  {val}  >",
                       (box.right - 20, box.y + _bh // 2 - 14), 22,
                       C_GOOD if sel else C_TEXT, "right")
            self.set_rects.append((box, field))
            y += _step

        # A plain emplacement is coloured by what it is FOR, since what
        # it looks like is the thing PLAIN gives up. Say so here rather
        # than leaving the player to work six colours out in a firefight.
        FONTS.draw(sc, "drawn plain, an emplacement is coloured by its job:",
                   (cx, y + 2), 13, C_TEXT_DIM, "center")
        NAMES = {"spawner": "PUTS MEN OUT", "support": "SUPPORT",
                 "air": "AIR ONLY", "splash": "AREA",
                 "long": "LONG REACH", "gun": "GUN"}
        wds = [(NAMES[r], c) for r, c in PLAIN_ROLES]
        span = sum(FONTS.font(13).size(t)[0] + 34 for t, _c in wds)
        lx = cx - span // 2
        for txt, col in wds:
            pygame.draw.rect(sc, col, (lx, y + 22, 13, 13),
                             border_radius=3)
            pygame.draw.rect(sc, shade(col, 0.45), (lx, y + 22, 13, 13), 1,
                             border_radius=3)
            FONTS.draw(sc, txt, (lx + 19, y + 22), 13, C_TEXT_DIM)
            lx += FONTS.font(13).size(txt)[0] + 34

        # ...and WHAT is in the frame, because "it is hot" and "there are
        # nine hundred particles" are different problems with different
        # switches, and the numbers are the only way to tell them apart.
        _g = LAST_BOARD
        _load = ""
        if _g is not None:
            _load = (f"      {len(_g.enemies)} hostiles, "
                     f"{len(_g.allies)} friendly, {len(_g.towers)} guns, "
                     f"{len(_g.particles)} particles, "
                     f"{len(_g.projectiles)} rounds")
        FONTS.draw(sc, f"this frame {GFX.frame_ms:5.1f} ms"
                       + ("   -  simplifying" if GFX.busy else "")
                       + _load,
                   (cx, y + 52), 14, C_TEXT_DIM, "center")
        # ---- the code box ------------------------------------------
        box = pygame.Rect(cx - 260, WIN_H - 148, 520, 66)
        pygame.draw.rect(sc, (13, 16, 15), box, border_radius=6)
        pygame.draw.rect(sc, C_PANEL_LINE, box, 2, border_radius=6)
        FONTS.draw(sc, "CODE", (box.x + 18, box.y + 10), 15, C_TEXT_DIM)
        caret = "_" if (pygame.time.get_ticks() // 420) % 2 else " "
        FONTS.draw(sc, (self.code_buf + caret) or caret,
                   (box.x + 18, box.y + 30), 22,
                   C_ACCENT if self.code_buf else C_TEXT_DIM)
        if self.code_msg:
            FONTS.draw(sc, self.code_msg, (box.right - 18, box.y + 32), 14,
                       C_GOOD if self.code_ok else C_BAD, "right")
        else:
            FONTS.draw(sc, "type it and press ENTER",
                       (box.right - 18, box.y + 34), 13, C_TEXT_DIM, "right")
        self.code_rect = box

        FONTS.draw(sc, "UP / DOWN select      LEFT / RIGHT change      "
                       "TYPE a code      ESC back",
                   (cx, WIN_H - 40), 13, C_TEXT_DIM, "center")

    SAND_POSTS = (
        ("THE WAR", "Every programme on the COMMAND screen, at its top "
                    "level."),
        ("THE CAT KINGDOM", "The keep instead, with its own rows maxed - "
                            "and the war's programmes worth nothing, "
                            "exactly as they are in a real tour."))

    def sandbox_rows(self):
        """The three things the workshop is told, and nothing else. A
        sandbox with forty switches on the way in is a settings screen."""
        side = SANDBOX_SIDES[self.sand_side % len(SANDBOX_SIDES)]
        return (("SECTOR",
                 SANDBOX_MAPS[self.sand_map % len(SANDBOX_MAPS)][1],
                 "The ground. Every road in the game is here, whether or "
                 "not the tour that runs it has been beaten.",
                 C_TEXT),
                ("HOSTILES",
                 FACTIONS[side]["name"] if side else "THE WAR",
                 "Whose doctrine the road is running. The deck can still "
                 "put anything at all on it - this is only who ARRIVES.",
                 FACTIONS[side]["col"] if side else C_TEXT),
                ("POST", self.SAND_POSTS[self.sand_post % 2][0],
                 self.SAND_POSTS[self.sand_post % 2][1], C_TEXT))

    def sandbox_turn(self, step):
        r = self.sand_row % 3
        if r == 0:
            self.sand_map = (self.sand_map + step) % len(SANDBOX_MAPS)
        elif r == 1:
            self.sand_side = (self.sand_side + step) % len(SANDBOX_SIDES)
        else:
            self.sand_post = (self.sand_post + step) % 2
        self.sounds.play("build")

    def info_text(self, tab, key):
        """Name, what it does, and the numbers behind it.

        Three different tables answer this question depending on which
        tab is up, so the lookup is here rather than at the draw."""
        p = self.profile
        if tab == "command":
            b = BASE_BY_KEY.get(key)
            if b is None:
                return None
            lvl = p.base_level(key)
            cost = base_cost(key, lvl)
            facts = ["%d of %d marks taken" % (lvl, b["levels"])]
            facts.append("MAXED" if cost is None
                         else "next mark %s RP" % f"{cost:,}")
            locked = p.base_locked(b)
            if locked:
                facts.append(str(locked))
            return b["name"], b["blurb"], facts
        d = TOWER_TYPES.get(key)
        if d is None:
            return None
        facts = []
        if d.get("cost"):
            facts.append("$%s" % f"{d['cost']:,}")
        if d.get("dmg"):
            facts.append("%s damage" % f"{d['dmg']:,}")
        if d.get("cd"):
            facts.append("every %.2fs" % d["cd"])
        if d.get("rng"):
            facts.append("reach %d" % d["rng"])
        if d.get("levels"):
            facts.append("%d marks" % d["levels"])
        if d.get("limit"):
            facts.append("%d to a sector" % d["limit"])
        hits = [w for w, on in (("ground", d.get("hits_ground", True)),
                                ("air", d.get("hits_air", False))) if on]
        if hits:
            facts.append(" and ".join(hits))
        return d["name"], d.get("desc", ""), facts

    def draw_info_card(self):
        """What the right button asked about. Drawn last and over
        everything, because it is the answer to a question that was just
        asked and nothing behind it matters until it is read."""
        if not self.info_key or not self.armoury:
            return
        got = self.info_text(*self.info_key)
        if got is None:
            self.info_key = None
            return
        name, blurb, facts = got
        sc = self.screen
        W, H = 720, 300
        r = pygame.Rect((WIN_W - W) // 2, (WIN_H - H) // 2, W, H)
        lay = pygame.Surface((WIN_W, WIN_H), pygame.SRCALPHA)
        lay.fill((6, 8, 10, 170))
        sc.blit(lay, (0, 0))
        pygame.draw.rect(sc, (24, 28, 22), r, border_radius=10)
        pygame.draw.rect(sc, C_ACCENT, r, 3, border_radius=10)
        FONTS.draw(sc, name, (r.x + 26, r.y + 20), 26, C_ACCENT)
        y = r.y + 62
        f = FONTS.font(15, True)
        line, lines = "", []
        for word in (blurb or "").split():
            test = (line + " " + word).strip()
            if f.size(test)[0] > W - 52 and line:
                lines.append(line)
                line = word
            else:
                line = test
        if line:
            lines.append(line)
        for ln in lines[:9]:
            FONTS.draw(sc, ln, (r.x + 26, y), 15, C_TEXT)
            y += 20
        if facts:
            y = max(y + 10, r.bottom - 54)
            pygame.draw.line(sc, C_PANEL_LINE, (r.x + 26, y - 12),
                             (r.right - 26, y - 12), 1)
            FONTS.draw(sc, "   ".join(facts), (r.x + 26, y), 14, C_TEXT_DIM)
        FONTS.draw(sc, "RIGHT-CLICK ANYWHERE TO PUT IT AWAY",
                   (r.x + 26, r.bottom - 26), 11, C_TEXT_DIM)

    def draw_sandbox(self):
        """The way in. Three choices and a door."""
        sc = self.screen
        cx = WIN_W // 2
        FONTS.draw(sc, "SANDBOX", (cx, 34), 38, C_ACCENT, "center")
        FONTS.draw(sc, "PROVING GROUND - nothing is earned here and "
                       "nothing is lost",
                   (cx, 82), 15, C_TEXT_DIM, "center")
        pygame.draw.line(sc, C_PANEL_LINE, (140, 106), (WIN_W - 140, 106), 1)
        self.sand_rects = []
        mx, my = pygame.mouse.get_pos()
        for i, (label, value, note, col) in enumerate(self.sandbox_rows()):
            r = pygame.Rect(cx - 460, 142 + i * 96, 920, 78)
            self.sand_rects.append(r)
            if r.collidepoint(mx, my) and self.sand_row != i:
                self.sand_row = i
